window.QUESTION_BANK = {"source":"simulado_completo.docx","language":"en","generatedFromOriginalMaterial":true,"totalQuestions":568,"reviewCount":0,"questions":[{"id":"Q001","sourceNumber":1,"duplicateIndex":1,"question":"When does a Guaranteed Insurability Rider allow the insured to buy additional coverage?","options":[{"label":"A","text":"10 year increments"},{"label":"B","text":"at future dates specified in the contract with proof of insurability required"},{"label":"C","text":"at future dates specified in the contract with no evidence of insurability required"},{"label":"D","text":"at any time while policy is active"}],"correctAnswer":"C","explanation":"This rider provides specific dates on which additional life insurance policies can be bought without providing proof of insurabilty.","explanationPt":"Esta cláusula adicional (rider) estabelece datas específicas em que apólices adicionais de seguro de vida podem ser compradas sem a necessidade de comprovar segurabilidade (novo exame de saúde).","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q002","sourceNumber":2,"duplicateIndex":1,"question":"Which of the following policies is characterized by a flexible premium and death benefit and allows the policyowner control of the investment aspect of the plan?","options":[{"label":"A","text":"Variable life"},{"label":"B","text":"Universal life"},{"label":"C","text":"Variable universal life"},{"label":"D","text":"Adjustable life"}],"correctAnswer":"C","explanation":"Any policy whose title includes the term \"Universal\" indicates that the policy has a flexible or adjustable premium. The variable nature of the product indicates that the cash savings value is invested in the stock market (e.g., mutual funds) which permits for a contract owner to decide where equity (i.e., cash value) is to be invested.","explanationPt":"Qualquer apólice cujo título inclua o termo \"Universal\" indica que ela tem um prêmio flexível ou ajustável. A natureza variável do produto indica que o valor em dinheiro acumulado é investido no mercado de ações (por exemplo, fundos mútuos), permitindo que o titular do contrato decida onde o patrimônio (valor em dinheiro) será investido.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q003","sourceNumber":3,"duplicateIndex":1,"question":"A term life insurance policy matures:","options":[{"label":"A","text":"upon endowment of the contract"},{"label":"B","text":"upon death of the insured"},{"label":"C","text":"when the cash value equals the death benefit"},{"label":"D","text":"upon the insured's death during the term of the policy"}],"correctAnswer":"D","explanation":"Term life policies can only mature (pay out the face amount) if death occurs during the term of the policy.","explanationPt":"As apólices de seguro de vida temporário (term life) só podem \"vencer\" (pagar o valor de face) se a morte ocorrer durante o período de vigência da apólice.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q004","sourceNumber":4,"duplicateIndex":1,"question":"The purpose of the ______ Period clause is to avoid an unintentional lapse of a life insurance policy.","options":[{"label":"A","text":"Grace"},{"label":"B","text":"Incontestable"},{"label":"C","text":"Conversion"},{"label":"D","text":"Reinstatement"}],"correctAnswer":"A","explanation":"The purpose of the Grace Period Clause is to avoid an unintentional lapse in a life policy.","explanationPt":"O objetivo da Cláusula do Período de Carência (Grace Period) é evitar o cancelamento não intencional (lapse) de uma apólice de seguro de vida.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q005","sourceNumber":5,"duplicateIndex":1,"question":"Which statement is TRUE in regards to a policy loan?","options":[{"label":"A","text":"Past-due interest payments not paid after 3 months will void the policy"},{"label":"B","text":"Past-due interest on a policy loan is added to the total debt"},{"label":"C","text":"Insurance companies can send delinquent interest accounts to a collection agency"},{"label":"D","text":"Insurance companies can charge an interest rate based on the policyowner's credit report"}],"correctAnswer":"B","explanation":"Interest on a loan which is not paid when due is added to the total debt.","explanationPt":"Os juros de um empréstimo que não são pagos quando vencem são somados ao total da dívida.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q006","sourceNumber":6,"duplicateIndex":1,"question":"Which of the following consists of an offer, acceptance, and consideration?","options":[{"label":"A","text":"Warranty"},{"label":"B","text":"Estoppel"},{"label":"C","text":"Contract"},{"label":"D","text":"Representation"}],"correctAnswer":"C","explanation":"Offer, acceptance, and consideration are all elements of a contract.","explanationPt":"Oferta, aceitação e contraprestação (consideration) são todos elementos de um contrato.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q007","sourceNumber":7,"duplicateIndex":1,"question":"What kind of insurance policy supplies an income stream over a set period of time that starts when the insured dies?","options":[{"label":"A","text":"Family Maintenance Policy"},{"label":"B","text":"Family Income Policy"},{"label":"C","text":"Survivor Policy"},{"label":"D","text":"Family Survivor Policy"}],"correctAnswer":"A","explanation":"A policy that provides an income for a specific period starting at the death of the insured is a Family Maintenance Policy.","explanationPt":"Uma apólice que fornece uma renda por um período específico a partir da morte do segurado é chamada de Apólice de Manutenção Familiar (Family Maintenance Policy).","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q008","sourceNumber":8,"duplicateIndex":1,"question":"A life insurance policy's grace period entitles the insured a period of no less than __ days to make the premium payment.","options":[{"label":"A","text":"25"},{"label":"B","text":"30"},{"label":"C","text":"35"},{"label":"D","text":"40"}],"correctAnswer":"B","explanation":"The grace period for a life insurance policy is never than 30 days.","explanationPt":"O período de carência (grace period) de uma apólice de seguro de vida nunca é inferior a 30 dias.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q009","sourceNumber":9,"duplicateIndex":1,"question":"A life insurance policyowner may sell their policy to a(n) ____ in order to receive a percentage of the policy's face value.","options":[{"label":"A","text":"viatical settlement provider"},{"label":"B","text":"broker"},{"label":"C","text":"insurer"},{"label":"D","text":"viator agent"}],"correctAnswer":"A","explanation":"To receive a percentage of the policy face value, an owner of a life policy may sell the policy to a viatical settlement provider.","explanationPt":"Para receber um percentual do valor de face da apólice, o titular de uma apólice de vida pode vendê-la a uma empresa de liquidação viática (viatical settlement provider).","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q010","sourceNumber":10,"duplicateIndex":1,"question":"What action should a producer take if the initial premium is NOT submitted with the application?","options":[{"label":"A","text":"Keep the application until premium is paid"},{"label":"B","text":"Forward the application to the insurer after giving the applicant a binding receipt"},{"label":"C","text":"Forward the application to the insurer without the initial premium"},{"label":"D","text":"Forward the application to the insurer after giving the applicant a conditional receipt"}],"correctAnswer":"C","explanation":"In this situation, the producer s! without the premium. How premium is not paid with the application, the policy will not become valid until the initial premium is collected.","explanationPt":"Nesta situação, se o prêmio não for pago junto com a proposta, a apólice não se tornará válida até que o prêmio inicial seja cobrado.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q011","sourceNumber":11,"duplicateIndex":1,"question":"All of these insurance products require an agent to have proper FINRA securities registration in order to sell them, EXCEPT for:","options":[{"label":"A","text":"Variable Life"},{"label":"B","text":"Modified Whole Life"},{"label":"C","text":"Universal Variable life"},{"label":"D","text":"Variable Annuity"}],"correctAnswer":"B","explanation":"An agent must have proper FINRA securities registration to sell all of these products EXCEPT Modified Whole Life.","explanationPt":"Um agente deve ter o registro de valores mobiliários apropriado junto à FINRA para vender todos estes produtos, EXCETO o Seguro de Vida Inteira Modificada (Modified Whole Life).","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q012","sourceNumber":12,"duplicateIndex":1,"question":"When is it acceptable to share commissions with another agent?","options":[{"label":"A","text":"as long as both agents are licensed for the same lines of insurance"},{"label":"B","text":"as long as both agents work for the same insurance company."},{"label":"C","text":"as long as both agents are licensed in the same state"},{"label":"D","text":"it is never acceptable"}],"correctAnswer":"A","explanation":"It is acceptable to share commissions as long as both agents are licensed for the same lines of insurance.","explanationPt":"É permitido dividir comissões, desde que ambos os agentes sejam licenciados para os mesmos ramos de seguro.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q013","sourceNumber":13,"duplicateIndex":1,"question":"In life insurance, the needs approach is used mostly to establish:","options":[{"label":"A","text":"which type of life insurance a client should apply for"},{"label":"B","text":"how much life insurance a client should apply for"},{"label":"C","text":"which company a client should use when applying for life insurance"},{"label":"D","text":"what the maximum amount the client can spend on life insurance"}],"correctAnswer":"B","explanation":"The \"needs approach\" in life insurance is most useful in determining the amount of life insurance is most useful in determining the amount of life insurance to be recommended to a client.","explanationPt":"A \"abordagem por necessidades\" (needs approach) no seguro de vida é a mais útil para determinar o valor de seguro de vida a ser recomendado a um cliente.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q014","sourceNumber":14,"duplicateIndex":1,"question":"Which of the following Life insurance policies combine term insurance with an investment element?","options":[{"label":"A","text":"Increasing Term Life"},{"label":"B","text":"Decreasing Term Life"},{"label":"C","text":"Universal Life"},{"label":"D","text":"Graded Life"}],"correctAnswer":"C","explanation":"A universal Life policy combines term insurance and an investment element.","explanationPt":"Uma apólice de Vida Universal combina seguro temporário (term) com um elemento de investimento.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q015","sourceNumber":15,"duplicateIndex":1,"question":"All of the following are Nonforfeiture Options EXCEPT","options":[{"label":"A","text":"Cash Surrender Option"},{"label":"B","text":"Extended Term Option"},{"label":"C","text":"Reduced Paid-Up Option"},{"label":"D","text":"Automatic Premium Loan Option"}],"correctAnswer":"D","explanation":"An automatic premium loan is not considered a Nonforfeiture Option.","explanationPt":"Um empréstimo automático de prêmio (automatic premium loan) não é considerado uma Opção de Não Confisco (Nonforfeiture Option).","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q016","sourceNumber":16,"duplicateIndex":1,"question":"The amount of coverage on a group credit life policy is limited to:","options":[{"label":"A","text":"half of the insureds total loan value"},{"label":"B","text":"the insured’s total loan value"},{"label":"C","text":"75% of the insureds total loan value"},{"label":"D","text":"$25,000"}],"correctAnswer":"B","explanation":"With a group credit life policy, the amount of insurance on the life of a debtor is limited to the total amount of the insured's loan.","explanationPt":"Em uma apólice de seguro de vida em grupo para crédito (group credit life), o valor do seguro sobre a vida do devedor é limitado ao valor total do empréstimo do segurado.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q017","sourceNumber":17,"duplicateIndex":1,"question":"Which statement is TRUE regarding a Variable Whole Life policy?","options":[{"label":"A","text":"A minimum guaranteed Death benefit is provided"},{"label":"B","text":"Itis a combination of an Endowment and a Increasing Term policy"},{"label":"C","text":"Its premiums and benefits are variable"},{"label":"D","text":"Ithas guaranteed dividends"}],"correctAnswer":"A","explanation":"A Variable whole life policy provides a minimum guaranteed death benefit.","explanationPt":"Uma apólice de Vida Inteira Variável (Variable Whole Life) oferece um benefício mínimo garantido por morte.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q018","sourceNumber":18,"duplicateIndex":1,"question":"What advantage does the renewability feature give to a term policy?","options":[{"label":"A","text":"The insured may extend the coverage period at no additional cost"},{"label":"B","text":"The insured may apply for this policy with little or no underwriting"},{"label":"C","text":"The insured may borrow against the cash value"},{"label":"D","text":"The insured may extend the coverage period"}],"correctAnswer":"D","explanation":"The advantage a renewability feature gives to the insured is it allows him/her to extend the coverage period. Usually a premium increase is involved upon renewal.","explanationPt":"A vantagem que a característica de renovabilidade oferece ao segurado é permitir que ele estenda o período de cobertura. Geralmente há um aumento de prêmio na renovação.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q019","sourceNumber":19,"duplicateIndex":1,"question":"The Common Disaster clause provides that if both the insured and the sole named beneficiary were to die in a common accident, which of the following is true?","options":[{"label":"A","text":"This clause provides the payment of proceeds to the insured's estate"},{"label":"B","text":"This clause provides the payment of proceeds to the beneficiary's estate"},{"label":"C","text":"The estate taxes in the insured's estate may be reduced"},{"label":"D","text":"The estate taxes in the beneficiary's estate may be reduced"}],"correctAnswer":"A","explanation":"The Common Disaster clause provides that in the event of simultaneous death, the beneficiary is presumed to die first and therefore the contingent beneficiary 'would be next in line for proceeds. If no contingent beneficiary, then the proceeds would be paid to the insured's estate.","explanationPt":"A cláusula de Desastre Comum (Common Disaster) estabelece que, em caso de morte simultânea, presume-se que o beneficiário morreu primeiro; assim, o beneficiário contingente seria o próximo na linha para receber os valores. Se não houver beneficiário contingente, os valores seriam pagos ao espólio do segurado.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q020","sourceNumber":20,"duplicateIndex":1,"question":"Tom has a qualified retirement plan with his employer that is currently considered to be 80% \"vested\". How can this be interpreted?","options":[{"label":"A","text":"20% of the funds are subject to taxes"},{"label":"B","text":"80% of the funds are invested in a separate account"},{"label":"C","text":"If Tom's employment is terminated, 20% of the funds would be forfeited"},{"label":"D","text":"If Tom's employment is terminated, 80% of the funds would be forfeited"}],"correctAnswer":"C","explanation":"In this situation, 80% \"vested\" means that 20% of the funds could be forfeited if Tom's employment is terminated.","explanationPt":"Nesta situação, 80% \"adquirido\" (vested) significa que 20% dos fundos poderiam ser perdidos caso o emprego de Tom seja encerrado.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q021","sourceNumber":21,"duplicateIndex":1,"question":"K is an agent who made an improper sale of an annuity to a client. Which of the following corrective actions would the Department of Financial Services likely order K to take?","options":[{"label":"A","text":"Sell the client a more appropriate annuity"},{"label":"B","text":"Pay monetary restitution to the client"},{"label":"C","text":"Provide a written apology letter"},{"label":"D","text":"Pay a penalty of three times the client's loss"}],"correctAnswer":"B","explanation":"The Department of Financial order the agent to pay monetary restitution to the client.","explanationPt":"O Departamento de Serviços Financeiros determina que o agente pague uma restituição monetária ao cliente.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q022","sourceNumber":22,"duplicateIndex":1,"question":"All of the following entries are classified under the four principal areas of Florida insurance law EXCEPT:","options":[{"label":"A","text":"An agent's commission"},{"label":"B","text":"Policyowner's rights"},{"label":"C","text":"Policy provisions"},{"label":"D","text":"An agent's licensing requirements"}],"correctAnswer":"A","explanation":"The payment of commissions to the agents is not classified under the four principal areas of Florida insurance law.","explanationPt":"O pagamento de comissões aos agentes não é classificado dentro das quatro áreas principais da legislação de seguros da Flórida.","theme":"Producers and Licensing","jurisdiction":"FL","review":false,"reviewFlags":[]},{"id":"Q023","sourceNumber":23,"duplicateIndex":1,"question":"Any changes made on an insurance application requires the initials of whom?","options":[{"label":"A","text":"Insured"},{"label":"B","text":"Agent"},{"label":"C","text":"Applicant"},{"label":"D","text":"Beneficiary"}],"correctAnswer":"C","explanation":"when an applicant makes a mistake in the information given to an agent in completing the application, the applicant can have the agent correct the information, but the applicant must initial the correction.","explanationPt":"Quando um proponente comete um erro nas informações fornecidas a um agente ao preencher a proposta, ele pode pedir ao agente para corrigir a informação, mas deve rubricar (assinar com as iniciais) a correção.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q024","sourceNumber":24,"duplicateIndex":1,"question":"In what year was The Florida Office of Financial Regulation (OFR) created?","options":[{"label":"A","text":"1983"},{"label":"B","text":"1993"},{"label":"C","text":"2003"},{"label":"D","text":"2013"}],"correctAnswer":"C","explanation":"The OFR was created in 2003 as the result of the Cabinet Reorganization Act of 2002.","explanationPt":"O OFR (Office of Financial Regulation) foi criado em 2003 como resultado da Lei de Reorganização do Gabinete (Cabinet Reorganization Act) de 2002.","theme":"Producers and Licensing","jurisdiction":"FL","review":false,"reviewFlags":[]},{"id":"Q025","sourceNumber":25,"duplicateIndex":1,"question":"Whole Life insurance policies are contractually guaranteed to provide each of the following, EXCEPT:","options":[{"label":"A","text":"cash value that will ultimately replace the death benefit"},{"label":"B","text":"nonforfeiture benefit options"},{"label":"C","text":"premiums that remain fixed for the life of the policy"},{"label":"D","text":"partial withdrawal features beyond a surrender charge period"}],"correctAnswer":"D","explanation":"de Correct. All of these are contractually guaranteed to be provided in a whole life insurance policy EXCEPT \"partial withdrawal features beyond a surrender charge period\"","explanationPt":"Todos estes itens são contratualmente garantidos em uma apólice de seguro de vida inteira (whole life), EXCETO \"recursos de retirada parcial além do período de taxa de resgate (surrender charge)\".","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q026","sourceNumber":26,"duplicateIndex":1,"question":"Which of the following is considered an element of a Variable Life Policy?","options":[{"label":"A","text":"Underlying equity investment"},{"label":"B","text":"Little or no risk to insured"},{"label":"C","text":"Guaranteed dividends"},{"label":"D","text":"Insurer assumes all the risk"}],"correctAnswer":"A","explanation":"One characteristic of a Variable Life policy is it contains an underlying equity investment.","explanationPt":"Uma característica de uma apólice de Vida Variável é que ela contém um investimento subjacente em ações (equity).","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q027","sourceNumber":27,"duplicateIndex":1,"question":"Who is NOT required to sign a life insurance application?","options":[{"label":"A","text":"Adult insured"},{"label":"B","text":"Policyowner"},{"label":"C","text":"Agent"},{"label":"D","text":"Beneficiary"}],"correctAnswer":"D","explanation":"All of the following individuals must sign a life insurance application EXCEPT the beneficiary.","explanationPt":"Todos os indivíduos a seguir devem assinar uma proposta de seguro de vida, EXCETO o beneficiário.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q028","sourceNumber":28,"duplicateIndex":1,"question":"What action can a policyowner take if an application for a bank loan requires collateral?","options":[{"label":"A","text":"Utilize accelerated benefits provision"},{"label":"B","text":"Borrow against policy cash value and use as a down payment."},{"label":"C","text":"Assign policy ownership to the bank"},{"label":"D","text":"Name bank as beneficiary"}],"correctAnswer":"C","explanation":"A policeowner may assign ownership of the policy to a bank as collateral.","explanationPt":"O titular de uma apólice pode ceder a titularidade da apólice a um banco como garantia (colateral).","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q029","sourceNumber":29,"duplicateIndex":1,"question":"An agent that sells ____ Life insurance MUST be registered with the Financial Industry Regulatory Authority (FINRA).","options":[{"label":"A","text":"Variable"},{"label":"B","text":"Straight"},{"label":"C","text":"Universal"},{"label":"D","text":"Credit"}],"correctAnswer":"A","explanation":"An agent is required to register with the Financial Industry Regulatory Authority (FINRA) in order to sell Variable Life insurance policies.","explanationPt":"Um agente precisa se registrar na FINRA (Financial Industry Regulatory Authority) para vender apólices de seguro de Vida Variável.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q030","sourceNumber":30,"duplicateIndex":1,"question":"What is the initial source of underwriting for an insurance policy?","options":[{"label":"A","text":"Application containing statements from the insured"},{"label":"B","text":"MIB report"},{"label":"C","text":"Credit report"},{"label":"D","text":"Medical exam"}],"correctAnswer":"A","explanation":"The initial source of underwriting for an insurance policy is the application containing statements from the insured.","explanationPt":"A fonte inicial de subscrição (underwriting) de uma apólice de seguro é a proposta, que contém as declarações do segurado.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q031","sourceNumber":31,"duplicateIndex":1,"question":"Which of these is an element of a Variable Life policy?","options":[{"label":"A","text":"A fixed, level premium"},{"label":"B","text":"Insurer assumes the investment risk"},{"label":"C","text":"No investment risk to the policyowner"},{"label":"D","text":"Rate of returns are guaranteed"}],"correctAnswer":"A","explanation":"Variable Whole Life policies have a fixed, level premium.","explanationPt":"As apólices de Vida Inteira Variável (Variable Whole Life) têm um prêmio fixo e nivelado.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q032","sourceNumber":32,"duplicateIndex":1,"question":"The most important factor to consider when determining whether to convert term insurance at the insured's attained age or the insured's original age is:","options":[{"label":"A","text":"the cost"},{"label":"B","text":"the health of the insured"},{"label":"C","text":"the amount of coverage being converted"},{"label":"D","text":"who will be beneficiary"}],"correctAnswer":"A","explanation":"The cost of insurance is most important when an insured owner is trying to decide whether to convert term insurance original age or the insured's attained age.","explanationPt":"O custo do seguro é mais importante quando um segurado está decidindo se deve converter um seguro temporário (term) pela idade original ou pela idade atingida (attained age).","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q033","sourceNumber":33,"duplicateIndex":1,"question":"Which factors are taken into consideration when an insurance company determines the premium rate for a Whole Life policy on an applicant?","options":[{"label":"A","text":"Geographical location"},{"label":"B","text":"Source of income"},{"label":"C","text":"Risk classification"},{"label":"D","text":"Marital status"}],"correctAnswer":"C","explanation":"To determine the premium rate on a Whole Life policy, an insurance will consider the risk classification of the applicant.","explanationPt":"Para determinar a taxa de prêmio de uma apólice de Vida Inteira, a seguradora considerará a classificação de risco do proponente.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q034","sourceNumber":34,"duplicateIndex":1,"question":"A Cost of Living rider gives the insured","options":[{"label":"A","text":"tax incentives"},{"label":"B","text":"monthly income"},{"label":"C","text":"decreasing premiums"},{"label":"D","text":"additional death benefits"}],"correctAnswer":"D","explanation":"The cost of living rider can be purchased with many different types of life insurance. This type of coverage is designed to help you hedge your bets against inflation. For example, if you purchase this rider, your policy is going to increase in value if inflation increases.","explanationPt":"A cláusula adicional de custo de vida (cost of living rider) pode ser adquirida com diversos tipos de seguro de vida. Esta cobertura ajuda a proteger contra a inflação: se você adquirir esta cláusula, o valor da sua apólice aumentará se a inflação aumentar.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q035","sourceNumber":35,"duplicateIndex":1,"question":"Which of the following does Social Security NOT provide benefits for?","options":[{"label":"A","text":"Survivorship"},{"label":"B","text":"Dismemberment"},{"label":"C","text":"Disability"},{"label":"D","text":"Retirement"}],"correctAnswer":"B","explanation":"Social Security provides for all of these types of benefits EXCEPT dismemberment.","explanationPt":"O Seguro Social (Social Security) prevê todos estes tipos de benefícios, EXCETO desmembramento.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q036","sourceNumber":36,"duplicateIndex":1,"question":"Before a life policy is issued, which of these contract elements is necessary?","options":[{"label":"A","text":"A signed application by the prospect"},{"label":"B","text":"A minimum amount of coverage"},{"label":"C","text":"A beneficiary's signature on an application"},{"label":"D","text":"Abinding receipt"}],"correctAnswer":"C","explanation":"A prospect's signature on an application is necessary before a life policy will be issued.","explanationPt":"A assinatura do proponente na proposta é necessária antes que uma apólice de vida seja emitida.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q037","sourceNumber":37,"duplicateIndex":1,"question":"Which of the following are Equity Indexed annuities typically invested in?","options":[{"label":"A","text":"Corporate Bonds"},{"label":"B","text":"Money Market accounts"},{"label":"C","text":"Municipal Bonds"},{"label":"D","text":"S&P 500"}],"correctAnswer":"D","explanation":"An indexed annuity is a type of tax-deferred annuity whose credited interest is linked to an equity index — typically the S&P500.","explanationPt":"Uma anuidade indexada é um tipo de anuidade com imposto diferido cujos juros creditados estão vinculados a um índice de ações — tipicamente o S&P 500.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q038","sourceNumber":38,"duplicateIndex":1,"question":"A life insurance arrangement which circumvents insurable interest statutes is called:","options":[{"label":"A","text":"a contract of adhesion"},{"label":"B","text":"an indemnity contract"},{"label":"C","text":"key person insurance"},{"label":"D","text":"Investor-Originated Life Insurance"}],"correctAnswer":"D","explanation":"Investor-originated i'g insurance (or IOLl) is used to circumvent state insurable interest statutes. This is done when an investor (or stranger) persuades an individual to take out life insurance specifically for the purpose of selling the policy to the investor. The investor compensates the insured and makes the premiums, then collects the death benefit when the insured dies.","explanationPt":"O seguro de vida originado por investidor (Investor-Originated Life Insurance, IOLI) é usado para contornar as leis estaduais de interesse segurável. Isso ocorre quando um investidor (ou estranho) convence um indivíduo a contratar um seguro de vida com o propósito específico de vender a apólice a esse investidor. O investidor compensa o segurado e paga os prêmios, recebendo o benefício por morte quando o segurado falece.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q039","sourceNumber":39,"duplicateIndex":1,"question":"An applicant who pays the initial premium at the time of application is typically given a(n)","options":[{"label":"A","text":"official receipt"},{"label":"B","text":"conditional receipt"},{"label":"C","text":"binding receipt"},{"label":"D","text":"certified receipt"}],"correctAnswer":"B","explanation":"A conditional receipt is normally given to an applicant who pays the initial premium at the time of application.","explanationPt":"Um recibo condicional (conditional receipt) normalmente é entregue ao proponente que paga o prêmio inicial no momento da proposta.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q040","sourceNumber":40,"duplicateIndex":1,"question":"Company Z has a Cross Purchase Buy-Sell Agreement in place among its three founding partners. If the agreement is funded with individual life insurance, what would it require?","options":[{"label":"A","text":"One policy is owned and paid for by the company"},{"label":"B","text":"Each partner must own a policy on the other partners"},{"label":"C","text":"One policy is owned by the company and premiums are split equally among the partners"},{"label":"D","text":"Each partner owns their own individual policy"}],"correctAnswer":"B","explanation":"In this situation, each partner must own a policy on the other partners.","explanationPt":"Nesta situação, cada sócio deve possuir uma apólice sobre a vida dos demais sócios.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q041","sourceNumber":41,"duplicateIndex":1,"question":"Which entity approves the insurance policy forms used in Florida?","options":[{"label":"A","text":"National Association of Insurance Commissioners (NAIC)"},{"label":"B","text":"Department of Financial Services (DFS)"},{"label":"C","text":"Financial Services Commission (FSC)"},{"label":"D","text":"Office of insurance Regulation (OIR)"}],"correctAnswer":"D","explanation":"The insurance policy forms used in Florida are approved by the Office of Insurance Regulation (OIR).","explanationPt":"Os formulários de apólices de seguro usados na Flórida são aprovados pelo Escritório de Regulação de Seguros (Office of Insurance Regulation, OIR).","theme":"Life Insurance Policies","jurisdiction":"FL","review":false,"reviewFlags":[]},{"id":"Q042","sourceNumber":42,"duplicateIndex":1,"question":"Consumer reports requested by an underwriter during the application process of a life insurance policy can be used to determine:","options":[{"label":"A","text":"driving history"},{"label":"B","text":"probability of making timely premium payments"},{"label":"C","text":"if applicant is a tobacco user"},{"label":"D","text":"overall health of the applicant"}],"correctAnswer":"B","explanation":"The purpose of these reports is to provide a picture of an applicant’s general character and reputation, mode of living, finances, and any exposure to abnormal hazards.","explanationPt":"O objetivo destes relatórios é fornecer um retrato do caráter geral e da reputação do proponente, seu modo de vida, situação financeira e qualquer exposição a riscos anormais.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q043","sourceNumber":43,"duplicateIndex":1,"question":"P purchases a $50,000 whole life insurance policy in 2005. One of the questions on the application asks if P engages in scuba diving, to which P answers \"No\". The policy is then issued with no scuba exclusions. In 2010, P takes up scuba diving and dies in a scuba-related accident in 2011. What will the insurer pay to P's beneficiary?","options":[{"label":"A","text":"Premiums paid plus interest"},{"label":"B","text":"Nothing. Claim will be denied"},{"label":"C","text":"$50,000 minus any outstanding policy loans"},{"label":"D","text":"$100,000 because the cause of death was accidental"}],"correctAnswer":"C","explanation":"In this situation, the beneficiary will receive $50,000 less any outstanding loans and interest. At the time of the insured's death, the policy is beyond the contestable period.","explanationPt":"Nesta situação, o beneficiário receberá $50.000, deduzidos quaisquer empréstimos e juros pendentes. No momento da morte do segurado, a apólice já está fora do período de contestabilidade.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q044","sourceNumber":44,"duplicateIndex":1,"question":"The investment gains from a Universal Life Policy usually go toward:","options":[{"label":"A","text":"the death benefit"},{"label":"B","text":"the dividends"},{"label":"C","text":"the cash value"},{"label":"D","text":"paying off a policy loan"}],"correctAnswer":"C","explanation":"In a Universal Life Policy, income is usually directed toward the cash value.","explanationPt":"Em uma apólice de Vida Universal, os rendimentos são geralmente direcionados para o valor em dinheiro (cash value).","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q045","sourceNumber":45,"duplicateIndex":1,"question":"The Consideration clause in a life insurance contract contains what pertinent information?","options":[{"label":"A","text":"Summary of benefits"},{"label":"B","text":"Offer and acceptance"},{"label":"C","text":"Entire Contract"},{"label":"D","text":"Amount of premium payments and when they are due"}],"correctAnswer":"D","explanation":"The Consideration clause in a life insurance policy specifies the amount and frequency of premium payments that the policyowner must make to keep the insurance in force.","explanationPt":"A Cláusula de Contraprestação (Consideration Clause) em uma apólice de seguro de vida especifica o valor e a frequência dos pagamentos de prêmio que o titular deve fazer para manter o seguro em vigor.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q046","sourceNumber":46,"duplicateIndex":1,"question":"According to Florida law, which of the following statements accurately describes an admitted mail order insurance company?","options":[{"label":"A","text":"It may solicit insurance business by mail without the assistance of a licensed agent"},{"label":"B","text":"It may solicit insurance business by mail only with the assistance of a licensed Florida agent"},{"label":"C","text":"Admitted mail order insurance companies are illegal in Florida"},{"label":"D","text":"Admitted mail order insurance companies cannot solicit insurance business outside the state of Florida"}],"correctAnswer":"A","explanation":"The correct answer is \"It may solicit insurance business by mail without the assistance of a licensed agent”. An admintted mail order insurance company may solicit and accept business by mail without the aid of a licensed agent.","explanationPt":"A resposta correta é \"Pode angariar negócios de seguro pelo correio sem a assistência de um agente licenciado\". Uma seguradora de venda por correspondência devidamente autorizada pode angariar e aceitar negócios pelo correio sem o auxílio de um agente licenciado.","theme":"Producers and Licensing","jurisdiction":"FL","review":false,"reviewFlags":[]},{"id":"Q047","sourceNumber":47,"duplicateIndex":1,"question":"A provision in a life insurance policy that pays the policyowner an amount that does not surpass the guaranteed cash value is called the:","options":[{"label":"A","text":"Policy Loan provision"},{"label":"B","text":"Automatic Premium Loan provision"},{"label":"C","text":"Accelerated Benefits provision"},{"label":"D","text":"Consideration clause"}],"correctAnswer":"A","explanation":"A policy loan will pay the policyowner an amount that, with interest, does NOT exceed the guaranteed cash value.","explanationPt":"Um empréstimo sobre a apólice pagará ao titular um valor que, somado aos juros, NÃO excederá o valor em dinheiro garantido.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q048","sourceNumber":48,"duplicateIndex":1,"question":"Which of the following is a standard provision of the conversion privileges in a Group Life policy?","options":[{"label":"A","text":"Group Life coverage can only be converted if the employer pays for the individual policy"},{"label":"B","text":"Group Life coverage can normally be converted to an individual policy within 6 months"},{"label":"C","text":"Group Life coverage can only be converted by providing evidence of insurability"},{"label":"D","text":"Group Life coverage can be converted to an individual policy at regular rates on an attained-age basis"}],"correctAnswer":"D","explanation":"Conversion at regular rates on an attained-age basis without a medical exam is a standard provision for conversion privileges in Group Life policies.","explanationPt":"A conversão a taxas regulares com base na idade atingida (attained-age), sem exame médico, é uma disposição padrão para os privilégios de conversão em apólices de Vida em Grupo.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q049","sourceNumber":49,"duplicateIndex":1,"question":"How can an agent-in-charge have more than one location?","options":[{"label":"A","text":"Only if the locations are in Florida"},{"label":"B","text":"By keeping all locations within a close proximity"},{"label":"C","text":"An agent-in-charge can only have one location"},{"label":"D","text":"Only if the agent-in-charge is present when insurance activity occurs"}],"correctAnswer":"D","explanation":"Multiple locations are allowed as long as the agent-in-charge is present when insurance activity occurs.","explanationPt":"Múltiplos locais são permitidos, desde que o agente responsável esteja presente quando ocorrer a atividade de seguro.","theme":"Producers and Licensing","jurisdiction":"FL","review":false,"reviewFlags":[]},{"id":"Q050","sourceNumber":50,"duplicateIndex":1,"question":"How would a contingent beneficiary receive the policy proceeds in an Accidental Death and dismemberment (AD&D) policy?","options":[{"label":"A","text":"If the primary beneficiary is a minor at the time of the insured's death"},{"label":"B","text":"If the primary beneficiary dies before the insured"},{"label":"C","text":"If the insured died of accidental causes"},{"label":"D","text":"If the insured died of natural causes"}],"correctAnswer":"B","explanation":"A contingent beneficiary will receive the policy proceeds if the primary beneficiary dies before the insured's death.","explanationPt":"Um beneficiário contingente receberá os valores da apólice se o beneficiário principal falecer antes da morte do segurado.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q051","sourceNumber":51,"duplicateIndex":1,"question":"In Florida, an element of an insurance transaction would be","options":[{"label":"A","text":"ordering an MIB report"},{"label":"B","text":"setting up the sales appointment"},{"label":"C","text":"issuing an insurance contract"},{"label":"D","text":"determining how much coverage is needed"}],"correctAnswer":"C","explanation":"The inssuance of an insurance contract is considered to be an element of an insurance transaction.","explanationPt":"A emissão de um contrato de seguro é considerada um elemento de uma transação de seguro.","theme":"Producers and Licensing","jurisdiction":"FL","review":false,"reviewFlags":[]},{"id":"Q052","sourceNumber":52,"duplicateIndex":1,"question":"Which type of plan allows an employer to give money to an employee for buying a life insurance policy and also permits the employee to select the beneficiary?","options":[{"label":"A","text":"Split-dollar plan"},{"label":"B","text":"Employer purchase plan"},{"label":"C","text":"Key employee plan"},{"label":"D","text":"Deferred compensation plan"}],"correctAnswer":"A","explanation":"A split-dollar plan is an arrangement where an employer and an employee share in the cost of purchasing a life insurance policy on the employee. The employee is also allowed to name the policy beneficiary.","explanationPt":"Um plano \"split-dollar\" é um arranjo no qual o empregador e o empregado dividem o custo da compra de uma apólice de seguro de vida sobre o empregado. O empregado também pode indicar o beneficiário da apólice.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q053","sourceNumber":53,"duplicateIndex":1,"question":"All of the following will result in the suspension of an agent's license EXCEPT","options":[{"label":"A","text":"intentionally misrepresenting the provisions of a policy"},{"label":"B","text":"acting with fiduciary responsibility"},{"label":"C","text":"forging a name on an insurance application"},{"label":"D","text":"being convicted of a felony"}],"correctAnswer":"B","explanation":"Acting as a fiduciary would not result in suspension of an agent's license.","explanationPt":"Atuar como fiduciário não resultaria na suspensão da licença de um agente.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q054","sourceNumber":54,"duplicateIndex":1,"question":"J owns a business and has a Group Life policy covering her employees. J decides to cancel the policy by letting it lapse on the renewal date. What action must be taken?","options":[{"label":"A","text":"J must cover the group with another policy at cancellation"},{"label":"B","text":"All of the employees must be notified of the cancellation either by the insurance company or through J"},{"label":"C","text":"The insurance company must replace the existing policy with one to J's liking"},{"label":"D","text":"No obligation is required from either the insurance company nor J"}],"correctAnswer":"B","explanation":"When a Group Life policy is cancelled or allowed to lapse, the employees covered under the policy must be notified of the cancellation. This notice may be provided by the insurance company or through the employer/policyholder, so employees are aware that their group coverage is ending.","explanationPt":"Quando uma apólice de Vida em Grupo é cancelada ou deixa de vigorar, os funcionários cobertos devem ser notificados do cancelamento. Este aviso pode ser dado pela seguradora ou pelo empregador/titular da apólice, para que os funcionários saibam que sua cobertura em grupo está terminando.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q055","sourceNumber":55,"duplicateIndex":1,"question":"Which of the following situations does NOT apply to the Florida Replacement Rule?","options":[{"label":"A","text":"An existing policy is reissued with a reduction in cash value"},{"label":"B","text":"A new policy is issued while an existing one is surrendered"},{"label":"C","text":"An existing policy is subject to extensive borrowing"},{"label":"D","text":"An existing policyholder purchases an additional policy from the same insurer"}],"correctAnswer":"D","explanation":"Florida's Replacement Rule applies to all of these situations EXCEPT \"An existing policyholder purchases an additional policy from the same insurer.","explanationPt":"A Regra de Substituição (Replacement Rule) da Flórida se aplica a todas estas situações, EXCETO \"um titular de apólice existente compra uma apólice adicional da mesma seguradora\".","theme":"Ethics and Compliance","jurisdiction":"FL","review":false,"reviewFlags":[]},{"id":"Q056","sourceNumber":56,"duplicateIndex":1,"question":"Which statement about a whole life policy is true?","options":[{"label":"A","text":"Beneficiary may be changed only with the consent of the premium payor"},{"label":"B","text":"Death benefit can usually be adjusted"},{"label":"C","text":"Cash value may be borrowed against"},{"label":"D","text":"Premiums are flexible"}],"correctAnswer":"C","explanation":"One feature of whole life policies is that the policyowner may borrow against the cash value.","explanationPt":"Uma característica das apólices de vida inteira é que o titular pode tomar empréstimo contra o valor em dinheiro.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q057","sourceNumber":57,"duplicateIndex":1,"question":"When a misrepresentation on a life insurance policy application is discovered, what action may an insurance company take?","options":[{"label":"B","text":"Void the policy if found during the Contestable period"},{"label":"C","text":"Void the policy, no matter when it is discovered"},{"label":"D","text":"Void the policy at any time only if itis found to be material"},{"label":"E","text":"Void the policy only if itis discovered during the Contestable period and proven to be material"}],"correctAnswer":"E","explanation":"An insurer may void the policy only if the misrepresentation is discovered during the Contestable period and proven to be material.","explanationPt":"Uma seguradora só pode anular a apólice se a declaração falsa (misrepresentation) for descoberta durante o período de contestabilidade e for comprovadamente material.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q058","sourceNumber":58,"duplicateIndex":1,"question":"Which of the following is TRUE about a qualified retirement that is \"top heavy\"?","options":[{"label":"A","text":"More than 30% of plan assets are in key employee accounts"},{"label":"B","text":"More than 40% of annual additions are for key employee accounts"},{"label":"C","text":"More than 50% of plan assets are in key employee accounts"},{"label":"D","text":"More than 60% of plan assets are in key employee accounts"}],"correctAnswer":"D","explanation":"A plan is considered to be top heavy if more than 60% of plan assets are attributable to \"key employees\" as of the last day of the prior plan year.","explanationPt":"Um plano é considerado \"top heavy\" (concentrado no topo) se mais de 60% dos ativos do plano forem atribuíveis a \"funcionários-chave\" no último dia do ano anterior do plano.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q059","sourceNumber":59,"duplicateIndex":1,"question":"A life policy with a death benefit and cash value that can fluctuate according to the performance of its underlying investment portfolio is referred to as:","options":[{"label":"A","text":"Adjustable Life"},{"label":"B","text":"Graded-Premium Life"},{"label":"C","text":"Variable Life"},{"label":"D","text":"Modified Whole Life"}],"correctAnswer":"C","explanation":"The cash value and death benefits of a Variable Life policy can fluctuate according to the performance of its underlying investment portfolio.","explanationPt":"O valor em dinheiro e o benefício por morte de uma apólice de Vida Variável podem flutuar de acordo com o desempenho da carteira de investimentos subjacente.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q060","sourceNumber":60,"duplicateIndex":1,"question":"B receives yearly dividends and interest from a participating life insurance policy. Which of these should B include as gross income for federal income tax purposes?","options":[{"label":"A","text":"Interest and dividends"},{"label":"B","text":"Interest only"},{"label":"C","text":"Dividends only"},{"label":"D","text":"Neither interest nor dividends are taxable"}],"correctAnswer":"B","explanation":"Some life insurance policies (known as participating policies) pay dividends to their policyholders. Dividends are generally not taxed as income to the policyowner. However interest is taxable as income for federal income tax purposes.","explanationPt":"Algumas apólices de seguro de vida (conhecidas como apólices participantes) pagam dividendos aos seus titulares. Os dividendos geralmente não são tributados como renda para o titular; porém, os juros são tributáveis como renda para fins de imposto de renda federal.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q061","sourceNumber":61,"duplicateIndex":1,"question":"Life and health insurance policies are:","options":[{"label":"A","text":"Multi-lateral contracts"},{"label":"B","text":"Bilateral contracts"},{"label":"C","text":"Unilateral contracts"},{"label":"D","text":"Non-lateral contracts"}],"correctAnswer":"C","explanation":"Life and health insurance policies are considered unilateral contracts because one party makes a promise, and the other party can only accept by performance.","explanationPt":"As apólices de seguro de vida e saúde são consideradas contratos unilaterais porque uma parte faz uma promessa, e a outra parte só pode aceitar por meio do cumprimento (pagamento do prêmio).","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q062","sourceNumber":62,"duplicateIndex":1,"question":"J is 35-years old and looking to purchase a whole life insurance policy. Which of the following types of policies will provide the most rapid growth of cash value?","options":[{"label":"A","text":"Life Paid-up at Age 70"},{"label":"B","text":"20-pay Life"},{"label":"C","text":"Increasing Term to age 65"},{"label":"D","text":"Straight Life"}],"correctAnswer":"B","explanation":"The shorter the pay period, the faster the cash value growth.","explanationPt":"Quanto mais curto o período de pagamento, mais rápido é o crescimento do valor em dinheiro.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q063","sourceNumber":63,"duplicateIndex":1,"question":"Which of these types of life insurance allows the policyowner to have level premiums and to also choose from a selection of investment options?","options":[{"label":"A","text":"Modified Whole Life"},{"label":"B","text":"Variable Life"},{"label":"C","text":"Universal Life"},{"label":"D","text":"Adjustable Life"}],"correctAnswer":"B","explanation":"A life insurance policy that has a level premium but allows the policyowner to choose from a selection of investment options is known as Variable Life.","explanationPt":"Uma apólice de seguro de vida com prêmio nivelado, mas que permite ao titular escolher entre opções de investimento, é conhecida como Vida Variável.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q064","sourceNumber":64,"duplicateIndex":1,"question":"T is covered by an Accidental Death and Dismemberment (AD&D) policy that has an irrevocable beneficiary. What action will the insurance company take if T requests a change of beneficiary?","options":[{"label":"A","text":"Request will be accepted only if in writing by the insured"},{"label":"B","text":"Change will be made only if premiums are paid current"},{"label":"C","text":"Change will be made immediately."},{"label":"D","text":"Request of the change will be refused"}],"correctAnswer":"D","explanation":"An irrevocable designation may not be changed without the written consent of the beneficiary.","explanationPt":"Uma designação irrevogável não pode ser alterada sem o consentimento por escrito do beneficiário.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q065","sourceNumber":65,"duplicateIndex":1,"question":"Credit life insurance is typically issued with which of the following types of coverage?","options":[{"label":"A","text":"Annual Renewable Term"},{"label":"B","text":"Decreasing Term"},{"label":"C","text":"Individual Whole Life"},{"label":"D","text":"Group Term"}],"correctAnswer":"B","explanation":"The type of insurance used for Credit life is typically decreasing term, with the term matched to the length of the loan period.","explanationPt":"O tipo de seguro usado para Credit Life é tipicamente o temporário decrescente (decreasing term), com o prazo ajustado à duração do empréstimo.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q066","sourceNumber":66,"duplicateIndex":1,"question":"Which action could result in a hearing being ordered by the Department of Financial Services?","options":[{"label":"A","text":"Representing a foreign insurer"},{"label":"B","text":"Sharing commissions with another licensed agent"},{"label":"C","text":"Performing insurance transactions without a license"},{"label":"D","text":"Conducting insurance business in this state while being a resident of another"}],"correctAnswer":"C","explanation":"A hearing may be conducted if anyone is suspected of engaging in the business of insurance without a license.","explanationPt":"Uma audiência pode ser realizada se alguém for suspeito de atuar no ramo de seguros sem licença.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q067","sourceNumber":67,"duplicateIndex":1,"question":"A Limited-Pay Life policy has:","options":[{"label":"A","text":"graded death benefits"},{"label":"B","text":"no cash value"},{"label":"C","text":"premium payments limited to a specified number of years"},{"label":"D","text":"premium payments that are paid to age 100"}],"correctAnswer":"C","explanation":"In a Limited-Pay Life policy, premium payments are limited to a specified number of years.","explanationPt":"Em uma apólice de Vida com Pagamento Limitado (Limited-Pay Life), os pagamentos de prêmio são limitados a um número específico de anos.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q068","sourceNumber":68,"duplicateIndex":1,"question":"Which type of contract liquidates an estate through recurrent payments?","options":[{"label":"A","text":"Universal life insurance"},{"label":"B","text":"Whole life insurance"},{"label":"C","text":"Annuity"},{"label":"D","text":"401(K)"}],"correctAnswer":"C","explanation":"A contract that provides for the liquidation of all or part of an estate through periodic payments is known as an annuity.","explanationPt":"Um contrato que prevê a liquidação de todo ou parte de um patrimônio por meio de pagamentos periódicos é conhecido como anuidade.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q069","sourceNumber":69,"duplicateIndex":1,"question":"Which of these require an offer, acceptance, and consideration?","options":[{"label":"A","text":"Warranty"},{"label":"B","text":"Estoppel"},{"label":"C","text":"Contract"},{"label":"D","text":"Representation"}],"correctAnswer":"C","explanation":"Offer, acceptance, and consideration are all elements of a contract.","explanationPt":"Oferta, aceitação e contraprestação são todos elementos de um contrato.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q070","sourceNumber":70,"duplicateIndex":1,"question":"Agent J takes an application and initial premium from an applicant and sends the application and premium check to the insurance company. The insurance company returns the check back to J because the check is made out to J instead of the insurance company. What action should J take?","options":[{"label":"A","text":"Deposit the applicant's check into his account and make a personal check out to the insurance company from his personal account"},{"label":"B","text":"Return to the customer, collect a new check made out to the insurance company, and send the new check out to the insurance company"},{"label":"C","text":"Cross off his name on the \"pay to\" portion of the check, write the name of the insurance company, and send the check back to the insurance company"},{"label":"D","text":"Deposit the check in to his personal account, use the funds to purchase a cashiers check, and send the new cashiers check back to the insurance company"}],"correctAnswer":"B","explanation":"If an agent receives a check made out to them instead of the insurance company, they should return the check to the customer and collect a new check properly made out to the insurance company.","explanationPt":"Se um agente receber um cheque emitido em seu próprio nome em vez do nome da seguradora, ele deve devolver o cheque ao cliente e obter um novo cheque emitido corretamente em nome da seguradora.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q071","sourceNumber":71,"duplicateIndex":1,"question":"_____ of personal life insurance premiums is usually deductible for federal income tax purposes.","options":[{"label":"A","text":"100%"},{"label":"B","text":"75%"},{"label":"C","text":"50%"},{"label":"D","text":"0%"}],"correctAnswer":"D","explanation":"In general, personal life insurance premiums are NOT deductible for federal income tax purposes.","explanationPt":"Em geral, os prêmios pessoais de seguro de vida NÃO são dedutíveis para fins de imposto de renda federal.","theme":"Health Insurance","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q072","sourceNumber":72,"duplicateIndex":1,"question":"K is an agent who takes an application for individual life insurance and accepts a check from the client. He submits the application and check to the insurance company, however the check was never signed by the applicant. If the application is approved, when will coverage be effective?","options":[{"label":"A","text":"The date the sales appointment was made."},{"label":"B","text":"The date the application was submitted to the insurance company"},{"label":"C","text":"The date of application"},{"label":"D","text":"The date the agent delivered the policy, collected the initial premium, and obtained a good health statement from the insured"}],"correctAnswer":"D","explanation":"In this situation, coverage will go into effect the date the agent delivers the policy, collects the initial premium, and obtains a good health statement from the insured.","explanationPt":"Nesta situação, a cobertura entrará em vigor na data em que o agente entregar a apólice, coletar o prêmio inicial e obter uma declaração de boa saúde do segurado.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q073","sourceNumber":73,"duplicateIndex":1,"question":"Who is a mutual insurance company owned by?","options":[{"label":"A","text":"Its board of directors"},{"label":"B","text":"Its policyholders"},{"label":"C","text":"The State of Florida"},{"label":"D","text":"Its employees"}],"correctAnswer":"B","explanation":"A mutual insurance company is owned by its policyholders.","explanationPt":"Uma seguradora mútua (mutual insurance company) é de propriedade de seus próprios segurados.","theme":"Life Insurance Policies","jurisdiction":"FL","review":false,"reviewFlags":[]},{"id":"Q074","sourceNumber":74,"duplicateIndex":1,"question":"P has recently signed an application for insurance. The insurer MUST advise her in writing that an investigative consumer report may be conducted according to the","options":[{"label":"A","text":"Fair Credit Reporting Act"},{"label":"B","text":"Medical Information Bureau"},{"label":"C","text":"Part Ill of the application"},{"label":"D","text":"Life Insurance Buyer's Guide"}],"correctAnswer":"A","explanation":"The Fair Credit Reporting Act requires that an insurance application state that an investigative consumer report may be obtained on an applicant.","explanationPt":"A Lei de Relatórios de Crédito Justo (Fair Credit Reporting Act) exige que a proposta de seguro informe que um relatório investigativo do consumidor pode ser obtido sobre o proponente.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q075","sourceNumber":75,"duplicateIndex":1,"question":"In Florida, which employee is eligible for an employer's group term life plan?","options":[{"label":"A","text":"Employee who works seasonally during the summer"},{"label":"B","text":"Employee who works part-time."},{"label":"C","text":"Employee who works more than 40 hours per week"},{"label":"D","text":"Full time employee not actively at work"}],"correctAnswer":"C","explanation":"All of these employees may be EXCLUDED for group term life coverage EXCEPT \"Employee who works more than 40 hours per week\".","explanationPt":"Todos estes funcionários podem ser EXCLUÍDOS da cobertura de vida em grupo temporário, EXCETO \"funcionário que trabalha mais de 40 horas por semana\".","theme":"Life Insurance Policies","jurisdiction":"FL","review":false,"reviewFlags":[]},{"id":"Q076","sourceNumber":76,"duplicateIndex":1,"question":"Variable Life products require a producer to","options":[{"label":"A","text":"guarantee not more than a 12% return per annum"},{"label":"B","text":"hold a Life and Health Insurance license"},{"label":"C","text":"hold a Life Insurance license and a Securities license"},{"label":"D","text":"be regulated solely by State Law"}],"correctAnswer":"C","explanation":"Variable Life products require a producer to hold a Life Insurance license and a Securities license.","explanationPt":"Produtos de Vida Variável exigem que o produtor possua uma licença de Seguro de Vida e uma licença de Valores Mobiliários (Securities).","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q077","sourceNumber":77,"duplicateIndex":1,"question":"_____ can be defined as \"using the contract values of an existing policy to purchase a new policy with an existing insurer\".","options":[{"label":"A","text":"Churning"},{"label":"B","text":"Defamation"},{"label":"C","text":"Misrepresentation"},{"label":"D","text":"Twisting"}],"correctAnswer":"A","explanation":"Churning can be defined as \"using the contract values of an existing policy to purchase a new policy with an existing Insurer”","explanationPt":"\"Churning\" pode ser definido como \"usar os valores contratuais de uma apólice existente para comprar uma nova apólice com a mesma seguradora\".","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q078","sourceNumber":78,"duplicateIndex":1,"question":"Which Unfair Trade Practice involves making a false statement on an insurance application in order to receive money from insurer?","options":[{"label":"A","text":"receive money from an insurer?"},{"label":"B","text":"Rebating"},{"label":"C","text":"Coercion"},{"label":"D","text":"Sliding"},{"label":"E","text":"Misrepresentation"}],"correctAnswer":"E","explanation":"Making a fraudulent statement on an insurance application would be considered an act of misrepresentation.","explanationPt":"Fazer uma declaração fraudulenta em uma proposta de seguro seria considerado um ato de declaração falsa (misrepresentation).","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q079","sourceNumber":79,"duplicateIndex":1,"question":"At what point does a Whole Life Insurance policy endow?","options":[{"label":"A","text":"At age 65"},{"label":"B","text":"When premium paid equals the death benefit"},{"label":"C","text":"When the cash value equals the death benefit"},{"label":"D","text":"In 30 years or age 65, whichever comes first"}],"correctAnswer":"C","explanation":"A Whole Life Insurance Policy endows when the cash value equals the death benefit.","explanationPt":"Uma Apólice de Seguro de Vida Inteira \"vence\" (endows) quando o valor em dinheiro se iguala ao benefício por morte.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q080","sourceNumber":80,"duplicateIndex":1,"question":"Which of the following documents must an agent submit to the replacing insurance company during the replacement of an existing life insurance policy?","options":[{"label":"A","text":"Notice to existing and replacing insurers of intention to replace"},{"label":"B","text":"A list of all policies the agent has replaced in the last 3 years"},{"label":"C","text":"A statement made by the agent that NAIC guidelines have been met during the replacement process"},{"label":"D","text":"A copy of the agent's insurance license"}],"correctAnswer":"A","explanation":"When replacing an existing life insurance policy, an agent must submit notice to existing insurer and replacing insurer of intentions.","explanationPt":"Ao substituir uma apólice de seguro de vida existente, o agente deve enviar um aviso de suas intenções tanto à seguradora atual quanto à nova seguradora.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q081","sourceNumber":81,"duplicateIndex":1,"question":"Which of the following is NOT a consequence for placing business with an unauthorized insurer?","options":[{"label":"A","text":"Third degree felony"},{"label":"B","text":"First degree misdemeanor"},{"label":"C","text":"Insurance license revoked"},{"label":"D","text":"Responsible for unpaid claims"}],"correctAnswer":"B","explanation":"All of these are possible consequences for placing business with an unauthorized insurer EXCEPT the conviction of a first degree misdemeanor.","explanationPt":"Todas estas são possíveis consequências por colocar negócios com uma seguradora não autorizada, EXCETO a condenação por contravenção de primeiro grau (first degree misdemeanor).","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q082","sourceNumber":82,"duplicateIndex":1,"question":"Which of these is NOT a reason for a business to buy key person life insurance?","options":[{"label":"A","text":"The reduction in sales as a direct result from death of the key employee"},{"label":"B","text":"Avoid in leadership if the key person were to die"},{"label":"C","text":"The loss of company revenues while a replacement is being sought"},{"label":"D","text":"pension deficiency if the key employee dies"}],"correctAnswer":"D","explanation":"All of these are reasons for a business organization to purchase key person life insurance EXCEPT \"A pension deficiency if the key employee dies”.","explanationPt":"Todas estas são razões para uma empresa comprar seguro de vida de pessoa-chave (key person), EXCETO \"uma deficiência de pensão caso o funcionário-chave morra\".","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q083","sourceNumber":83,"duplicateIndex":1,"question":"In a Life insurance contract, an insurance company's promise to pay stated benefits is called the:","options":[{"label":"A","text":"Insuring clause"},{"label":"B","text":"Consideration clause"},{"label":"C","text":"Entire Contract"},{"label":"D","text":"Owner's rights"}],"correctAnswer":"A","explanation":"The insuring clause in a Life insurance c tract establishes the basic promise of the insurance company.","explanationPt":"A cláusula de seguro (insuring clause) em um contrato de seguro de vida estabelece a promessa básica da seguradora.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q084","sourceNumber":84,"duplicateIndex":1,"question":"According to Florida law, a Group Life insurance policy requires a minimum of how many insureds?","options":[{"label":"A","text":"2"},{"label":"B","text":"25"},{"label":"C","text":"100"},{"label":"D","text":"No minimum"}],"correctAnswer":"D","explanation":"In Florida, there is no minimum number of insureds required for a group life insurance policy.","explanationPt":"Na Flórida, não há um número mínimo de segurados exigido para uma apólice de seguro de vida em grupo.","theme":"Life Insurance Policies","jurisdiction":"FL","review":false,"reviewFlags":[]},{"id":"Q085","sourceNumber":85,"duplicateIndex":1,"question":"All of these are considered to be a benefit under Social Security, EXCEPT for:","options":[{"label":"A","text":"survivorship"},{"label":"B","text":"unemployment"},{"label":"C","text":"disability"},{"label":"D","text":"retirement"}],"correctAnswer":"B","explanation":"All of these are considered benefits of social security EXCEPT for unemployment.","explanationPt":"Todos estes são considerados benefícios do Seguro Social (Social Security), EXCETO desemprego.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q086","sourceNumber":86,"duplicateIndex":1,"question":"In a qualified retirement plan, the yearly contributions to an employee's account:","options":[{"label":"A","text":"are not tax-deductible"},{"label":"B","text":"are restricted to minimum levels set by the IRS"},{"label":"C","text":"are restricted to maximum levels set by the IRS"},{"label":"D","text":"must be matched dollar-for-dollar by the employer"}],"correctAnswer":"C","explanation":"Annual limits to an employee's qualified retirement pian are based on maximum limits set by the IRS.","explanationPt":"Os limites anuais para o plano de aposentadoria qualificado de um funcionário são baseados nos limites máximos estabelecidos pela Receita Federal (IRS).","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q087","sourceNumber":87,"duplicateIndex":1,"question":"Which of the following is NOT an unfair claim settlement practice?","options":[{"label":"A","text":"Failing to acknowledge and act promptly with respect to an insurance claim"},{"label":"B","text":"Compelling an insured to initiate a lawsuit by offering less on an insurance claim"},{"label":"C","text":"Failing to accept or deny a claim within reasonable time after proof of loss is submitted"},{"label":"D","text":"Needing written documentation of claim details"}],"correctAnswer":"D","explanation":"All of these are unfair claim settlement practices except “Needing written documentation of claim details\".","explanationPt":"Todas estas são práticas desleais de liquidação de sinistros, EXCETO \"exigir documentação escrita dos detalhes do sinistro\".","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q088","sourceNumber":88,"duplicateIndex":1,"question":"Credit Life insurance is:","options":[{"label":"A","text":"issued in any amount at the discretion of the applicant"},{"label":"B","text":"used in the event of loss of income"},{"label":"C","text":"issued in an amount not to exceed the amount of the loan"},{"label":"D","text":"coverage that waives the premiums on a loan payment in the event of total disability"}],"correctAnswer":"C","explanation":"Credit life insurance is designed to cover the life of a debtor and pay the amount due on a loan if the debtor dies before the loan is repaid.","explanationPt":"O seguro de vida de crédito (credit life insurance) é projetado para cobrir a vida de um devedor e pagar o valor devido de um empréstimo caso o devedor morra antes de quitá-lo.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q089","sourceNumber":89,"duplicateIndex":1,"question":"A Universal Life policy is sometimes referred to as an unbundled Life Policy because the owner can see the interest earned, expense charges, and the","options":[{"label":"A","text":"inherent risk"},{"label":"B","text":"commission rate"},{"label":"C","text":"inflation factor"},{"label":"D","text":"cost of insurance"}],"correctAnswer":"D","explanation":"The Universal Life Policy is called an unbundled Life Policy because the policyholder can see the expense charges, the interest eamed, and the cost of insurance.","explanationPt":"A apólice de Vida Universal é chamada de apólice de vida \"desagregada\" (unbundled) porque o titular pode visualizar as taxas de despesas, os juros ganhos e o custo do seguro separadamente.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q090","sourceNumber":90,"duplicateIndex":1,"question":"W gave W's age as 50 when W purchased a Life policy. At the time of W's death seven years later, the company discovered W's true age at issue had been 59. What would the normal procedure be under the misstatement of age provision in regard to the payment of the death claim?","options":[{"label":"A","text":"The policy's full death benefit would be paid, due to the expiration of the incontestable period"},{"label":"B","text":"The proceeds would be reduced based on whatever the premium would have been if purchased at age 59"},{"label":"C","text":"There would be no death proceeds paid out by the insurer"},{"label":"D","text":"The insurer is only obligated to refund all premiums paid"}],"correctAnswer":"B","explanation":"In this situation, the proceeds will be reduced based on whatever the premium would have been if purchased at age 59.","explanationPt":"Nesta situação, os valores serão reduzidos com base no que o prêmio teria sido se a apólice tivesse sido contratada aos 59 anos.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q091","sourceNumber":91,"duplicateIndex":1,"question":"Which of these is NOT considered to be an element of an insurance contract?","options":[{"label":"A","text":"the offer"},{"label":"B","text":"acceptance"},{"label":"C","text":"negotiating"},{"label":"D","text":"consideration"}],"correctAnswer":"C","explanation":"The elements of an insurance contract do not include negotiating.","explanationPt":"Os elementos de um contrato de seguro não incluem negociação.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q092","sourceNumber":92,"duplicateIndex":1,"question":"If an agent combines premiums collected with their personal funds, they have engaged in:","options":[{"label":"A","text":"twisting"},{"label":"B","text":"commingling"},{"label":"C","text":"defamation"},{"label":"D","text":"rebating"}],"correctAnswer":"B","explanation":"An agent who has combined premiums collected with personal funds has engaged in commingling, which is a prohibited.","explanationPt":"Um agente que misturou prêmios recebidos com fundos pessoais praticou \"commingling\" (mistura de fundos), o que é proibido.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q093","sourceNumber":93,"duplicateIndex":1,"question":"N is a 40-year old applicant who would like to retire at age 70. He is looking to buy a life insurance policy with level premiums, permanent protection, and be paid-up at retirement. Which of these should N purchase?","options":[{"label":"A","text":"30 Pay Life"},{"label":"B","text":"Term to Age 70"},{"label":"C","text":"Universal Life"},{"label":"D","text":"Adjustable Life"}],"correctAnswer":"A","explanation":"Limited pay whole life policies have level premiums that are limited to a certain period.","explanationPt":"As apólices de vida inteira com pagamento limitado (limited pay whole life) têm prêmios nivelados que são limitados a um determinado período.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q094","sourceNumber":94,"duplicateIndex":1,"question":"In an individual retirement account (IRA), rollover contributions are:","options":[{"label":"A","text":"subject to capital gains tax"},{"label":"B","text":"subject to ordinary income tax"},{"label":"C","text":"partially limited by dollar amount"},{"label":"D","text":"not limited by dollar amount"}],"correctAnswer":"D","explanation":"Rollover contributions to an individual retirement account are unlimited by dollar amount.","explanationPt":"As contribuições de rollover para uma conta de aposentadoria individual (IRA) não têm limite de valor em dólares.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q095","sourceNumber":95,"duplicateIndex":1,"question":"M has an insurance policy that also has an outstanding policy loan at the time of M's death. The insurer will deduct the outstanding loan balance from the:","options":[{"label":"A","text":"cash value"},{"label":"B","text":"estate of the insured"},{"label":"C","text":"policy proceeds"},{"label":"D","text":"nonforfeiture value"}],"correctAnswer":"C","explanation":"If not repaid by the time the insured dies, the loan balance and any interest accrued are deducted from the policy proceeds at the time of claim.","explanationPt":"Se não for quitado até a morte do segurado, o saldo do empréstimo e quaisquer juros acumulados são deduzidos dos valores da apólice no momento do sinistro.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q096","sourceNumber":96,"duplicateIndex":1,"question":"A policy of adhesion can only be modified by whom?","options":[{"label":"A","text":"The agent"},{"label":"B","text":"The applicant"},{"label":"C","text":"The primary beneficiary"},{"label":"D","text":"The insurance company"}],"correctAnswer":"D","explanation":"A policy of adhesion is best described as a policy which only the insurance company can modify","explanationPt":"Um contrato de adesão é melhor descrito como um contrato que somente a seguradora pode modificar.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q097","sourceNumber":97,"duplicateIndex":1,"question":"Which of the following statements is CORRECT about an agent who is taking an insurance application?","options":[{"label":"A","text":"The agent should avoid asking the applicant questions that may cause embarrassment"},{"label":"B","text":"The agent should have the applicant initial any changes made on the application"},{"label":"C","text":"The agent may allow a member of the applicant's immediate family to sign the application if the applicant is not available"},{"label":"D","text":"The agent may answer routine questions on the application for the applicant"}],"correctAnswer":"B","explanation":"An agent who is taking an insurance application should have the applicant initial any changes made on the application.","explanationPt":"Um agente que estiver preenchendo uma proposta de seguro deve pedir ao proponente que rubrique quaisquer alterações feitas na proposta.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q098","sourceNumber":98,"duplicateIndex":1,"question":"S would like to use dividends from her life insurance policy to purchase paid-up additions. All of these would be factors that determine how much coverage can be purchased EXCEPT","options":[{"label":"A","text":"type of life insurance"},{"label":"B","text":"S's attained age"},{"label":"C","text":"dividend amount used toward purchase"},{"label":"D","text":"beneficiary's age"}],"correctAnswer":"D","explanation":"The age of the beneficiary is irrelevant in determining how much paid-up additions can be purchased.","explanationPt":"A idade do beneficiário é irrelevante para determinar quanto de adições integralizadas (paid-up additions) pode ser comprado.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q099","sourceNumber":99,"duplicateIndex":1,"question":"J chooses a monthly premium payment mode on his Whole Life insurance policy. Which of these statements is correct?","options":[{"label":"A","text":"The gross premium is higher on a monthly payment mode as compared to being paid annually"},{"label":"B","text":"The gross premium is lower on a monthly payment mode as compared to being paid annually"},{"label":"C","text":"The cash value from a life policy paid on a monthly basis builds quicker than one paid on an annual basis"},{"label":"D","text":"The face amount of a life policy paid on a monthly basis is higher than one paid on an annual basis"}],"correctAnswer":"A","explanation":"A premium payment mode that is more frequent than an annual payment will result in a higher gross premium.","explanationPt":"Um modo de pagamento de prêmio mais frequente do que o pagamento anual resultará em um prêmio bruto total mais alto.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q100","sourceNumber":100,"duplicateIndex":1,"question":"A variable life insurance agent must be licensed and appointed as a life and variable contract agent, as well as a(n)","options":[{"label":"A","text":"accredited agent"},{"label":"B","text":"broker dealer"},{"label":"C","text":"Certified Variable Dealer (CVD)"},{"label":"D","text":"Registered Managing Agent (RMA)"}],"correctAnswer":"B","explanation":"An agent marketing variable life insurance must be licensed and appointed as a life and variable contract agent and a broker dealer.","explanationPt":"Um agente que comercializa seguro de vida variável deve ser licenciado e credenciado como agente de vida e contratos variáveis, além de corretor-distribuidor (broker dealer).","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q101","sourceNumber":101,"duplicateIndex":1,"question":"Which of these is NOT a type of agent authority?","options":[{"label":"A","text":"Express"},{"label":"B","text":"Implied"},{"label":"C","text":"Principal"},{"label":"D","text":"Apparent"}],"correctAnswer":"C","explanation":"The three types of agent authority include express, implied, and apparent authority.","explanationPt":"Os três tipos de autoridade de um agente incluem autoridade expressa, implícita e aparente.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q102","sourceNumber":102,"duplicateIndex":1,"question":"When is the face amount of a Whole Life policy paid?","options":[{"label":"A","text":"At the policy's maturity date only"},{"label":"B","text":"When the insured dies or at the policy's maturity date, whichever happens first"},{"label":"C","text":"Only when the insured dies"},{"label":"D","text":"When the policy is surrendered"}],"correctAnswer":"B","explanation":"The face amount of a Whole Life policy will be paid when the insured dies or on maturity of the policy, whichever occurs first.","explanationPt":"O valor de face de uma apólice de Vida Inteira será pago quando o segurado morrer ou no vencimento da apólice, o que ocorrer primeiro.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q103","sourceNumber":103,"duplicateIndex":1,"question":"Additional coverage can be added to a Whole Life policy by adding a(n):","options":[{"label":"A","text":"payor rider"},{"label":"B","text":"accelerated benefit rider"},{"label":"C","text":"decreasing term rider"},{"label":"D","text":"automatic premium loan rider"}],"correctAnswer":"C","explanation":"A decreasing term rider can add additional coverage to a whole life policy.","explanationPt":"Uma cláusula adicional de termo decrescente (decreasing term rider) pode acrescentar cobertura extra a uma apólice de vida inteira.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q104","sourceNumber":104,"duplicateIndex":1,"question":"When an insurer issues a policy that refuses to cover certain risks, this is referred to as a(n):","options":[{"label":"A","text":"elimination"},{"label":"B","text":"exclusion"},{"label":"C","text":"limitation"},{"label":"D","text":"exception"}],"correctAnswer":"B","explanation":"Exclusions are features of a life insurance policy stating that the policy will not cover certain risks.","explanationPt":"As exclusões são características de uma apólice de seguro de vida que indicam que a apólice não cobrirá determinados riscos.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q105","sourceNumber":105,"duplicateIndex":1,"question":"A life insurance policyowner would like to file a complaint against a life insurance agent. In Florida, the entity that oversees these complaints is called the","options":[{"label":"A","text":"Department of Homeland Security"},{"label":"B","text":"Office of Financial Regulation"},{"label":"C","text":"Securities Exchange Commission"},{"label":"D","text":"Office of Insurance Regulation"}],"correctAnswer":"B","explanation":"The Office of Financial Regulation oversees complaints against life insurance agents and agencies selling life insurance products.","explanationPt":"O Escritório de Regulação Financeira (Office of Financial Regulation) supervisiona as reclamações contra agentes e agências que vendem produtos de seguro de vida.","theme":"Producers and Licensing","jurisdiction":"FL","review":false,"reviewFlags":[]},{"id":"Q106","sourceNumber":106,"duplicateIndex":1,"question":"A(n) _____ annuity pays benefits based on units rather than stated dollar amounts.","options":[{"label":"A","text":"Deferred"},{"label":"B","text":"Variable"},{"label":"C","text":"Immediate"},{"label":"D","text":"Unit"}],"correctAnswer":"B","explanation":"A Variable annuity pays benefits based on units rather than specific dollar amounts.","explanationPt":"Uma anuidade variável paga benefícios com base em unidades, e não em valores fixos em dólares.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q107","sourceNumber":107,"duplicateIndex":1,"question":"A policyowner is able to choose the frequency of premium payments through what policy feature?","options":[{"label":"A","text":"Consideration"},{"label":"B","text":"Payor benefit"},{"label":"C","text":"Premium Mode"},{"label":"D","text":"Assignment provision"}],"correctAnswer":"C","explanation":"Premium mode is the feature that allows the policyowner to select the timing of premium payment, such as monthly.","explanationPt":"O modo de prêmio é a característica que permite ao titular escolher a periodicidade do pagamento do prêmio, como mensalmente.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q108","sourceNumber":108,"duplicateIndex":1,"question":"A level premium indicates:","options":[{"label":"A","text":"the premium is fixed for a period stated in the contract, then becomes variable"},{"label":"B","text":"the premium can only be changed with the consent of the insurer"},{"label":"C","text":"the premium stays level until the policy's renewal date"},{"label":"D","text":"the premium is fixed for the entire duration of the contract"}],"correctAnswer":"D","explanation":"A level premium means that the premium remains fixed through the life of a policy.","explanationPt":"Um prêmio nivelado significa que o prêmio permanece fixo durante toda a vigência da apólice.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q109","sourceNumber":109,"duplicateIndex":1,"question":"K's whole life insurance policy lapsed two months ago due to nonpayment. She would now like to reinstate the policy. All of these statements are correct about the policy's reinstatement EXCEPT","options":[{"label":"A","text":"K must reinstate within a stated period"},{"label":"B","text":"K must pay back interest and premiums"},{"label":"C","text":"K will forfeit the right to use the automatic loan provision upon reinstatement"},{"label":"D","text":"K must provide evidence of insurability"}],"correctAnswer":"C","explanation":"All of these statements concerning reinstatement is correct EXCEPT \"K will forfeit the right to use the automatic provision upon reinstatement'","explanationPt":"Todas estas afirmações sobre reinstalação (reinstatement) estão corretas, EXCETO \"K perderá o direito de usar o dispositivo automático mediante a reinstalação\".","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q110","sourceNumber":110,"duplicateIndex":1,"question":"Which of these factors does NOT influence an applicant's need for life insurance?","options":[{"label":"A","text":"Lifestyle of the applicant"},{"label":"B","text":"Number of dependents"},{"label":"C","text":"Future educational costs of the dependents"},{"label":"D","text":"Self-maintenance expenses"}],"correctAnswer":"D","explanation":"An individual's need for a death benefit for survivors is influenced by all of the following factors EXCEPT self-maintenance expenses.","explanationPt":"A necessidade de um indivíduo por um benefício por morte para os sobreviventes é influenciada por todos estes fatores, EXCETO despesas de autossustento.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q111","sourceNumber":111,"duplicateIndex":1,"question":"In order for a domestic, foreign, or alien insurance company to conduct business, it must be authorized by whom?","options":[{"label":"A","text":"The National Association of Insurance Commissioners (NAIC)"},{"label":"B","text":"The state where they are conducting business"},{"label":"C","text":"The attorney general in the state where they are domiciled"},{"label":"D","text":"Homeland Security"}],"correctAnswer":"B","explanation":"Domestic, foreign, or alien companies must be authorized by each state where they conduct business.","explanationPt":"Empresas domésticas, estrangeiras ou alienígenas (domestic, foreign ou alien) devem ser autorizadas em cada estado onde operam.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q112","sourceNumber":112,"duplicateIndex":1,"question":"Within how many days must a licensee notify the Department of Financial Services of a change in address?","options":[{"label":"A","text":"30"},{"label":"B","text":"60"},{"label":"C","text":"90"},{"label":"D","text":"120"}],"correctAnswer":"A","explanation":"All licensees are required to notify the Department of Financial Services of a change in address within 30 days.","explanationPt":"Todos os licenciados devem notificar o Departamento de Serviços Financeiros sobre uma mudança de endereço no prazo de 30 dias.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q113","sourceNumber":113,"duplicateIndex":1,"question":"Which of the following is an example of a nonforfeiture option?","options":[{"label":"A","text":"Conversion option"},{"label":"B","text":"Reduced Paid-Up option"},{"label":"C","text":"Inflation option"},{"label":"D","text":"Guaranteed insurability option"}],"correctAnswer":"B","explanation":"Reduced Paid-Up option\" is an example of a nonforfeiture option.","explanationPt":"A \"Opção de Pagamento Único Reduzido\" (Reduced Paid-Up) é um exemplo de opção de não confisco (nonforfeiture option).","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q114","sourceNumber":114,"duplicateIndex":1,"question":"Under Florida law, a variable annuity policyowner must be notified of the accumulated value of the contract","options":[{"label":"A","text":"only when requested by the policyowner"},{"label":"B","text":"once each month"},{"label":"C","text":"once each year"},{"label":"D","text":"twice each year"}],"correctAnswer":"C","explanation":"A variable annuity policyholder must be informed at least once each year of the accumulated value of the contract during the premium payment period.","explanationPt":"O titular de uma anuidade variável deve ser informado ao menos uma vez por ano sobre o valor acumulado do contrato durante o período de pagamento dos prêmios.","theme":"Annuities","jurisdiction":"FL","review":false,"reviewFlags":[]},{"id":"Q115","sourceNumber":115,"duplicateIndex":1,"question":"K is insured under a Group Life insurance policy. K is considered to be a(n)","options":[{"label":"A","text":"policyowner"},{"label":"B","text":"annuitant"},{"label":"C","text":"certificate holder"},{"label":"D","text":"beneficiary"}],"correctAnswer":"C","explanation":"Each person covered under a Group Life insurance policy is considered to be a certificate holder","explanationPt":"Cada pessoa coberta por uma apólice de seguro de Vida em Grupo é considerada um titular de certificado.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q116","sourceNumber":116,"duplicateIndex":1,"question":"S is covered by a whole life policy. Which insurance product can cover his children?","options":[{"label":"A","text":"Assignment provision"},{"label":"B","text":"Payor benefit"},{"label":"C","text":"Accelerated benefit rider"},{"label":"D","text":"Child term rider"}],"correctAnswer":"D","explanation":"The means of providing life insurance on the children of a person who is covered by a life insurance policy is by a child term rider.","explanationPt":"O meio de fornecer seguro de vida para os filhos de uma pessoa coberta por uma apólice de seguro de vida é por meio de uma cláusula adicional de termo infantil (child term rider).","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q117","sourceNumber":117,"duplicateIndex":1,"question":"A potential client, age 40, would like to purchase a Whole Life policy that will accumulate cash value at a faster rate in the early years of the policy. Which of these statements made by the producer would be correct?","options":[{"label":"A","text":"Straight life accumulates faster than Limited-pay Life"},{"label":"B","text":"20-Pay Life accumulates cash value faster than Straight Life"},{"label":"C","text":"Cash value accumulation of both 20-Pay Life and Straight Life depend on the insurer's financial rating"},{"label":"D","text":"20-Pay Life and Straight Life accumulate cash value at the same rate"}],"correctAnswer":"B","explanation":"A 20-Pay Life policy requires the policyowner to pay premiums over a shorter period than Straight Life. Because the premiums are paid more quickly, the policy builds cash value faster in the early years than a Straight Life policy.","explanationPt":"Uma apólice de Vida com Pagamento em 20 Anos (20-Pay Life) exige que o titular pague os prêmios em um período mais curto do que a Vida Inteira Comum (Straight Life). Como os prêmios são pagos mais rapidamente, a apólice acumula valor em dinheiro mais rápido nos primeiros anos do que uma apólice Straight Life.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q118","sourceNumber":118,"duplicateIndex":1,"question":"What group term life feature permits an individual to depart from the group and continue to be covered without providing evidence of insurability?","options":[{"label":"A","text":"Entire contract"},{"label":"B","text":"Owner's rights"},{"label":"C","text":"Nonforfeiture options"},{"label":"D","text":"Conversion"}],"correctAnswer":"D","explanation":"The conversion privilege allows an individual to leave the group term plan and continue his or her insurance without providing evidence of insurability.","explanationPt":"O privilégio de conversão permite que um indivíduo saia do plano de vida em grupo temporário e continue seu seguro sem apresentar prova de segurabilidade.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q119","sourceNumber":119,"duplicateIndex":1,"question":"All of these statements about the Waiver of Premium provision are correct, EXCEPT:","options":[{"label":"A","text":"A waiting period must pass before becoming eligible for benefits"},{"label":"B","text":"Waiver of Premium is available on both permanent and term insurance policies"},{"label":"C","text":"Insured must be eligible for Social Security disability for claim to be accepted"},{"label":"D","text":"Insured must be totally disabled to qualify"}],"correctAnswer":"C","explanation":"Receiving Social Security disability benefits is not a requirement to be eligible for the Waiver of Premium.","explanationPt":"Receber benefícios por invalidez do Seguro Social não é um requisito para ter direito à Isenção de Prêmio (Waiver of Premium).","theme":"Health Insurance","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q120","sourceNumber":120,"duplicateIndex":1,"question":"The provision that can be used to put an insurance policy back in force after it has lapsed due to nonpayment is called:","options":[{"label":"A","text":"Reinstatement"},{"label":"B","text":"Grace period"},{"label":"C","text":"Automatic premium loan"},{"label":"D","text":"Waiver of premium"}],"correctAnswer":"A","explanation":"In cases where a policyowner wishes to reinstate a lapsed policy, the reinstatement provision allows the policyowner to do so with some limitations.","explanationPt":"Nos casos em que o titular deseja reinstalar (reinstate) uma apólice caducada, a cláusula de reinstalação permite que ele o faça, com algumas limitações.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q121","sourceNumber":121,"duplicateIndex":1,"question":"An applicant's medical information received from the Medical Information Bureau (MIB) may be furnished the:","options":[{"label":"A","text":"agent"},{"label":"B","text":"applicant's spouse"},{"label":"C","text":"National Association of Insurance Commissioners (NAIC)"},{"label":"D","text":"applicant's physician"}],"correctAnswer":"D","explanation":"Information received from the Medical Information Bureau about a proposed insured may be released to the proposed insured's physician.","explanationPt":"As informações recebidas do Medical Information Bureau sobre um proposto segurado podem ser divulgadas ao médico do proposto segurado.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q122","sourceNumber":122,"duplicateIndex":1,"question":"D needs life insurance that provides coverage for only a limited amount of time while also paying the lowest possible premium. What kind of policy is needed?","options":[{"label":"A","text":"Limited-pay life"},{"label":"B","text":"Graded Premium"},{"label":"C","text":"Level term"},{"label":"D","text":"Endowment"}],"correctAnswer":"C","explanation":"Life insurance written to cover a need for a specified period of time at the lowest premium is called level term insurance.","explanationPt":"O seguro de vida contratado para cobrir uma necessidade por um período específico com o menor prêmio possível é chamado de seguro temporário nivelado (level term).","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q123","sourceNumber":123,"duplicateIndex":1,"question":"The amount of monthly disability benefits payable under Social Security is affected by which of the following factors?","options":[{"label":"A","text":"Insured's tax bracket"},{"label":"B","text":"Amount of the benefits available from other sources"},{"label":"C","text":"Nature of the disability"},{"label":"D","text":"Insured's education level"}],"correctAnswer":"B","explanation":"The amount of the benefits available from other sources affects the amount of monthly disability benefits payable under Social Security.","explanationPt":"O valor dos benefícios disponíveis de outras fontes afeta o valor dos benefícios mensais por invalidez pagáveis pelo Seguro Social.","theme":"Health Insurance","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q124","sourceNumber":124,"duplicateIndex":1,"question":"An example of false advertising would be","options":[{"label":"A","text":"Paid testimonials from celebrity endorsements"},{"label":"B","text":"An insurer exaggerating its dividends in a magazine advertisement"},{"label":"C","text":"An agent spending more than $25 on marketing gifts for a client"},{"label":"D","text":"An insurer advertising in an insurance trade journal"}],"correctAnswer":"B","explanation":"An insurance company may be judged guilty of false advertising if it exaggerates its dividends in a magazine advertisement.","explanationPt":"Uma seguradora pode ser considerada culpada de propaganda enganosa se exagerar seus dividendos em um anúncio de revista.","theme":"Ethics and Compliance","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q125","sourceNumber":125,"duplicateIndex":1,"question":"J is an agent who recently told a claimant that his rights might be impaired if he does not complete a release form within a specified time. What could this agent be found guilty of?","options":[{"label":"A","text":"Twisting"},{"label":"B","text":"Defamation"},{"label":"C","text":"Coercion"},{"label":"D","text":"Rebating"}],"correctAnswer":"C","explanation":"In this situation, the agent may be guilty of coercion.","explanationPt":"Nesta situação, o agente pode ser culpado de coação (coercion).","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q126","sourceNumber":126,"duplicateIndex":1,"question":"Which of the following is TRUE if the owner of an IRA names their spouse as beneficiary, but then before any distributions are made?","options":[{"label":"B","text":"Surrender charge is applied"},{"label":"C","text":"The account can be rolled into the surviving spouse's IRA"},{"label":"D","text":"Distributions will be received tax-free if surviving spouse is over age 59 1/2"},{"label":"E","text":"Future distributions are payable to the owner's estate"}],"correctAnswer":"C","explanation":"A surviving spouse who inherits IRA benefits or benefits from the deceased spouse's qualified plan is eligible to establish a rollover IRA in the surviving spouse's own name.","explanationPt":"Um cônjuge sobrevivente que herda benefícios de um IRA ou de um plano qualificado do cônjuge falecido tem o direito de estabelecer um IRA de rollover em seu próprio nome.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q127","sourceNumber":127,"duplicateIndex":1,"question":"All individuals covered under a group contract will receive a(n)","options":[{"label":"A","text":"certificate"},{"label":"B","text":"receipt of coverage"},{"label":"C","text":"master policy"},{"label":"D","text":"individual policy"}],"correctAnswer":"A","explanation":"A person who is insured within a group contract will be given a certificate.","explanationPt":"Uma pessoa segurada dentro de um contrato em grupo receberá um certificado.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q128","sourceNumber":128,"duplicateIndex":1,"question":"An individual working part-time has an annual income of $25,000. If this individual has an IRA, what is the maximum deductible IRA contribution allowable?","options":[{"label":"A","text":"No deduction allowed"},{"label":"B","text":"$6,000"},{"label":"C","text":"$5,000"},{"label":"D","text":"$4,000"}],"correctAnswer":"B","explanation":"In this situation, the maximum allowable contribution is $6,000.","explanationPt":"Nesta situação, a contribuição máxima permitida é de $6.000.","theme":"Health Insurance","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q129","sourceNumber":129,"duplicateIndex":1,"question":"Which of these arrangements allows one to bypass insurable interest laws?","options":[{"label":"A","text":"Concealment"},{"label":"B","text":"Indemnity contract"},{"label":"C","text":"Contract of adhesion"},{"label":"D","text":"investor-Originated Life Insurance"}],"correctAnswer":"D","explanation":"Investor-originated life insurance (or IOLI), sometimes called stranger-originated life insurance (or STOLI) is used to circumvent state insurable interest statutes. This is done when an investor (or stranger) persuades an individual to take out life insurance specifically for the purpose of selling the policy to the investor. The investor compensates the insured and makes the premiums, then collects the death benefit when the insured dies.","explanationPt":"O seguro de vida originado por investidor (IOLI), às vezes chamado de seguro de vida originado por estranho (STOLI), é usado para contornar as leis estaduais de interesse segurável. Isso ocorre quando um investidor (ou estranho) convence um indivíduo a contratar um seguro de vida com o propósito específico de vender a apólice a esse investidor. O investidor compensa o segurado e paga os prêmios, recebendo o benefício por morte quando o segurado falece.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q130","sourceNumber":130,"duplicateIndex":1,"question":"Which of these are NOT an example of a Nonforfeiture option?","options":[{"label":"A","text":"Extended Term"},{"label":"B","text":"Reduced Paid-up"},{"label":"C","text":"Cash Surrender"},{"label":"D","text":"Life Income"}],"correctAnswer":"D","explanation":"All of these are examples of Nonforfeiture options EXCEPT Life Income.","explanationPt":"Todos estes são exemplos de opções de não confisco (nonforfeiture options), EXCETO Renda Vitalícia (Life Income).","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q131","sourceNumber":131,"duplicateIndex":1,"question":"T has a term policy that allows him to continue the coverage after expiration of the initial policy period. What type of term coverage is this?","options":[{"label":"A","text":"Renewable"},{"label":"B","text":"Increasing"},{"label":"C","text":"Level"},{"label":"D","text":"Decreasing"}],"correctAnswer":"A","explanation":"Renewable Term policies guarantee the insured the right to continue term coverage after expiration of the initial policy period.","explanationPt":"As apólices de Termo Renovável (Renewable Term) garantem ao segurado o direito de continuar a cobertura temporária após o término do período inicial da apólice.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q132","sourceNumber":132,"duplicateIndex":1,"question":"What type of insurance offers permanent life coverage with premiums that are payable for life?","options":[{"label":"A","text":"Credit Life"},{"label":"B","text":"Renewable Term Life"},{"label":"C","text":"Whole Life"},{"label":"D","text":"Endowment"}],"correctAnswer":"C","explanation":"A policy that provides permanent life insurance with premiums payable for life is called whole life.","explanationPt":"Uma apólice que fornece seguro de vida permanente com prêmios pagáveis pela vida toda é chamada de vida inteira (whole life).","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q133","sourceNumber":133,"duplicateIndex":1,"question":"A policyowner's rights are limited under which beneficiary designation?","options":[{"label":"A","text":"Revocable"},{"label":"B","text":"Tertiary"},{"label":"C","text":"Contingent"},{"label":"D","text":"Irrevocable"}],"correctAnswer":"D","explanation":"An irrevocable beneficiary designation requires the consent and signature of that named beneficiary before a change of beneficiary occurs.","explanationPt":"Uma designação de beneficiário irrevogável exige o consentimento e a assinatura desse beneficiário nomeado antes que ocorra uma mudança de beneficiário.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q134","sourceNumber":134,"duplicateIndex":1,"question":"In order for coverage on a non-medical insurance application to take effect the same day, the producer must collect a signed application and","options":[{"label":"A","text":"a Medical Information Report"},{"label":"B","text":"the initial premium"},{"label":"C","text":"forward it immediately to the insurer"},{"label":"D","text":"Attending Physician Statement"}],"correctAnswer":"B","explanation":"Coverage begins on the day in which the producer collects the initial premium and has the applicant sign the life insurance contract..","explanationPt":"A cobertura começa no dia em que o produtor recebe o prêmio inicial e obtém a assinatura do proponente no contrato de seguro de vida.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q135","sourceNumber":135,"duplicateIndex":1,"question":"T is the policyowner for a Life Insurance policy with an Irrevocable beneficiary designation. If T wishes to change the beneficiary, T must obtain permission from the:","options":[{"label":"A","text":"Payor"},{"label":"B","text":"agent"},{"label":"C","text":"beneficiary"},{"label":"D","text":"Commissioner of Insurance"}],"correctAnswer":"C","explanation":"An irrevocable designation may not be changed without the written consent of the beneficiary.","explanationPt":"Uma designação irrevogável não pode ser alterada sem o consentimento por escrito do beneficiário.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q136","sourceNumber":136,"duplicateIndex":1,"question":"Agents that have been licensed for less than six years must complete __ hours of continuing education every two years.","options":[{"label":"A","text":"8"},{"label":"B","text":"20"},{"label":"C","text":"24"},{"label":"D","text":"36"}],"correctAnswer":"C","explanation":"Florida agents licensed less than six years are required to complete 24 hours of continuing education.","explanationPt":"Agentes da Flórida licenciados há menos de seis anos devem completar 24 horas de educação continuada.","theme":"Producers and Licensing","jurisdiction":"FL","review":false,"reviewFlags":[]},{"id":"Q137","sourceNumber":137,"duplicateIndex":1,"question":"Who has the option to renew a Renewable Term policy?","options":[{"label":"A","text":"Agency"},{"label":"B","text":"Agent"},{"label":"C","text":"Insured"},{"label":"D","text":"Beneficiary"}],"correctAnswer":"C","explanation":"Renewable Term Policy is renewable at the option of the insured.","explanationPt":"A Apólice de Termo Renovável é renovável à opção do segurado.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q138","sourceNumber":138,"duplicateIndex":1,"question":"The policy summary contains specific information on all of the following, EXCEPT:","options":[{"label":"A","text":"provisions"},{"label":"B","text":"benefits"},{"label":"C","text":"commission"},{"label":"D","text":"coverage"}],"correctAnswer":"C","explanation":"The policy summary contains specific information on the provisions, benefits, and coverage of the policy applied for. It does not contain information on agent commissions.","explanationPt":"O resumo da apólice (policy summary) contém informações específicas sobre as cláusulas, benefícios e cobertura da apólice solicitada. Ele não contém informações sobre as comissões do agente.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q139","sourceNumber":139,"duplicateIndex":1,"question":"Which of these statements is INCORRECT regarding the federal income tax treatment of life inrurance?","options":[{"label":"A","text":"insurance?"},{"label":"B","text":"Premiums are normally not tax deductible"},{"label":"C","text":"Cash dividends are normally not taxed"},{"label":"D","text":"Entire cash surrender value is taxable"},{"label":"E","text":"Proceeds are received tax-free if there is a named beneficiary"}],"correctAnswer":"D","explanation":"The total cash surrender value is NOT taxable. The interest gained is taxable.","explanationPt":"O valor total de resgate em dinheiro (cash surrender value) NÃO é tributável. Os juros ganhos são tributáveis.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q140","sourceNumber":140,"duplicateIndex":1,"question":"M purchased an Accidental Death and Dismemberment (AD&D) policy and named his son as beneficiary. M has the right to change the beneficiary designation at anytime. What type of beneficiary is his son?","options":[{"label":"A","text":"Tertiary"},{"label":"B","text":"Irrevocable"},{"label":"C","text":"Revocable"},{"label":"D","text":"Contingent"}],"correctAnswer":"C","explanation":"With a revocable beneficiary designation, the policyowner may change the beneficiary at any time without notifying or getting permission from the beneficiary.","explanationPt":"Com uma designação de beneficiário revogável, o titular pode mudar o beneficiário a qualquer momento sem notificar ou obter permissão do beneficiário.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q141","sourceNumber":141,"duplicateIndex":1,"question":"A statement made by an insured in an insurance application that must be true to the best of one's knowledge and which becomes a part of the contract is known as:","options":[{"label":"A","text":"an insuring agreement"},{"label":"B","text":"a mutual assent"},{"label":"C","text":"warranty"},{"label":"D","text":"a representation"}],"correctAnswer":"D","explanation":"The correct answer is \"a representation.\" A statement made by an insured in an insurance application that must be true to the best of one's knowledge and which becomes a part of the contract is a representation.","explanationPt":"A resposta correta é \"uma declaração (representation)\". Uma afirmação feita pelo segurado em uma proposta de seguro, que deve ser verdadeira segundo seu melhor conhecimento e que passa a fazer parte do contrato, é chamada de representação.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q142","sourceNumber":142,"duplicateIndex":1,"question":"The type of annuity that can be purchased with one monetary deposit is called a(n):","options":[{"label":"A","text":"Single Deposit annuity"},{"label":"B","text":"Single Premium annuity"},{"label":"C","text":"Fixed annuity"},{"label":"D","text":"Immediate annuity"}],"correctAnswer":"D","explanation":"An imediate annuity is purchased with one monetary deposit.","explanationPt":"Uma anuidade imediata é adquirida com um único depósito monetário.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q143","sourceNumber":143,"duplicateIndex":1,"question":"Which of these is NOT considered to be a right given to a policyowner?","options":[{"label":"A","text":"Surrendering the policy's cash value"},{"label":"B","text":"Modify a provision in the insurance contract"},{"label":"C","text":"Assignment of ownership"},{"label":"D","text":"Change the beneficiary, if revocable"}],"correctAnswer":"B","explanation":"Changing contract provisions is not a policyowner right.","explanationPt":"Alterar as cláusulas do contrato não é um direito do titular da apólice.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q144","sourceNumber":144,"duplicateIndex":1,"question":"All of these Settlement options involve the systematic liquidation of the death proceeds in the event of the insured's death, EXCEPT:","options":[{"label":"A","text":"Fixed Period"},{"label":"B","text":"Interest Only"},{"label":"C","text":"Fixed Amount"},{"label":"D","text":"Life Income"}],"correctAnswer":"B","explanation":"The Interest Only option does NOT involve the systematic liquidation of the death proceeds.","explanationPt":"A opção Somente Juros (Interest Only) NÃO envolve a liquidação sistemática dos valores por morte.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q145","sourceNumber":145,"duplicateIndex":1,"question":"Which of these life insurance riders allows the applicant to have excess coverage?","options":[{"label":"A","text":"Automatic Premium Loan rider"},{"label":"B","text":"Waiver of Premium rider"},{"label":"C","text":"Guarantee Insurability rider"},{"label":"D","text":"Term rider"}],"correctAnswer":"D","explanation":"Term riders allow an applicant to have excess life insurance coverage.","explanationPt":"As cláusulas adicionais de termo (term riders) permitem que um proponente tenha cobertura de seguro de vida extra.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q146","sourceNumber":146,"duplicateIndex":1,"question":"Which of these actions should a producer take when submitting an insurance application to an insurer?","options":[{"label":"A","text":"Issue a binding receipt to applicant if no initial premium is submitted"},{"label":"B","text":"Disclose to the applicant the amount of commissions to be eared on this transaction"},{"label":"C","text":"Inform insurer of relevant information not included on the application"},{"label":"D","text":"Arrange for a copy of the Attending Physician Statement (APS) to be sent to the producer"}],"correctAnswer":"C","explanation":"One of the actions a producer should take when submitting an application is to advise the insurer of any other relevant information not contained in the application.","explanationPt":"Uma das ações que um produtor deve tomar ao enviar uma proposta é informar à seguradora qualquer outra informação relevante não contida na proposta.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q147","sourceNumber":147,"duplicateIndex":1,"question":"How do life insurance companies handle cases where the insured commits suicide within the contract's stated Contestable period?","options":[{"label":"A","text":"Claims are denied under the Suicide clause of the policy"},{"label":"B","text":"Company pays twice the face amount under the double indemnity clause"},{"label":"C","text":"Claims are paid in full"},{"label":"D","text":"Premiums are returned under the Consideration clause"}],"correctAnswer":"A","explanation":"Claims are denied under the Suicide clause of the policy.","explanationPt":"Os sinistros são negados sob a cláusula de suicídio da apólice.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q148","sourceNumber":148,"duplicateIndex":1,"question":"K pays on a $20,000 20-Year Endowment policy for 10 years and dies from an automobile accident. How much will the insurance company pay the beneficiary?","options":[{"label":"A","text":"Return of premiums paid"},{"label":"B","text":"Cash value plus interest"},{"label":"C","text":"$20,000 death benefit"},{"label":"D","text":"Face amount plus interest."}],"correctAnswer":"C","explanation":"If the insured dies before the endowment's maturity, the policy's face value — also known as the \"death benefit\" — is paid in a lump sum to any beneficiaries.","explanationPt":"Se o segurado falecer antes do vencimento do dotal (endowment), o valor de face da apólice — também conhecido como \"benefício por morte\" — é pago em uma única quantia aos beneficiários.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q149","sourceNumber":149,"duplicateIndex":1,"question":"Under a Renewable Term policy,","options":[{"label":"A","text":"the face amount is automatically adjusted at the time of renewal"},{"label":"B","text":"evidence of insurability must be provided at each renewal"},{"label":"C","text":"the renewal premium is calculated on the basis of the insured's attained age"},{"label":"D","text":"a new application must be completed at each renewal"}],"correctAnswer":"C","explanation":"Under a Renewable Term policy, the renewal premium is calculated on the basis of the insured's attained age.","explanationPt":"Em uma apólice de Termo Renovável, o prêmio de renovação é calculado com base na idade atingida (attained age) do segurado.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q150","sourceNumber":150,"duplicateIndex":1,"question":"If a policyowner does not pay the premium by the due date, the","options":[{"label":"A","text":"policy must be reinstated"},{"label":"B","text":"policyowner is automatically assessed a late charge"},{"label":"C","text":"insurance company cancels the policy"},{"label":"D","text":"policyowner can make the premium payment during the grace period"}],"correctAnswer":"D","explanation":"If a policyowner does not pay the premium by the due date, the premium may be paid during the grace period.","explanationPt":"Se o titular não pagar o prêmio até a data de vencimento, o prêmio pode ser pago durante o período de carência (grace period).","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q151","sourceNumber":151,"duplicateIndex":1,"question":"What type of insurance company is domiciled in England, but conducts business in Florida?","options":[{"label":"A","text":"Foreign"},{"label":"B","text":"Domestic"},{"label":"C","text":"Alien"},{"label":"D","text":"Transatlantic"}],"correctAnswer":"C","explanation":"An insurance company that is domiciled in any country other than the United States is known as an alien insurance company.","explanationPt":"Uma seguradora domiciliada em qualquer país que não seja os Estados Unidos é conhecida como seguradora estrangeira/alienígena (alien insurance company).","theme":"State Law","jurisdiction":"FL","review":false,"reviewFlags":[]},{"id":"Q152","sourceNumber":152,"duplicateIndex":1,"question":"What would be an accurate definition of \"controlled business:","options":[{"label":"A","text":"Insurance business that is written on the agent's own life, property, or interests"},{"label":"B","text":"Insurance business obtained by an agent through coercion, intimidation, or boycotting"},{"label":"C","text":"Insurance business that is obtained through false advertising"},{"label":"D","text":"Insurance business that is obtained by replacing an existing policy through misrepresentation"}],"correctAnswer":"A","explanation":"“Controlled business\" is insurance business that is written on the agent's own life, property, or interests.","explanationPt":"\"Negócio controlado\" (controlled business) é o negócio de seguro emitido sobre a própria vida, propriedade ou interesses do agente.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q153","sourceNumber":153,"duplicateIndex":1,"question":"When an insurance application is taken by a producer, which of these statements is true?","options":[{"label":"A","text":"The applicant should have an attorney present during the application process"},{"label":"B","text":"Any changes made on the application require the applicant's initials"},{"label":"C","text":"Any changes made on the application can later be initialed by the producer if the applicant is unavailable"},{"label":"D","text":"The producer has the discretion to ask or not to ask any of the questions listed on the application"}],"correctAnswer":"B","explanation":"The producer should have the applicant initial any changes made on the application.","explanationPt":"O produtor deve pedir ao proponente que rubrique quaisquer alterações feitas na proposta.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q154","sourceNumber":154,"duplicateIndex":1,"question":"An individual covered under a Group Life insurance policy is considered to be a(n)","options":[{"label":"A","text":"annuitant"},{"label":"B","text":"policyowner"},{"label":"C","text":"certificate holder"},{"label":"D","text":"contingent"}],"correctAnswer":"C","explanation":"Each person insured under a Group Life insurance policy is a certificate holder.","explanationPt":"Cada pessoa segurada sob uma apólice de seguro de Vida em Grupo é um titular de certificado.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q155","sourceNumber":155,"duplicateIndex":1,"question":"S, age 40, is looking to buy a Life Insurance policy that will allow for increases or decreases in coverage as his needs change. The policy best suited for S would be","options":[{"label":"A","text":"Straight Life"},{"label":"B","text":"Universal Life"},{"label":"C","text":"an Endowment"},{"label":"D","text":"Modified Whole Life"}],"correctAnswer":"B","explanation":"Universal life insurance is characterized by flexible premiums and an adjustable death benefit.","explanationPt":"O seguro de vida universal é caracterizado por prêmios flexíveis e um benefício por morte ajustável.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q156","sourceNumber":156,"duplicateIndex":1,"question":"A(n) _____ Life pc offers the owner investment in products such as money-market funds, long-term bonds and equities.","options":[{"label":"A","text":"Adjustable"},{"label":"B","text":"Term"},{"label":"C","text":"Universal"},{"label":"D","text":"Variable"}],"correctAnswer":"D","explanation":"A Variable Life policy offers the owner investment in products such as money-market funds, long-term bonds, or equities.","explanationPt":"Uma apólice de Vida Variável oferece ao titular a possibilidade de investir em produtos como fundos do mercado monetário, títulos de longo prazo ou ações.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q157","sourceNumber":157,"duplicateIndex":1,"question":"Which of the following is NOT considered rebating?","options":[{"label":"A","text":"Sharing commissions with an agent licensed in the same line of business"},{"label":"B","text":"Returning premium to a client as an inducement for purchasing a policy"},{"label":"C","text":"Giving something of value to an insured in exchange for their business"},{"label":"D","text":"Offering special dividends"}],"correctAnswer":"A","explanation":"Sharing commissions with other licensed agents is not considered rebating.","explanationPt":"Dividir comissões com outros agentes licenciados não é considerado rebate (rebating).","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q158","sourceNumber":158,"duplicateIndex":1,"question":"Who is normally considered to be the owner of a 403(b) tax-sheltered annuity?","options":[{"label":"A","text":"The 403(b) custodian"},{"label":"B","text":"The financial institution"},{"label":"C","text":"The employer"},{"label":"D","text":"The employee"}],"correctAnswer":"D","explanation":"The participating employee normally applies for and owns a 403(b) tax-sheltered annuity..","explanationPt":"O funcionário participante normalmente solicita e é titular de uma anuidade com benefício fiscal 403(b).","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q159","sourceNumber":159,"duplicateIndex":1,"question":"In Florida, most life insurance policies have a contestability period of","options":[{"label":"A","text":"1 year"},{"label":"B","text":"2 years"},{"label":"C","text":"3 years"},{"label":"D","text":"4 years"}],"correctAnswer":"B","explanation":"The maximum contestability period for most life insurance policies is 2 years.","explanationPt":"O período máximo de contestabilidade para a maioria das apólices de seguro de vida é de 2 anos.","theme":"Producers and Licensing","jurisdiction":"FL","review":false,"reviewFlags":[]},{"id":"Q160","sourceNumber":160,"duplicateIndex":1,"question":"In Florida, which agency is responsible for the rehabilitation or liquidation of insurers?","options":[{"label":"A","text":"Office of the Attorney General (OAG)"},{"label":"B","text":"Department of Financial Services (DFS)"},{"label":"C","text":"Office of Consumer Affairs (OCA)"},{"label":"D","text":"Office of Financial Regulation (OFR)"}],"correctAnswer":"B","explanation":"The Department of Financial Services (DFS) is responsible for the rehabilitation or liquidation of insurers when necessary.","explanationPt":"O Departamento de Serviços Financeiros (DFS) é responsável pela reabilitação ou liquidação das seguradoras quando necessário.","theme":"State Law","jurisdiction":"FL","review":false,"reviewFlags":[]},{"id":"Q161","sourceNumber":161,"duplicateIndex":1,"question":"When can a policyowner change a revocable beneficiary?","options":[{"label":"A","text":"Anytime"},{"label":"B","text":"After the consent of the current beneficiary"},{"label":"C","text":"Never"},{"label":"D","text":"Only if primary beneficiary dies"}],"correctAnswer":"A","explanation":"With a revocable beneficiary designation, the policyowner may change the beneficiary at any time without notifying or getting permission from the beneficiary.","explanationPt":"Com uma designação de beneficiário revogável, o titular pode mudar o beneficiário a qualquer momento sem notificar ou obter permissão do beneficiário.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q162","sourceNumber":162,"duplicateIndex":1,"question":"T took out a $50,000 life insurance policy with an Accidental Death and Dismemberment rider. Five years later, T commits suicide. How much will the insurer pay?","options":[{"label":"A","text":"The total premiums paid minus any policy loans"},{"label":"B","text":"Nothing"},{"label":"C","text":"$50,000"},{"label":"D","text":"$100,000"}],"correctAnswer":"C","explanation":"The suicide occurred outside the Suicide clause period (normally 1-2 years), thus the face amount will be paid","explanationPt":"O suicídio ocorreu fora do período da cláusula de suicídio (normalmente de 1 a 2 anos); portanto, o valor de face será pago.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q163","sourceNumber":163,"duplicateIndex":1,"question":"Which of the following statements is CORRECT regarding the tax treatment of a lump-sum payment paid to a life insurance policy's primary beneficiary?","options":[{"label":"A","text":"The proceeds which exceed the amount paid in premiums are taxable"},{"label":"B","text":"The proceeds are taxable only if the beneficiary's tax bracket has changed from the payout"},{"label":"C","text":"All proceeds are considered taxable income in the year they are received"},{"label":"D","text":"All proceeds are income tax free in the year they are received"}],"correctAnswer":"D","explanation":"If a life insurance policy has a stated beneficiary, all the proceeds are income tax free in the year which they are received.","explanationPt":"Se uma apólice de seguro de vida tiver um beneficiário indicado, todos os valores recebidos são isentos de imposto de renda no ano em que forem recebidos.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q164","sourceNumber":164,"duplicateIndex":1,"question":"A license may be denied, suspended, or revoked if the licensee","options":[{"label":"A","text":"engages in replacement of an existing policy"},{"label":"B","text":"is found guilty of misrepresentation"},{"label":"C","text":"does not meet a sales quota"},{"label":"D","text":"files for bankruptcy"}],"correctAnswer":"B","explanation":"Being found guilty of misrepresentation may result in the Department of Financial Services denying, suspending, revoking, or not renewing any license.","explanationPt":"Ser considerado culpado de declaração falsa (misrepresentation) pode resultar em o Departamento de Serviços Financeiros negar, suspender, revogar ou não renovar qualquer licença.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q165","sourceNumber":165,"duplicateIndex":1,"question":"Which of these do NOT constitute policy delivery?","options":[{"label":"A","text":"Policy mailed to applicant"},{"label":"B","text":"Policy mailed to agent"},{"label":"C","text":"Policy delivered to the applicant by the agent"},{"label":"D","text":"Policy issued with a rating"}],"correctAnswer":"D","explanation":"All of these constitute delivery of the policy EXCEPT issuing a rated policy.","explanationPt":"Todos estes constituem entrega da apólice, EXCETO emitir uma apólice com sobretaxa (rated policy).","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q166","sourceNumber":166,"duplicateIndex":1,"question":"Apolicyowner may generate taxable income from which of the following Dividend Options?","options":[{"label":"A","text":"Nonforfeiture"},{"label":"B","text":"cash"},{"label":"C","text":"Accumulation at Interest"},{"label":"D","text":"Reduced Premium"}],"correctAnswer":"C","explanation":"While policy dividends are not taxable, any interest paid on them is taxable income in the year the interest is credited to the policy.","explanationPt":"Embora os dividendos da apólice não sejam tributáveis, quaisquer juros pagos sobre eles são renda tributável no ano em que forem creditados à apólice.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q167","sourceNumber":167,"duplicateIndex":1,"question":"If an agent would like to sell Variable annuities, which state examination must the agent pass?","options":[{"label":"A","text":"Variable annuities"},{"label":"B","text":"Accident and Health insurance"},{"label":"C","text":"Life insurance"},{"label":"D","text":"Life and Variable contracts"}],"correctAnswer":"D","explanation":"An agent who wants to sell Variable annuities must be licensed by the state which includes examinations in Life and Variable contracts.","explanationPt":"Um agente que deseja vender anuidades variáveis deve ser licenciado pelo estado, o que inclui exames em Vida e em contratos variáveis.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q168","sourceNumber":168,"duplicateIndex":1,"question":"The free-look provision begins","options":[{"label":"A","text":"upon the date of the sales presentation"},{"label":"B","text":"upon receipt of the policy by the producer"},{"label":"C","text":"upon receipt of the policy by the policyowner"},{"label":"D","text":"upon the completion of the application"}],"correctAnswer":"C","explanation":"When delivering the policy, the agent needs to explain that the free-look provision begins upon receipt of the policy by the policyowner.","explanationPt":"Ao entregar a apólice, o agente deve explicar que o período de reflexão (free-look) começa a partir do recebimento da apólice pelo titular.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q169","sourceNumber":169,"duplicateIndex":1,"question":"A life policy that contains a monthly mortality charge as well as self-directed investment choices is called a(n)","options":[{"label":"A","text":"Joint Life policy"},{"label":"B","text":"Endowment"},{"label":"C","text":"Variable Universal Life policy"},{"label":"D","text":"Universal Life policy"}],"correctAnswer":"C","explanation":"Vanable Universal Life is comprised of monthly mortality charges and self directed investment choices.","explanationPt":"A Vida Universal Variável é composta por encargos mensais de mortalidade e opções de investimento autodirigidas.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q170","sourceNumber":170,"duplicateIndex":1,"question":"The cash value in a(n) ______ Life policy may fluctuate to reflect changing assumptions regarding mortality cost, interest, and expense factors.","options":[{"label":"A","text":"Universal"},{"label":"B","text":"Graded"},{"label":"C","text":"Term"},{"label":"D","text":"Endowment"}],"correctAnswer":"A","explanation":"A Universal Life policy has a cash value that may fluctuate to reflect changing assumptions regarding mortality cost interest, and expense factors.","explanationPt":"Uma apólice de Vida Universal tem um valor em dinheiro que pode flutuar para refletir mudanças nas premissas relativas ao custo de mortalidade, juros e fatores de despesa.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q171","sourceNumber":171,"duplicateIndex":1,"question":"How long does the coverage normally remain on a limited-pay life policy?","options":[{"label":"A","text":"age 65"},{"label":"B","text":"age 100"},{"label":"C","text":"when premium payments stop"},{"label":"D","text":"at the discretion of the insurer"}],"correctAnswer":"B","explanation":"Even though the premium payments are limited to a certain period, the insurance protection extends until the insured's death, or to age 100.","explanationPt":"Embora os pagamentos de prêmio sejam limitados a um determinado período, a proteção do seguro se estende até a morte do segurado, ou até os 100 anos de idade.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q172","sourceNumber":172,"duplicateIndex":1,"question":"A licensed agent must be appointed by an insurance company to solicit insurance in Florida. The agent's license will terminate if a certain period of time elapses without being appointed. How long is this period of time?","options":[{"label":"A","text":"12 months"},{"label":"B","text":"24 months"},{"label":"C","text":"36 months"},{"label":"D","text":"48 months"}],"correctAnswer":"D","explanation":"An agent's license will terminate if the agent allows 48 months to elapse without being appointed for the class or classes of insurance listed on the license.","explanationPt":"A licença de um agente será encerrada se ele permitir que se passem 48 meses sem estar credenciado (appointed) para a(s) classe(s) de seguro listada(s) em sua licença.","theme":"Producers and Licensing","jurisdiction":"FL","review":false,"reviewFlags":[]},{"id":"Q173","sourceNumber":173,"duplicateIndex":1,"question":"Dividends paid from a life insurance policy are","options":[{"label":"A","text":"guaranteed"},{"label":"B","text":"taxable"},{"label":"C","text":"issued by the insurer"},{"label":"D","text":"issued by the Department of Insurance"}],"correctAnswer":"C","explanation":"Dividends paid from a life insurance policy are issued by the insurer.","explanationPt":"Os dividendos pagos de uma apólice de seguro de vida são emitidos pela seguradora.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q174","sourceNumber":174,"duplicateIndex":1,"question":"P died five years after purchasing a life policy. While investigating the claim, the insurer discovered material misrepresentations made by P during the application process. Which of these actions will the insurer take?","options":[{"label":"A","text":"Beneficiary will be denied the claim"},{"label":"B","text":"Beneficiary will be denied the claim and refunded all paid premiums"},{"label":"C","text":"Beneficiary will be paid the Death Benefit"},{"label":"D","text":"Beneficiary will be paid a partial Death Benefit"}],"correctAnswer":"C","explanation":"The incontestable clause prevents the insurer from canceling the contract even for a material misrepresentation.","explanationPt":"A cláusula de incontestabilidade impede que a seguradora cancele o contrato mesmo em caso de declaração falsa material.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q175","sourceNumber":175,"duplicateIndex":1,"question":"Which of the following professional organizations has its code of ethics incorporated into Florida law?","options":[{"label":"A","text":"Financial Industry Regulatory Agency (FINRA)"},{"label":"B","text":"National Association of Insurance Commissioners (NAIC)"},{"label":"C","text":"National Association of Insurance and Financial Advisors (NAIFA)"},{"label":"D","text":"The American College of Life Insurance"}],"correctAnswer":"C","explanation":"The professional organization whose code of ethics is incorporated into Florida law, and whose responsibility is to establish the activities of agents is the National Association of Insurance and Financial Advisors.","explanationPt":"A organização profissional cujo código de ética está incorporado à legislação da Flórida, e que é responsável por estabelecer as atividades dos agentes, é a National Association of Insurance and Financial Advisors.","theme":"Producers and Licensing","jurisdiction":"FL","review":false,"reviewFlags":[]},{"id":"Q176","sourceNumber":176,"duplicateIndex":1,"question":"K is shopping for a permanent life insurance policy that will offer her the MOST protection per dollar of annual premium. Which of these policies best fits her needs?","options":[{"label":"A","text":"Endowment"},{"label":"B","text":"Straight life"},{"label":"C","text":"10-Year Renewable Term"},{"label":"D","text":"Joint life"}],"correctAnswer":"B","explanation":"Straight life insurance policies provide an insured the greatest amount of permanent protection per dollar of annual premium.","explanationPt":"As apólices de seguro de vida inteira comum (straight life) oferecem ao segurado a maior quantidade de proteção permanente por dólar de prêmio anual.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q177","sourceNumber":177,"duplicateIndex":1,"question":"Under an Interest Sensitive Whole Life policy,","options":[{"label":"A","text":"premiums are determined by the policyowner"},{"label":"B","text":"no cash value ever accrues"},{"label":"C","text":"the policy normally renews every 10 years"},{"label":"D","text":"cash values are determined by interest rates"}],"correctAnswer":"D","explanation":"Under an Interest Sensitive Whole Life policy, the cash value accrues according to market value, except in the case of some companies which offer a guaranteed interest rate independent of markets","explanationPt":"Em uma apólice de Vida Inteira Sensível a Juros (Interest Sensitive Whole Life), o valor em dinheiro cresce de acordo com o valor de mercado, exceto no caso de algumas seguradoras que oferecem uma taxa de juros garantida independente do mercado.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q178","sourceNumber":178,"duplicateIndex":1,"question":"Which Federal law allows an insurer to obtain an inspection report on a potential insured?","options":[{"label":"A","text":"Medical Information Bureau Act"},{"label":"B","text":"Freedom of Information Act"},{"label":"C","text":"Fair Credit Reporting Act"},{"label":"D","text":"Medical Information Act"}],"correctAnswer":"C","explanation":"The Fair Credit Reporting Act of 1970, or FRA, established procedures for the collection and disclosure of information obtained on consumers through investigation and credit reports.","explanationPt":"A Lei de Relatórios de Crédito Justo de 1970 (Fair Credit Reporting Act, FCRA) estabeleceu procedimentos para a coleta e divulgação de informações obtidas sobre consumidores por meio de investigações e relatórios de crédito.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q179","sourceNumber":179,"duplicateIndex":1,"question":"S buys a $50,000 whole life policy with a $50,000 Accidental Death and Dismemberment rider. S dies 1 year later of natural causes. How much will the insurer pay the beneficiary?","options":[{"label":"A","text":"$100,000"},{"label":"B","text":"$50,000"},{"label":"C","text":"Refund of premiums paid plus interest"},{"label":"D","text":"No claim will be paid because cause of death was from natural causes"}],"correctAnswer":"B","explanation":"In this situation, the beneficiary is entitled to receive $50,000.","explanationPt":"Nesta situação, o beneficiário tem direito a receber $50.000.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q180","sourceNumber":180,"duplicateIndex":1,"question":"The minimum age at which a person can sign a life insurance application is","options":[{"label":"A","text":"15 years"},{"label":"B","text":"16 years"},{"label":"C","text":"17 years"},{"label":"D","text":"18 years"}],"correctAnswer":"A","explanation":"A person 15 years or older may contract for life insurance on his/her own life.","explanationPt":"Uma pessoa com 15 anos ou mais pode contratar seguro de vida sobre sua própria vida.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q181","sourceNumber":181,"duplicateIndex":1,"question":"Which of these statements concerning an Individual Straight Life annuity is accurate?","options":[{"label":"A","text":"Life expectancy of the annuitant is not a factor"},{"label":"B","text":"The payments are received tax-free"},{"label":"C","text":"Only available to employees of nonprofit charitable, educational, and religious organizations"},{"label":"D","text":"Payments are made to an annuitant for life"}],"correctAnswer":"D","explanation":"A Straight Life annuity pays for the life of the annuitant.","explanationPt":"Uma anuidade de Vida Inteira Comum (Straight Life) paga durante toda a vida do anuitante.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q182","sourceNumber":182,"duplicateIndex":1,"question":"Traditional individual retirement annuity (IRA) distributions must start by:","options":[{"label":"A","text":"age 59 1/2"},{"label":"B","text":"age 65"},{"label":"C","text":"April 1st of the year following the year the participant attains age 59 1/2"},{"label":"D","text":"April 1st of the year following the year the participant attains age 70 1/2"}],"correctAnswer":"D","explanation":"Distributions from a traditional IRA must be made by April 1 following the year the participant tums age 70 1/2 or an excise tax will be assessed.","explanationPt":"As distribuições de um IRA tradicional devem ser feitas até 1º de abril seguinte ao ano em que o participante completa 70 anos e meio, sob pena de tributação (imposto especial).","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q183","sourceNumber":183,"duplicateIndex":1,"question":"Which of the following situations are NOT subject to Florida life insurance laws?","options":[{"label":"A","text":"Insurance companies’ day-to-day operations"},{"label":"B","text":"Insurance companies’ life policy replacement requirements"},{"label":"C","text":"Insurance companies’ setting of life insurance policy rates"},{"label":"D","text":"Insurance companies’ guidelines for paying a life insurance claim"}],"correctAnswer":"A","explanation":"Florida life insurance laws apply to all of these situations EXCEPT insurance companies' day-to-day internal operations.","explanationPt":"As leis de seguro de vida da Flórida se aplicam a todas estas situações, EXCETO às operações internas do dia a dia das seguradoras.","theme":"Producers and Licensing","jurisdiction":"FL","review":false,"reviewFlags":[]},{"id":"Q184","sourceNumber":184,"duplicateIndex":1,"question":"The ______ has the right to change a life insurance policy's beneficiary.","options":[{"label":"A","text":"insurer"},{"label":"B","text":"insured"},{"label":"C","text":"policyowner"},{"label":"D","text":"beneficiary"}],"correctAnswer":"C","explanation":"The policyowner has the right to change a life insurance policy's beneficiary.","explanationPt":"O titular da apólice tem o direito de mudar o beneficiário de uma apólice de seguro de vida.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q185","sourceNumber":185,"duplicateIndex":1,"question":"The Consideration clause of an insurance contract includes:","options":[{"label":"A","text":"the buyer's guide"},{"label":"B","text":"a summary of the coverage provided"},{"label":"C","text":"the named beneficiaries"},{"label":"D","text":"the schedule and amount of premium payments"}],"correctAnswer":"D","explanation":"The Consideration clause of a Life or Health policy includes the schedule and amount of premium payments.","explanationPt":"A Cláusula de Contraprestação (Consideration Clause) de uma apólice de Vida ou Saúde inclui o cronograma e o valor dos pagamentos de prêmio.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q186","sourceNumber":186,"duplicateIndex":1,"question":"An architecture firm would stand to lose a lot of money in the event of the death of its project manager. Which type of policy should the firm purchase on its project manager?","options":[{"label":"A","text":"Universal life insurance"},{"label":"B","text":"Key Person insurance"},{"label":"C","text":"Graded insurance"},{"label":"D","text":"Executive insurance"}],"correctAnswer":"B","explanation":"Key person insurance is a type of life insurance policy that provides a death benefit to a business if its owner or another significant employee passes away.","explanationPt":"O seguro de pessoa-chave (key person insurance) é um tipo de apólice de seguro de vida que fornece um benefício por morte a uma empresa caso seu proprietário ou outro funcionário importante venha a falecer.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q187","sourceNumber":187,"duplicateIndex":1,"question":"In a life insurance policy, which feature states that the policy will not cover certain risks?","options":[{"label":"A","text":"Exception"},{"label":"B","text":"Exclusion"},{"label":"C","text":"Ejection"},{"label":"D","text":"Expulsion"}],"correctAnswer":"B","explanation":"The feature of a life insurance policy stating that the policy will not cover certain risks is called an exclusion.","explanationPt":"A característica de uma apólice de seguro de vida que indica que a apólice não cobrirá certos riscos é chamada de exclusão.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q188","sourceNumber":188,"duplicateIndex":1,"question":"Which of the following provisions guarantees that premiums will be waived if a Juvenile Life policyowner becomes disabled?","options":[{"label":"A","text":"Family Maintenance clause"},{"label":"B","text":"Payor clause"},{"label":"C","text":"Assignment provision"},{"label":"D","text":"Automatic Premium Loan provision"}],"correctAnswer":"B","explanation":"A Payor clause ensures that premiums will be waived for a Juvenile Life policy if the policyowner becomes disabled","explanationPt":"Uma cláusula de pagador (Payor clause) garante que os prêmios serão isentos em uma apólice de Vida Juvenil caso o titular fique incapacitado.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q189","sourceNumber":189,"duplicateIndex":1,"question":"Typically a life insurance death benefit is paid by a lump-sum payment. A(n) _____ option is a method of distributing a Life Insurance policy's death benefit OTHER than by a lump sum payment.","options":[{"label":"A","text":"settlement"},{"label":"B","text":"dividend"},{"label":"C","text":"conversion"},{"label":"D","text":"aleatory"}],"correctAnswer":"A","explanation":"A settlement option is a method of distributing a Life Insurance policy's death benefit OTHER than a lump sum payment.","explanationPt":"Uma opção de liquidação (settlement option) é um método de distribuir o benefício por morte de uma apólice de seguro de vida de forma DIFERENTE de um pagamento único.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q190","sourceNumber":190,"duplicateIndex":1,"question":"How does a typical Variable Life Policy investment account grow?","options":[{"label":"A","text":"Tied to price of gold"},{"label":"B","text":"Through mutual funds, stocks, bonds"},{"label":"C","text":"Based on returns from insurer's general account"},{"label":"D","text":"Tied to Treasury Bills"}],"correctAnswer":"B","explanation":"Variable Life Policy has investment values based instruments such as mutual funds, stocks, and bonds.","explanationPt":"Uma apólice de Vida Variável tem valores de investimento baseados em instrumentos como fundos mútuos, ações e títulos.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q191","sourceNumber":191,"duplicateIndex":1,"question":"Group Life policies in Florida are required to contain a conversion privilege that allows for conversion","options":[{"label":"A","text":"with evidence of insurability"},{"label":"B","text":"to an individual policy for a stated period of time"},{"label":"C","text":"only if the premiums are paid by the employer"},{"label":"D","text":"to an individual policy at anytime"}],"correctAnswer":"B","explanation":"In Florida, Group Life policies must contain a conversion privilege that allows for conversion to an individual policy for a specified period of time.","explanationPt":"Na Flórida, as apólices de Vida em Grupo devem conter um privilégio de conversão que permita a conversão para uma apólice individual dentro de um período de tempo especificado.","theme":"Life Insurance Policies","jurisdiction":"FL","review":false,"reviewFlags":[]},{"id":"Q192","sourceNumber":192,"duplicateIndex":1,"question":"An example of an unfair claims settlement practice is","options":[{"label":"A","text":"making it mandatory that proof of loss be provided for each claim"},{"label":"B","text":"requiring a time limit for submitting a claim"},{"label":"C","text":"paying a claim in a timely matter"},{"label":"D","text":"turning down a claim without providing the basis of denial"}],"correctAnswer":"D","explanation":"Denying an insured's claim without indicating the basis of denial under the policy is considered an unfair claim settlement practice.","explanationPt":"Negar o sinistro de um segurado sem indicar a base da negação de acordo com a apólice é considerado uma prática desleal de liquidação de sinistros.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q193","sourceNumber":193,"duplicateIndex":1,"question":"The act of an insurance company publishing misleading information about its policy's pro’ called","options":[{"label":"A","text":"coercion"},{"label":"B","text":"false advertising"},{"label":"C","text":"twisting"},{"label":"D","text":"intimidation"}],"correctAnswer":"B","explanation":"An insurance company that publishes misleading information about insurance coverage may be found guilty of false advertising.","explanationPt":"Uma seguradora que publica informações enganosas sobre a cobertura de seguro pode ser considerada culpada de propaganda enganosa.","theme":"Ethics and Compliance","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q194","sourceNumber":194,"duplicateIndex":1,"question":"D the agent met with a prospect and ended up selling an insurance policy. While filling out the insurance application, D makes a mistake. In this situation, D MUST","options":[{"label":"A","text":"correct the information with no further action from prospect necessary"},{"label":"B","text":"receive a verbal acknowledgement from prospect of the mistake made"},{"label":"C","text":"request that the insurer issue the policy with a rating"},{"label":"D","text":"correct the information and have the prospect initial the change"}],"correctAnswer":"D","explanation":"If an agent makes an error on an insurance application the agent must correct the information and have the applicant initial the changes.","explanationPt":"Se um agente cometer um erro em uma proposta de seguro, ele deve corrigir a informação e pedir ao proponente que rubrique as alterações.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q195","sourceNumber":195,"duplicateIndex":1,"question":"Which of these is NOT an element of Life insurance premiums?","options":[{"label":"A","text":"Mortality rate"},{"label":"B","text":"Insurer's expenses"},{"label":"C","text":"Interest credit"},{"label":"D","text":"Morbidity rate"}],"correctAnswer":"D","explanation":"Morbidity rate is NOT an element of life insurance premiums.","explanationPt":"A taxa de morbidade NÃO é um elemento dos prêmios de seguro de vida.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q196","sourceNumber":196,"duplicateIndex":1,"question":"Which of the following features of a group Term Life policy enables an individual to leave the group and continue his or her insurance without providing evidence of insurability?","options":[{"label":"A","text":"Owner's Rights clause"},{"label":"B","text":"Incontestable Period"},{"label":"C","text":"Insuring Agreement"},{"label":"D","text":"Conversion privilege"}],"correctAnswer":"D","explanation":"The conversion privilege allows an individual to leave the group term plan and continue his or her insurance without provide evidence of insurability.","explanationPt":"O privilégio de conversão permite que um indivíduo saia do plano de vida em grupo temporário e continue seu seguro sem apresentar prova de segurabilidade.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q197","sourceNumber":197,"duplicateIndex":1,"question":"A Whole Life insurance policyowner does NOT have the right to","options":[{"label":"A","text":"designate a beneficiary"},{"label":"B","text":"take out a policy loan"},{"label":"C","text":"change the grace period"},{"label":"D","text":"assign the policy"}],"correctAnswer":"C","explanation":"All of these are rights of a Whole Life insurance policyowner EXCEPT “change the grace period”.","explanationPt":"Todos estes são direitos do titular de uma apólice de Vida Inteira, EXCETO \"alterar o período de carência (grace period)\".","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q198","sourceNumber":198,"duplicateIndex":1,"question":"What is the excise tax rate the IRS imposes on individuals aged 70 1/2 or older who do not take the required minimum distributions from their qualified retirement plan?","options":[{"label":"A","text":"30%"},{"label":"B","text":"40%"},{"label":"C","text":"50%"},{"label":"D","text":"60%"}],"correctAnswer":"C","explanation":"Distributions must be made by April 1 following the year the participant turns age 70 1/2 or a 50% excise tax will be assessed on the amount that should have been withdrawn.","explanationPt":"As distribuições devem ser feitas até 1º de abril seguinte ao ano em que o participante completa 70 anos e meio, ou será cobrado um imposto especial de 50% sobre o valor que deveria ter sido retirado.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q199","sourceNumber":199,"duplicateIndex":1,"question":"What would be the disadvantage of naming a trust as beneficiary of a life insurance policy?","options":[{"label":"A","text":"Trusts cannot be formed for life insurance purposes"},{"label":"B","text":"Trust administration fees would reduce policy proceeds"},{"label":"C","text":"Trusts cannot be used if a minor is the beneficiary"},{"label":"D","text":"Trustee must be a bank or brokerage"}],"correctAnswer":"B","explanation":"One possible disadvantage of naming a trust as beneficiary of a life insurance policy is that the policy proceeds may be reduced by trust administration fees.","explanationPt":"Uma possível desvantagem de nomear um trust como beneficiário de uma apólice de seguro de vida é que os valores da apólice podem ser reduzidos pelas taxas de administração do trust.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q200","sourceNumber":200,"duplicateIndex":1,"question":"What would be a valid reason for naming a trust as the beneficiary of a life insurance policy as opposed to naming an individual?","options":[{"label":"A","text":"Avoiding probate"},{"label":"B","text":"Management of proceeds would be provided"},{"label":"C","text":"Trustee can pay off any existing policy loans"},{"label":"D","text":"More settlement options available with a trustee"}],"correctAnswer":"B","explanation":"One reason for naming a trust rather than an individual as the beneficiary of a life insurance policy is to provide management of the proceeds.","explanationPt":"Uma razão para nomear um trust, em vez de um indivíduo, como beneficiário de uma apólice de seguro de vida é fornecer gestão dos valores recebidos.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q201","sourceNumber":201,"duplicateIndex":1,"question":"A life annuity feature which provides benefit payments for a minimum number of years, no matter when the annuitant dies, is called","options":[{"label":"A","text":"fixed period"},{"label":"B","text":"period certain"},{"label":"C","text":"installment refund"},{"label":"D","text":"straight life"}],"correctAnswer":"B","explanation":"Correct. A life annuity feature which provides benefit payments for a minimum number of years, no matter when the annuitant dies, is called period certain.","explanationPt":"Correto. Uma característica de anuidade vitalícia que garante o pagamento de benefícios por um número mínimo de anos, independentemente de quando o anuitante morrer, é chamada de período certo (period certain).","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q202","sourceNumber":202,"duplicateIndex":1,"question":"ABC Company is attempting to minimize the severity of potential losses within its company. The company is engaged in risk","options":[{"label":"A","text":"transference"},{"label":"B","text":"retention"},{"label":"C","text":"reduction"},{"label":"D","text":"avoidance"}],"correctAnswer":"C","explanation":"Risk reduction can reduce the chance that a particular loss will occur, or it can reduce the amount of a potential loss if it occurs.","explanationPt":"A redução de risco pode diminuir a chance de que uma determinada perda ocorra, ou pode reduzir o valor de uma perda potencial caso ela ocorra.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q203","sourceNumber":203,"duplicateIndex":1,"question":"How is the insured protected if a payor benefit rider is attached to the life insurance policy?","options":[{"label":"A","text":"Premiums are waived if the payor becomes financially insolvent"},{"label":"B","text":"Policy loan will automatically cover the premiums if payor becomes disabled or dies"},{"label":"C","text":"Premium payments are waived in the event the premium payor dies or becomes disabled"},{"label":"D","text":"Policy loan will automatically cover the premiums if payor becomes financially insolvent"}],"correctAnswer":"C","explanation":"The insured in a life insurance policy with a payor benefit rider is protected from the cost of premium payments if the premium payor dies or becomes disabled.","explanationPt":"O segurado em uma apólice de seguro de vida com cláusula adicional de benefício de pagador (payor benefit rider) fica protegido do custo dos pagamentos de prêmio caso o pagador do prêmio morra ou fique incapacitado.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q204","sourceNumber":204,"duplicateIndex":1,"question":"A material change in a modified endowment contract (MEC) results in","options":[{"label":"A","text":"the contract becoming void"},{"label":"B","text":"a new contestable period"},{"label":"C","text":"the seven pay test, adjusted for cash value, applies again"},{"label":"D","text":"a tax penalty"}],"correctAnswer":"C","explanation":"Under the rules for an MEC, if there is a material change in the contract, the seven pay test applies again.","explanationPt":"De acordo com as regras para um MEC, se houver uma alteração material no contrato, o teste dos sete pagamentos (seven pay test) se aplica novamente.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q205","sourceNumber":205,"duplicateIndex":1,"question":"Laura added a children's rider to her life insurance policy. What type of coverage was added?","options":[{"label":"A","text":"Level term"},{"label":"B","text":"Increasing term"},{"label":"C","text":"Decreasing term"},{"label":"D","text":"Juvenile term"}],"correctAnswer":"A","explanation":"Level term is provided by adding a children's rider to a life insurance policy.","explanationPt":"O termo nivelado (level term) é fornecido ao adicionar uma cláusula adicional infantil a uma apólice de seguro de vida.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q206","sourceNumber":206,"duplicateIndex":1,"question":"Tim is retired and has recently separated from his wife. He receives benefits from a qualified retirement plan through his former employer. The plan's trustee has decided to split these benefit payments between Tim and his estranged wife. This decision is likely in violation of which IRS rule?","options":[{"label":"A","text":"Reasonable expectations"},{"label":"B","text":"Alienation of benefits"},{"label":"C","text":"Minimum coverage"},{"label":"D","text":"Indemnity of benefits"}],"correctAnswer":"B","explanation":"Alienation of benefits involves the assignment of a pension or retirement plan participant's benefits to another person. It is permitted only under exceptional circumstances per IRS rules, such as certain participant loans and certain domestic relations orders. With no domestic relations order, this trustee is likely in violation of this rule.","explanationPt":"A alienação de benefícios envolve a cessão dos benefícios de um participante de plano de pensão ou aposentadoria a outra pessoa. Isso só é permitido em circunstâncias excepcionais, de acordo com as regras do IRS, como certos empréstimos a participantes e determinadas ordens de relações domésticas. Sem uma ordem de relações domésticas, este fiduciário provavelmente está violando essa regra.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q207","sourceNumber":207,"duplicateIndex":1,"question":"A 55 year old recently received a $30,000 distribution from a previous employer's 401k plan, minus $6,000 for income tax withholding. Which federal taxes apply if none of the funds were rolled over?","options":[{"label":"A","text":"Only income taxes on $30,000"},{"label":"B","text":"Only income taxes on $24,000"},{"label":"C","text":"Income taxes plus a 10% penalty tax on $30,000"},{"label":"D","text":"Income taxes plus a 10% penalty tax on $24,000"}],"correctAnswer":"C","explanation":"All withdrawals from a qualified retirement plan are taxable as current income. In addition, any withdrawals made before age 59 1/2 is subject to an additional tax penalty of 10% of the amount withdrawn.","explanationPt":"Todos os saques de um plano de aposentadoria qualificado são tributáveis como renda corrente. Além disso, qualquer saque feito antes dos 59 anos e meio está sujeito a uma penalidade fiscal adicional de 10% do valor sacado.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q208","sourceNumber":208,"duplicateIndex":1,"question":"A life policy's spendthrift clause would have no effect if the beneficiary is paid the proceeds as a","options":[{"label":"A","text":"fixed-period installment"},{"label":"B","text":"life income option"},{"label":"C","text":"fixed-amount installment"},{"label":"D","text":"lump-sum payment"}],"correctAnswer":"D","explanation":"A spendthrift clause in a life insurance policy would have no effect if the beneficiary receives the proceeds as one lump sum payment.","explanationPt":"Uma cláusula de proteção contra dilapidação (spendthrift clause) não teria efeito se o beneficiário receber os valores em um único pagamento total.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q209","sourceNumber":209,"duplicateIndex":1,"question":"All of these statements correctly describe an aleatory contract EXCEPT","options":[{"label":"A","text":"A legal wager is considered an aleatory contract"},{"label":"B","text":"Potential unequal exchange of value for both parties"},{"label":"C","text":"Only one party makes any kind of legally enforceable offer"},{"label":"D","text":"Element of chance is involved"}],"correctAnswer":"C","explanation":"Insurance contracts are aleatory, which means there is an unequal exchange. The premiums paid by the applicant are 'small in relation to the amount that will be paid by the insurance company in the event of a loss.","explanationPt":"Os contratos de seguro são aleatórios (aleatory), o que significa que há uma troca desigual. Os prêmios pagos pelo proponente são pequenos em relação ao valor que será pago pela seguradora em caso de sinistro.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q210","sourceNumber":210,"duplicateIndex":1,"question":"In what way are insurance policies said to be aleatory?","options":[{"label":"A","text":"Only one party makes any kind of enforceable promise"},{"label":"B","text":"Involves the potential for the unequal exchange of value"},{"label":"C","text":"Contract is prepared by only one party"},{"label":"D","text":"Vagueness in a contract's wording is resolved in favor of the policyowner"}],"correctAnswer":"B","explanation":"Insurance contracts are considered to be aleatory because the exchange of values may be unequal.","explanationPt":"Os contratos de seguro são considerados aleatórios porque a troca de valores pode ser desigual.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q211","sourceNumber":211,"duplicateIndex":1,"question":"A group-owned insurance company that is formed to assume and spread the liability risks of its members is known as","options":[{"label":"A","text":"a treaty insurer"},{"label":"B","text":"Risk retention group"},{"label":"C","text":"risk assumption group"},{"label":"D","text":"captive insurer"}],"correctAnswer":"B","explanation":"A group-owned insurer whose primary activity consists of assuming and spreading the liability risks of its members is called a risk retention group.","explanationPt":"Uma seguradora de propriedade coletiva cuja atividade principal consiste em assumir e distribuir os riscos de responsabilidade de seus membros é chamada de grupo de retenção de risco (risk retention group).","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q212","sourceNumber":212,"duplicateIndex":1,"question":"Who regulates an insurer's claim settlement practices?","options":[{"label":"A","text":"National Association of Claim Adjusters"},{"label":"B","text":"State attorney general"},{"label":"C","text":"National Association of Insurance Commissioners"},{"label":"D","text":"State insurance departments"}],"correctAnswer":"D","explanation":"State insurance departments regulate claim settlement practices.","explanationPt":"Os departamentos estaduais de seguros regulam as práticas de liquidação de sinistros.","theme":"State Law","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q213","sourceNumber":213,"duplicateIndex":1,"question":"Peter, age 50, surrenders his modified endowment contract (MEC). How is the gain treated in terms of federal income taxes?","options":[{"label":"A","text":"The gain is treated as taxable income and a penalty tax is imposed on the gain"},{"label":"B","text":"The gain is treated as taxable income but no additional penalties are applied"},{"label":"C","text":"The gain is not taxable but a penalty is assessed"},{"label":"D","text":"Surrendering an MEC is considered a tax and penalty-free transaction"}],"correctAnswer":"A","explanation":"If an MEC is surrendered prior to age 59 the gain is taxable as well as a 10% penalty imposed on that gain.","explanationPt":"Se um MEC for resgatado antes dos 59 anos, o ganho é tributável, além de uma penalidade de 10% imposta sobre esse ganho.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q214","sourceNumber":214,"duplicateIndex":1,"question":"The courts will normally interpret a policy in favor of the insured when the meaning of the policy is not clear. This is because an insurance policy is a(n)","options":[{"label":"A","text":"warranty contract"},{"label":"B","text":"aleatory contract"},{"label":"C","text":"contract of adhesion"},{"label":"D","text":"unilateral contract"}],"correctAnswer":"C","explanation":"In a case where the meaning of an insurance policy is not clear, a court of law will usually interpret the policy in favor of the insured because an insurance contract is a contract of adhesion.","explanationPt":"Em um caso em que o significado de uma apólice de seguro não é claro, um tribunal geralmente interpretará a apólice em favor do segurado, pois um contrato de seguro é um contrato de adesão.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q215","sourceNumber":215,"duplicateIndex":1,"question":"Which life insurance policy provision prohibits a beneficiary from commuting, encumbering, withdrawing, or assigning\" any portion of the proceeds prior to actual receipt from the company?","options":[{"label":"A","text":"Insuring clause"},{"label":"B","text":"Spendthrift clause"},{"label":"C","text":"Nonforfeiture provision"},{"label":"D","text":"Collateral Provision"}],"correctAnswer":"B","explanation":"A spendthrift clause prevents a beneficiary from recklessly spending benefits by requiring the benefits to be paid in fixed amounts or installments over a certain period of time.","explanationPt":"Uma cláusula de proteção contra dilapidação (spendthrift clause) impede que o beneficiário gaste os benefícios de forma imprudente, exigindo que os valores sejam pagos em quantias fixas ou parcelas ao longo de um determinado período.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q216","sourceNumber":216,"duplicateIndex":1,"question":"The owner of a single premium deferred annuity is entitled to do all of these EXCEPT","options":[{"label":"A","text":"make additional payments into the annuity"},{"label":"B","text":"choose the length of the payout period"},{"label":"C","text":"choose who will be the recipient of the annuity payments"},{"label":"D","text":"cash surrender the contract"}],"correctAnswer":"A","explanation":"Single premium deferred annuities involve a single, lump-sum deposit.","explanationPt":"As anuidades diferidas de prêmio único envolvem um único depósito em quantia total.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q217","sourceNumber":217,"duplicateIndex":1,"question":"XYZ Corp gives money to an employee to purchase a life insurance policy and allows the employee to select the beneficiary. What kind of plan is this?","options":[{"label":"A","text":"Split-dollar"},{"label":"B","text":"Cross purchase"},{"label":"C","text":"Key employee"},{"label":"D","text":"Deferred compensation"}],"correctAnswer":"A","explanation":"A split-dollar plan is an arrangement where an employer and an employee share in the cost of purchasing a life insurance policy on the employee. The employee is also allowed to name the beneficiary.","explanationPt":"Um plano \"split-dollar\" é um arranjo no qual o empregador e o empregado dividem o custo da compra de uma apólice de seguro de vida sobre o empregado. O empregado também pode indicar o beneficiário.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q218","sourceNumber":218,"duplicateIndex":1,"question":"The interest credited to the cash values of personally-owned non-qualified annuities is considered","options":[{"label":"A","text":"a tax credit"},{"label":"B","text":"Tax-deferred"},{"label":"C","text":"tax-deductible"},{"label":"D","text":"tax-exempt"}],"correctAnswer":"B","explanation":"Interest credited to the cash values of annuities is deferred until distribution.","explanationPt":"Os juros creditados aos valores em dinheiro das anuidades são diferidos até a distribuição.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q219","sourceNumber":219,"duplicateIndex":1,"question":"Tim is confined to a nursing home but doesn't have a terminal illness. Which life insurance rider is designed to help pay for this type of expense?","options":[{"label":"A","text":"Cash value rider"},{"label":"B","text":"Viatical rider"},{"label":"C","text":"Accelerated (living) benefit rider"},{"label":"D","text":"Long-term care benefit rider"}],"correctAnswer":"D","explanation":"A long-term care benefit rider can help pay for nursing home expenses by decreasing the amount of the life insurance policy's death benefit.","explanationPt":"Uma cláusula adicional de cuidados de longo prazo (long-term care rider) pode ajudar a pagar despesas de casa de repouso ao reduzir o valor do benefício por morte da apólice de seguro de vida.","theme":"Health Insurance","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q220","sourceNumber":220,"duplicateIndex":1,"question":"An individual working part-time has a gross income of $5,000 for the year. If this individual has an IRA, what is the maximum deductible IRA contribution allowable?","options":[{"label":"A","text":"No deduction allowed"},{"label":"B","text":"$5,000"},{"label":"C","text":"$2,000"},{"label":"D","text":"$1,000"}],"correctAnswer":"B","explanation":"In this situation, the maximum allowable IRA contribution is $5,000.","explanationPt":"Nesta situação, a contribuição máxima permitida para o IRA é de $5.000.","theme":"Health Insurance","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q221","sourceNumber":221,"duplicateIndex":1,"question":"The Medical Information Bureau consists of members from which group?","options":[{"label":"A","text":"Doctors"},{"label":"B","text":"Hospitals"},{"label":"C","text":"Insurance companies"},{"label":"D","text":"Underwriters"}],"correctAnswer":"C","explanation":"Insurance companies make up the membership of the Medical Information Bureau (MIB).","explanationPt":"As seguradoras compõem os membros do Medical Information Bureau (MIB).","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q222","sourceNumber":222,"duplicateIndex":1,"question":"Under which circumstance is the interest rate guaranteed within a market value adjusted annuity?","options":[{"label":"A","text":"When the contract has been held for the period specified in the policy"},{"label":"B","text":"For the entire length of the contract"},{"label":"C","text":"Never"},{"label":"D","text":"When the cash value has reached a stated minimum amount"}],"correctAnswer":"A","explanation":"The interest rate applied to the cash value within a market value adjusted annuity is guaranteed only when the contract has been in force for a stated time period.","explanationPt":"A taxa de juros aplicada ao valor em dinheiro de uma anuidade ajustada ao valor de mercado (market value adjusted) só é garantida quando o contrato estiver em vigor por um período de tempo determinado.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q223","sourceNumber":223,"duplicateIndex":1,"question":"Which life insurance policy option allows the policyowner to have coverage equal to the net death benefit of the lapsed policy?","options":[{"label":"A","text":"Reduced paid-up nonforfeiture option"},{"label":"B","text":"Accelerated benefits option"},{"label":"C","text":"Extended term nonforfeiture option"},{"label":"D","text":"Cash surrender option"}],"correctAnswer":"C","explanation":"The extended term nonforfeiture option provides coverage equal to the death benefit of the lapsed policy.","explanationPt":"A opção de não confisco de termo estendido (extended term) oferece cobertura igual ao benefício por morte da apólice caducada.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q224","sourceNumber":224,"duplicateIndex":1,"question":"In the event of premium default, which life insurance provision will use the cash value to keep the policy in force?","options":[{"label":"A","text":"Waiver of premium"},{"label":"B","text":"Automatic premium loan"},{"label":"C","text":"Reinstatement"},{"label":"D","text":"Policy loan"}],"correctAnswer":"B","explanation":"The automatic premium loan provision uses the cash value to keep the original policy in force in case of premium default.","explanationPt":"A cláusula de empréstimo automático de prêmio usa o valor em dinheiro para manter a apólice original em vigor em caso de falta de pagamento do prêmio.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q225","sourceNumber":225,"duplicateIndex":1,"question":"Which of these life insurance policies does NOT contain a cash value provision?","options":[{"label":"A","text":"Modified whole life"},{"label":"B","text":"Universal life"},{"label":"C","text":"Decreasing term life"},{"label":"D","text":"Adjustable life"}],"correctAnswer":"C","explanation":"Term life products do not have the ability to gain cash value, so cash value provisions would not be found in any type of erm insurance product.","explanationPt":"Os produtos de seguro de vida temporário (term life) não têm a capacidade de gerar valor em dinheiro; portanto, não existem cláusulas de valor em dinheiro em nenhum tipo de produto de seguro temporário.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q226","sourceNumber":226,"duplicateIndex":1,"question":"XYZ Corp has implemented a qualified retirement plan. This plan may NOT discriminate","options":[{"label":"A","text":"against employees under the age of 21"},{"label":"B","text":"in favor of highly compensated employees"},{"label":"C","text":"in favor of employees with higher seniority"},{"label":"D","text":"against stockholders"}],"correctAnswer":"B","explanation":"A qualified retirement plan may not discriminate in favor of highly compensated employees.","explanationPt":"Um plano de aposentadoria qualificado não pode discriminar em favor de funcionários altamente remunerados.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q227","sourceNumber":227,"duplicateIndex":1,"question":"When does the producer give a premium receipt for a life insurance application?","options":[{"label":"A","text":"When the application has been approved"},{"label":"B","text":"When the initial premium has been paid with the application"},{"label":"C","text":"During the medical exam"},{"label":"D","text":"When the completed application has been collected"}],"correctAnswer":"B","explanation":"A premium receipt is given to an applicant when the initial premium is paid with the application.","explanationPt":"Um recibo de prêmio é entregue ao proponente quando o prêmio inicial é pago junto com a proposta.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q228","sourceNumber":228,"duplicateIndex":1,"question":"What is another name for a Keogh plan?","options":[{"label":"A","text":"Roth IRA"},{"label":"B","text":"HR 10 plan"},{"label":"C","text":"Rollover plan"},{"label":"D","text":"1040 plan"}],"correctAnswer":"B","explanation":"The Keogh plan, or HR 10, is an employer-funded, tax-deferred retirement plan designed for unincorporated businesses or self-employed.","explanationPt":"A resposta correta é B: plano HR 10. Isso está correto porque o plano Keogh, ou HR 10, é um plano de aposentadoria com imposto diferido, financiado pelo empregador, criado para empresas não constituídas em sociedade ou para autônomos.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX001","sourceNumber":null,"duplicateIndex":1,"question":"A Keogh plan is a(n)","options":[{"label":"A","text":"unqualified retirement plan for large corporations"},{"label":"B","text":"qualified retirement plan for the self employed"},{"label":"C","text":"tax-exempt annuity for government workers"},{"label":"D","text":"split dollar plan for key employees"}],"correctAnswer":"B","explanation":"A Keogh plan is a qualified retirement plan for the self employed.","explanationPt":"A resposta correta é B: um plano de aposentadoria qualificado para autônomos. Isso está correto porque um plano Keogh é um plano de aposentadoria qualificado destinado a trabalhadores autônomos.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q229","sourceNumber":229,"duplicateIndex":1,"question":"A Massachusetts producer has violated an Unfair Trade Practice law. This producer may be fined up to ______ per violation.","options":[{"label":"A","text":"$1,000"},{"label":"B","text":"$3,000"},{"label":"C","text":"$5,000"},{"label":"D","text":"$10,000"}],"correctAnswer":"A","explanation":"If the violation was intentional, the Commissioner may impose a fine of up to $1,000 for each violation.","explanationPt":"Se a violação foi intencional, o Comissário pode impor uma multa de até $1.000 por violação.","theme":"Producers and Licensing","jurisdiction":"MA","review":false,"reviewFlags":[]},{"id":"Q230","sourceNumber":230,"duplicateIndex":1,"question":"Which of these is NOT considered a Federal punishment for unfair and deceptive insurance practices?","options":[{"label":"A","text":"Prison sentence"},{"label":"B","text":"Revocation of license"},{"label":"C","text":"Monetary fine"},{"label":"D","text":"Community service"}],"correctAnswer":"D","explanation":"Under federal law, punishment for unfair and deceptive insurance practices may include a fine, imprisonment and license revocation but not community service.","explanationPt":"Segundo a lei federal, a punição por práticas de seguro desleais e enganosas pode incluir multa, prisão e revogação da licença, mas não prestação de serviços comunitários.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q231","sourceNumber":231,"duplicateIndex":1,"question":"ERISA requires that a Summary Plan Description must be provided to a new plan member within how many days following the new member's eligibility date?","options":[{"label":"A","text":"30"},{"label":"B","text":"45"},{"label":"C","text":"90"},{"label":"D","text":"120"}],"correctAnswer":"C","explanation":"New employees must receive a copy of their plan sponsor's latest Summary Plan Description within 90 days after becoming covered by the plan.","explanationPt":"Os novos funcionários devem receber uma cópia da mais recente Descrição Resumida do Plano (Summary Plan Description) de seu patrocinador do plano dentro de 90 dias após passarem a ser cobertos pelo plano.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q232","sourceNumber":232,"duplicateIndex":1,"question":"According to ERISA regulations, a Summary Plan Description must be provided to a new plan member within ___ days of the member's eligibility date.","options":[{"label":"A","text":"30"},{"label":"B","text":"60"},{"label":"C","text":"90"},{"label":"D","text":"120"}],"correctAnswer":"C","explanation":"A Summary Plan Description must be provided within 90 days following a new plan member's eligibility date.","explanationPt":"A resposta correta é C: 90. Isso está correto porque uma Descrição Resumida do Plano (Summary Plan Description) deve ser fornecida dentro de 90 dias a partir da data de elegibilidade de um novo membro do plano.","theme":"General Insurance Concepts","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX002","sourceNumber":null,"duplicateIndex":1,"question":"An employee welfare plan exempt from ERISA regulations would be","options":[{"label":"A","text":"church plans"},{"label":"B","text":"indemnity plans"},{"label":"C","text":"split dollar plans"},{"label":"D","text":"accident only plans"}],"correctAnswer":"A","explanation":"Church plans are exempt from ERISA regulations.","explanationPt":"A resposta correta é A: planos de igrejas. Isso está correto porque os planos de igrejas são isentos das regulamentações da ERISA.","theme":"General Insurance Concepts","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q233","sourceNumber":233,"duplicateIndex":1,"question":"The administrator for a corporate pension plan bought an accumulation annuity contract for its 2,000 employees. All 2,000 participating employees received certificates of participation. What kind of contract is this?","options":[{"label":"A","text":"403(b) plan"},{"label":"B","text":"Group deferred annuity"},{"label":"C","text":"Group immediate annuity"},{"label":"D","text":"Deferred compensation plan"}],"correctAnswer":"B","explanation":"With a group deferred annuity, the employer holds a master contract and certificates of participation are given to the persons covered by the plan. It is considered a deferred annuity because of the word \"accumulation\".","explanationPt":"Em uma anuidade diferida em grupo, o empregador detém um contrato mestre, e certificados de participação são entregues às pessoas cobertas pelo plano. É considerada uma anuidade diferida por causa da palavra \"acumulação\".","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q234","sourceNumber":234,"duplicateIndex":1,"question":"A life insurance policy's waiver of premium rider has the ability to","options":[{"label":"A","text":"waive the premium payments in the event the insured becomes financially insolvent"},{"label":"B","text":"relieve the insured of premium payments following an initial waiting period after the insured becomes totally disabled"},{"label":"C","text":"provide a policy loan to cover the premium payments in the event the insured becomes totally disabled"},{"label":"D","text":"waive the premiums on this policy as well as any other insurance policies belonging to the insured in the event of total disability"}],"correctAnswer":"B","explanation":"The waiver of premium relieves the insured of premium payments following an initial waiting period after the insured becomes totally disabled.","explanationPt":"A isenção de prêmio (waiver of premium) libera o segurado dos pagamentos de prêmio após um período de espera inicial, depois que o segurado se torna totalmente incapacitado.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q235","sourceNumber":235,"duplicateIndex":1,"question":"What is the face amount of a $50,000 graded death benefit life insurance policy when the policy is issued?","options":[{"label":"A","text":"$0"},{"label":"B","text":"$50,000"},{"label":"C","text":"Under $50,000 initially, but decreases annually over time"},{"label":"D","text":"Under $50,000 initially, but increases over time"}],"correctAnswer":"D","explanation":"The initial face amount of a $50,000 graded death benefit life insurance policy is under $50,000, but increases annually until fully insured.","explanationPt":"O valor de face inicial de uma apólice de seguro de vida com benefício por morte gradual (graded death benefit) de $50.000 é inferior a $50.000, mas aumenta anualmente até estar totalmente segurado.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q236","sourceNumber":236,"duplicateIndex":1,"question":"When a producer is appointed, the _______ is considered the principal.","options":[{"label":"A","text":"insurer"},{"label":"B","text":"Governor"},{"label":"C","text":"producer"},{"label":"D","text":"Superintendent"}],"correctAnswer":"A","explanation":"After a producer is appointed, the insurance company is considered the principal.","explanationPt":"Depois que um produtor é credenciado (appointed), a seguradora é considerada a principal (principal).","theme":"Producers and Licensing","jurisdiction":"MA","review":false,"reviewFlags":[]},{"id":"Q237","sourceNumber":237,"duplicateIndex":1,"question":"Where is the difference between a standard risk and a substandard risk reflected?","options":[{"label":"A","text":"Backdating"},{"label":"B","text":"Coverage is not offered"},{"label":"C","text":"Premium charges"},{"label":"D","text":"Back-end charges"}],"correctAnswer":"C","explanation":"The difference between a standard risk and a substandard risk is reflected in the premium charges.","explanationPt":"A diferença entre um risco padrão e um risco substandard é refletida nos valores dos prêmios cobrados.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q238","sourceNumber":238,"duplicateIndex":1,"question":"An agent's authority to bind an insurer to an insurance contract may be granted in the","options":[{"label":"A","text":"agent's contract and the insurance company's appointment"},{"label":"B","text":"agent's license and insurance company's certificate of authority"},{"label":"C","text":"buyer's guide and policy summary"},{"label":"D","text":"state guaranty association"}],"correctAnswer":"A","explanation":"The agent's contract and appointment with the insurance company grants the authority to bind an insurer to an insurance contract.","explanationPt":"O contrato e o credenciamento do agente com a seguradora concedem a autoridade para vincular a seguradora a um contrato de seguro.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q239","sourceNumber":239,"duplicateIndex":1,"question":"Which statement concerning a deferred annuity contract is correct?","options":[{"label":"A","text":"The contract cannot be assignable by the owner"},{"label":"B","text":"Requires a single premium payment"},{"label":"C","text":"The owner can be the beneficiary, annuitant, or neither"},{"label":"D","text":"Benefits start immediately after contract formation"}],"correctAnswer":"C","explanation":"An owner may be the annuitant, beneficiary, or neither in a deferred annuity.","explanationPt":"Em uma anuidade diferida, o titular pode ser o anuitante, o beneficiário, ou nenhum dos dois.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q240","sourceNumber":240,"duplicateIndex":1,"question":"A policyowner fell behind on the premium payments of a whole life policy and is now in the grace period. How much will the beneficiary receive if the insured dies during this grace period and the policy also contains an outstanding policy loan?","options":[{"label":"A","text":"Full face amount"},{"label":"B","text":"Face amount minus the past-due premium"},{"label":"C","text":"Face amount minus the loan balance"},{"label":"D","text":"Face amount minus the loan balance and past-due premium"}],"correctAnswer":"D","explanation":"The beneficiary in this case will receive the face amount minus the loan amount and the overdue premium.","explanationPt":"O beneficiário, neste caso, receberá o valor de face menos o valor do empréstimo e o prêmio em atraso.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q241","sourceNumber":241,"duplicateIndex":1,"question":"How long does protection normally extend to under a limited pay whole life policy?","options":[{"label":"A","text":"It depends on the performance of the underlying investment account"},{"label":"B","text":"When premiums are no longer required as stated in the contract"},{"label":"C","text":"Until age 65"},{"label":"D","text":"Until age 100"}],"correctAnswer":"D","explanation":"Under a limited payment whole life insurance policy, protection usually continues to age 100.","explanationPt":"Em uma apólice de seguro de vida inteira com pagamento limitado, a proteção geralmente continua até os 100 anos de idade.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q242","sourceNumber":242,"duplicateIndex":1,"question":"How does a continuous premium whole life policy differ from a limited payment whole life policy?","options":[{"label":"A","text":"The time period in which premiums will be paid"},{"label":"B","text":"The availability of cash value loans"},{"label":"C","text":"The availability of nonforfeiture options"},{"label":"D","text":"The settlement options"}],"correctAnswer":"A","explanation":"The feature that separates a continuous premium whole life policy from a limited payment whole life policy is the length of time premiums will be paid.","explanationPt":"A característica que diferencia uma apólice de vida inteira com prêmio contínuo de uma apólice de vida inteira com pagamento limitado é o período de tempo durante o qual os prêmios serão pagos.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q243","sourceNumber":243,"duplicateIndex":1,"question":"How are monthly life annuity benefit payments treated under a tax sheltered annuity (TSA)?","options":[{"label":"A","text":"Taxed as a capital gain during the accumulation period"},{"label":"B","text":"Taxed as ordinary income during the accumulation period"},{"label":"C","text":"Taxed as ordinary income in the year received"},{"label":"D","text":"Received tax-free to all recipients"}],"correctAnswer":"C","explanation":"Monthly life annuity benefit payments received from a tax sheltered annuity (TSA) are taxed as ordinary income in the year received.","explanationPt":"Os pagamentos mensais de benefício de anuidade vitalícia recebidos de uma anuidade com benefício fiscal (TSA) são tributados como renda ordinária no ano em que forem recebidos.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q244","sourceNumber":244,"duplicateIndex":1,"question":"All of these are duties that a producer may be required to perform when delivering an insurance policy EXCEPT","options":[{"label":"A","text":"Acquire a statement of good health signature"},{"label":"B","text":"Gather the initial premium"},{"label":"D","text":"Review policy with applicant"},{"label":"E","text":"Leave a conditional receipt with client"}],"correctAnswer":"E","explanation":"A conditional receipt is normally given prior to a policy being issued.","explanationPt":"Um recibo condicional normalmente é entregue antes de a apólice ser emitida.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q245","sourceNumber":245,"duplicateIndex":1,"question":"All of these are duties that a producer may be required to perform when delivering an insurance policy EXCEPT","options":[{"label":"A","text":"Acquire a statement of good health signature"},{"label":"B","text":"Gather the initial premium"},{"label":"C","text":"Review policy with applicant"},{"label":"D","text":"Leave a conditional receipt with client"}],"correctAnswer":"D","explanation":"A conditional receipt is normally given prior to a policy being issued.","explanationPt":"Um recibo condicional normalmente é entregue antes de a apólice ser emitida.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q246","sourceNumber":246,"duplicateIndex":1,"question":"Group life plans sold in Massachusetts typically contain a conversion option. If the insured elects this option, the new policy","options":[{"label":"A","text":"does NOT require evidence of insurability"},{"label":"B","text":"requires evidence of insurability"},{"label":"C","text":"is in force for up to 5 years"},{"label":"D","text":"does NOT require premium payments from the insured"}],"correctAnswer":"A","explanation":"When an insured under a group life insurance plan in Massachusetts elects the conversion option, the new policy is issued without requiring evidence of insurability.","explanationPt":"Quando um segurado sob um plano de seguro de vida em grupo em Massachusetts opta pela opção de conversão, a nova apólice é emitida sem exigir prova de segurabilidade.","theme":"State Law","jurisdiction":"MA","review":false,"reviewFlags":[]},{"id":"Q247","sourceNumber":247,"duplicateIndex":1,"question":"Which of these is NOT considered to be a cost connected with an individual's death?","options":[{"label":"A","text":"Funeral expense"},{"label":"B","text":"Tax liability"},{"label":"C","text":"Business expenses"},{"label":"D","text":"Probate costs"}],"correctAnswer":"C","explanation":"All of these are considered to be costs associated with an individual’s death EXCEPT business expenses.","explanationPt":"Todos estes são considerados custos associados à morte de um indivíduo, EXCETO despesas empresariais.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q248","sourceNumber":248,"duplicateIndex":1,"question":"A life policy that has premiums that are lower than normal during the early years is called","options":[{"label":"A","text":"Decreasing term"},{"label":"B","text":"Modified life"},{"label":"C","text":"Variable life"},{"label":"D","text":"Limited-pay life"}],"correctAnswer":"B","explanation":"Modified life has premiums that are lower than normal during the early years of the policy","explanationPt":"A vida modificada (modified life) tem prêmios mais baixos do que o normal nos primeiros anos da apólice.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q249","sourceNumber":249,"duplicateIndex":1,"question":"A policyowner pays the first annual premium for a $50,000 life insurance policy and dies one month after the policy effective date. Which of these statements is normally true?","options":[{"label":"A","text":"Premium will be refunded with interest and no death benefit paid"},{"label":"B","text":"Premium received by insurer is considered to be unearned"},{"label":"C","text":"Proceeds are prorated to 1/12th of the full amount"},{"label":"D","text":"Beneficiary receives $50,000 income tax-free"}],"correctAnswer":"D","explanation":"In this situation, the beneficiary receives $50,000 income tax-free.","explanationPt":"Nesta situação, o beneficiário recebe $50.000 isentos de imposto de renda.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q250","sourceNumber":250,"duplicateIndex":1,"question":"Which life insurance policy would be eligible to include an automatic premium loan provision?","options":[{"label":"A","text":"Increasing term"},{"label":"B","text":"Level term"},{"label":"C","text":"Decreasing term"},{"label":"D","text":"Whole life"}],"correctAnswer":"D","explanation":"An automatic premium loan provision is possible in whole life insurance because of the cash value that builds:","explanationPt":"Uma cláusula de empréstimo automático de prêmio é possível no seguro de vida inteira por causa do valor em dinheiro que se acumula.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q251","sourceNumber":251,"duplicateIndex":1,"question":"A life insurance producer is required to give a disclosure notice about information practices to an applicant","options":[{"label":"A","text":"after the insurer requests a full medical exam"},{"label":"B","text":"when the insurer requests an attending physician's report"},{"label":"C","text":"prior to or at the time of signing the application"},{"label":"D","text":"at time of policy delivery"}],"correctAnswer":"C","explanation":"A life insurance producer is required to give a disclosure notice about information practices to an applicant or proposed insured prior to or at the time of signing the application.","explanationPt":"Um produtor de seguro de vida deve entregar um aviso de divulgação sobre práticas de informação a um proponente ou proposto segurado antes ou no momento da assinatura da proposta.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q252","sourceNumber":252,"duplicateIndex":1,"question":"When must a producer provide disclosure about information practices to an applicant?","options":[{"label":"A","text":"During the medical examination"},{"label":"B","text":"Upon policy delivery"},{"label":"C","text":"Prior to or at the time of signing the application"},{"label":"D","text":"Immediately after signing the application"}],"correctAnswer":"C","explanation":"A producer must give a disclosure notice about information practices to an applicant prior to or at the time of signing the application.","explanationPt":"Um produtor deve entregar um aviso de divulgação sobre práticas de informação a um proponente antes ou no momento da assinatura da proposta.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q253","sourceNumber":253,"duplicateIndex":1,"question":"What type of premiums are associated with individual mortgage protection life insurance policies?","options":[{"label":"A","text":"Level premiums"},{"label":"B","text":"Flexible premiums"},{"label":"C","text":"Modified premiums"},{"label":"D","text":"Decreasing premiums"}],"correctAnswer":"A","explanation":"Decreasing term policies are normally used for mortgage protection life insurance to which the premium remains level, but the coverage decreases over time.","explanationPt":"As apólices de termo decrescente normalmente são usadas para seguro de proteção de hipoteca, no qual o prêmio permanece nivelado, mas a cobertura diminui ao longo do tempo.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q254","sourceNumber":254,"duplicateIndex":1,"question":"For insurance purposes, similar objects which are exposed to the same group of perils are referred to as","options":[{"label":"A","text":"Homogenous perils"},{"label":"B","text":"Similar exposure units"},{"label":"C","text":"Homogeneous exposure units"},{"label":"D","text":"Common hazards"}],"correctAnswer":"C","explanation":"Similar objects of insurance that are exposed to the same group of perils are called homogeneous exposure units.","explanationPt":"Objetos de seguro semelhantes, expostos ao mesmo grupo de perigos, são chamados de unidades de exposição homogêneas.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q255","sourceNumber":255,"duplicateIndex":1,"question":"Which statement regarding the waiver of premium rider is accurate?","options":[{"label":"A","text":"Policy loans are used to keep the policy active"},{"label":"B","text":"Cash payment is not directly provided to the policyowner"},{"label":"C","text":"Insurance companies are required to offer this to all policyowners"},{"label":"D","text":"Premiums are waived in the event of bankruptcy"}],"correctAnswer":"B","explanation":"Cash payments are not involved with the waiver of premium. If the company determines that the insured is totally disabled, the policyowner is relieved of paying premiums as long as the disability continues.","explanationPt":"Não há pagamentos em dinheiro envolvidos na isenção de prêmio. Se a seguradora determinar que o segurado está totalmente incapacitado, o titular fica dispensado de pagar os prêmios enquanto a incapacidade persistir.","theme":"Health Insurance","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q256","sourceNumber":256,"duplicateIndex":1,"question":"Which entity is responsible for regulating claims settlement practices of insurers?","options":[{"label":"A","text":"Better Business Bureau"},{"label":"B","text":"State insurance departments"},{"label":"C","text":"NAIC"},{"label":"D","text":"Attorney General"}],"correctAnswer":"B","explanation":"Claims settlement practices of insurers are regulated by state insurance departments.","explanationPt":"As práticas de liquidação de sinistros das seguradoras são regulamentadas pelos departamentos estaduais de seguros.","theme":"State Law","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q257","sourceNumber":257,"duplicateIndex":1,"question":"What is payable to the policyowner if a whole life policy is surrendered prior to its maturity date?","options":[{"label":"A","text":"The loan value"},{"label":"B","text":"The cash value"},{"label":"C","text":"The face amount minus any past due premiums and outstanding loans"},{"label":"D","text":"Nothing"}],"correctAnswer":"B","explanation":"The cash value is the amount payable to the policyowner when a whole life insurance policy is surrendered before maturity.","explanationPt":"O valor em dinheiro é o valor pagável ao titular quando uma apólice de seguro de vida inteira é resgatada antes do vencimento.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q258","sourceNumber":258,"duplicateIndex":1,"question":"Which of these statements accurately portrays an adjustable life insurance policy?","options":[{"label":"A","text":"Policy can alternate between forms of term and whole life insurance"},{"label":"B","text":"Cash value loans are not permitted"},{"label":"C","text":"Evidence of insurability required for conversion"},{"label":"D","text":"Settlement options are limited"}],"correctAnswer":"A","explanation":"Adjustable life insurance allows the policyowner to adjust the policy's face amount, premium, and type of protection wit having to complete a new application or exchange policies. Example: converting a term policy to whole life or vice versa.","explanationPt":"O seguro de vida ajustável permite que o titular ajuste o valor de face, o prêmio e o tipo de proteção da apólice sem precisar preencher uma nova proposta ou trocar de apólice. Exemplo: converter uma apólice temporária (term) em vida inteira ou vice-versa.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q259","sourceNumber":259,"duplicateIndex":1,"question":"Which statement regarding an adjustable life insurance policy is NOT true?","options":[{"label":"A","text":"Combines term and permanent insurance into a single plan"},{"label":"B","text":"Allows flexibility as insurance needs change"},{"label":"C","text":"Plan of coverage may be changed by the policyowner"},{"label":"D","text":"Policy loans are not permitted"}],"correctAnswer":"D","explanation":"If the adjustable life policy has cash value, the policyowner is permitted to take out a policy loan.","explanationPt":"Se a apólice de vida ajustável tiver valor em dinheiro, o titular pode fazer um empréstimo sobre a apólice.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q260","sourceNumber":260,"duplicateIndex":1,"question":"Which statement concerning adjustable life insurance is accurate?","options":[{"label":"A","text":"Cash value loans are not permitted"},{"label":"B","text":"The face amount and premiums can be changed simultaneously by the policyowner"},{"label":"C","text":"Settlement options are limited"},{"label":"D","text":"Only the face amount can be changed by the policyowner"}],"correctAnswer":"B","explanation":"Adjustable life insurance combines features of both term and whole life coverage. Length of coverage, accumulated cash value, and the premiums can be adjusted to fit specific needs.","explanationPt":"O seguro de vida ajustável combina características tanto do seguro temporário quanto do seguro de vida inteira. A duração da cobertura, o valor em dinheiro acumulado e os prêmios podem ser ajustados para atender a necessidades específicas.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q261","sourceNumber":261,"duplicateIndex":1,"question":"Which life insurance policy provision allows a policyowner to cancel the policy and receive a full refund within a limited time period after policy delivery?","options":[{"label":"A","text":"Grace period"},{"label":"B","text":"Incontestable period"},{"label":"C","text":"Elimination period"},{"label":"D","text":"Free-look period"}],"correctAnswer":"D","explanation":"The free-look period provision in a life insurance policy permits a policyowner to cancel the policy within a stated time period after policy delivery and be given a full refund.","explanationPt":"A cláusula do período de reflexão (free-look) em uma apólice de seguro de vida permite que o titular cancele a apólice dentro de um período de tempo determinado após a entrega da apólice e receba um reembolso total.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q262","sourceNumber":262,"duplicateIndex":1,"question":"Which of these is NOT a reason to buy a term life policy?","options":[{"label":"A","text":"To pay a mortgage balance if an insured dies"},{"label":"B","text":"To offer temporary protection"},{"label":"C","text":"To offer low-cost insurance coverage"},{"label":"D","text":"To accumulate savings"}],"correctAnswer":"D","explanation":"All of these are valid reasons for purchasing term insurance EXCEPT to accumulate savings.","explanationPt":"Todos estes são motivos válidos para comprar seguro temporário (term), EXCETO acumular poupança.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q263","sourceNumber":263,"duplicateIndex":1,"question":"When there is a named beneficiary on a life insurance policy, the death benefits","options":[{"label":"A","text":"are directed to a trustee if the insured has any outstanding debts"},{"label":"B","text":"are paid directly to the insured's creditors, with any remaining balance forwarded to the beneficiary"},{"label":"C","text":"are paid directly to the beneficiary, minus any debt claims by the insured's creditors"},{"label":"D","text":"are paid directly to the beneficiary without interference from the insured's creditors"}],"correctAnswer":"D","explanation":"Death benefit proceeds pass directly to the beneficiary and are not subject to attachment by the insured's creditors.","explanationPt":"Os valores do benefício por morte são pagos diretamente ao beneficiário e não estão sujeitos a penhora por credores do segurado.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q264","sourceNumber":264,"duplicateIndex":1,"question":"Before an individual is permitted to act as an insurance agent, he/she must hold a valid insurance license and be________ by an authorized insurer.","options":[{"label":"A","text":"appointed"},{"label":"B","text":"bonded"},{"label":"C","text":"designated"},{"label":"D","text":"admitted"}],"correctAnswer":"A","explanation":"In order to act as an insurance agent, a producer must hold a valid insurance license and be appointed by an authorized insurance company.","explanationPt":"Para atuar como agente de seguros, um produtor deve possuir uma licença de seguro válida e ser credenciado por uma seguradora autorizada.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q265","sourceNumber":265,"duplicateIndex":1,"question":"Which of the following is a potential punishment given to a producer found guilty of an unfair method of competition?","options":[{"label":"A","text":"Reduction in commission"},{"label":"B","text":"Fine of up to $20,000 per violation"},{"label":"C","text":"Community service"},{"label":"D","text":"License suspension or revocation"}],"correctAnswer":"D","explanation":"A producer found to have engaged in an unfair method of competition may be subject to license suspension or revocation","explanationPt":"Um produtor considerado culpado de praticar um método desleal de concorrência pode estar sujeito à suspensão ou revogação da licença.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q266","sourceNumber":266,"duplicateIndex":1,"question":"Which of these must be disclosed in a universal life policy?","options":[{"label":"A","text":"Maximum coverage that can be purchased"},{"label":"B","text":"The policy's surrender charges"},{"label":"C","text":"The commissions earned from the sale of the policy"},{"label":"D","text":"The producer's license expiration date"}],"correctAnswer":"B","explanation":"The surrender charges of a universal life policy must be disclosed.","explanationPt":"As taxas de resgate (surrender charges) de uma apólice de vida universal devem ser divulgadas.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q267","sourceNumber":267,"duplicateIndex":1,"question":"Which type of life insurance policy allows a policyowner the choice of investments along with flexible premium payments?","options":[{"label":"A","text":"Variable universal life"},{"label":"B","text":"Modified endowment contract"},{"label":"C","text":"Adjustable life"},{"label":"D","text":"Graded premium whole life"}],"correctAnswer":"A","explanation":"Variable universal life involves a guaranteed death benefit plus premium and investment flexibility.","explanationPt":"A vida universal variável envolve um benefício por morte garantido, além de flexibilidade de prêmio e de investimento.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q268","sourceNumber":268,"duplicateIndex":1,"question":"A reciprocal insurer typically has an administrator who manages the premiums collected from the group's members. This administrator is called a(n)","options":[{"label":"A","text":"reciprocal commissioner"},{"label":"B","text":"attorney general"},{"label":"C","text":"attorney-in-fact"},{"label":"D","text":"reciprocal director"}],"correctAnswer":"C","explanation":"The administrator of a reciprocal insurer who manages the premiums collected from the group's members is called an attorney-in-fact.","explanationPt":"O administrador de uma seguradora recíproca (reciprocal insurer), que gerencia os prêmios recebidos dos membros do grupo, é chamado de procurador de fato (attorney-in-fact).","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q269","sourceNumber":269,"duplicateIndex":1,"question":"An annuity's accumulation period may","options":[{"label":"A","text":"continue after the purchase payments stop"},{"label":"B","text":"continue after the benefit payments start"},{"label":"C","text":"continue after the annuitant dies"},{"label":"D","text":"continue after the annuity has been surrendered"}],"correctAnswer":"A","explanation":"accumulation period of an annuity usually may continue after the purchase payments stop.","explanationPt":"O período de acumulação de uma anuidade geralmente pode continuar mesmo depois que os pagamentos de compra cessam.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q270","sourceNumber":270,"duplicateIndex":1,"question":"Rick owns a variable universal life policy and chooses a variable death benefit option. What will typically happen to the death benefit as a result of this selection?","options":[{"label":"A","text":"Remain the same"},{"label":"B","text":"Decrease but never increase"},{"label":"C","text":"Increase but never decrease"},{"label":"D","text":"Fluctuate with changes in the cash account"}],"correctAnswer":"D","explanation":"When a variable universal life policyowner selects a variable death benefit option, the death benefit generally will fluctuate with changes in the cash account.","explanationPt":"Quando o titular de uma apólice de vida universal variável seleciona uma opção de benefício por morte variável, o benefício por morte geralmente flutuará de acordo com as mudanças na conta em dinheiro.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q271","sourceNumber":271,"duplicateIndex":1,"question":"When determining the accumulation value of a deferred annuity, the total is calculated by taking the premiums paid plus interest earned minus","options":[{"label":"A","text":"bailout option charge"},{"label":"B","text":"surrender charges"},{"label":"C","text":"taxes owed"},{"label":"D","text":"expenses and withdrawals"}],"correctAnswer":"D","explanation":"The accumulation value of a deferred annuity is equal to the sum of premiums paid plus interest earned minus any withdrawals and expenses.","explanationPt":"O valor de acumulação de uma anuidade diferida é igual à soma dos prêmios pagos mais os juros ganhos, menos quaisquer saques e despesas.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q272","sourceNumber":272,"duplicateIndex":1,"question":"An insured has a $25,000 whole life insurance policy with $6,000 cash value available. Under the extended term nonforfeiture option, what is the amount of insurance available to the insured?","options":[{"label":"A","text":"$6,000"},{"label":"B","text":"$19,000"},{"label":"C","text":"$25,000"},{"label":"D","text":"$31,000"}],"correctAnswer":"C","explanation":"The extended term option uses the policy's cash value to purchase a level term insurance policy in an amount equal to the original policy's face value, for as long a period as the cash value will purchase.","explanationPt":"A opção de termo estendido (extended term) usa o valor em dinheiro da apólice para comprar uma apólice de seguro temporário nivelado em um valor igual ao valor de face da apólice original, pelo maior período que esse valor em dinheiro conseguir cobrir.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q273","sourceNumber":273,"duplicateIndex":1,"question":"The owner's cost basis for a non-qualified deferred annuity is typically the same as the","options":[{"label":"A","text":"annuity's cash value"},{"label":"B","text":"total premiums paid"},{"label":"C","text":"benefits payable to the annuitant"},{"label":"D","text":"interest earned within the annuity"}],"correctAnswer":"B","explanation":"An owner's cost basis for a deferred annuity is typically the same amount as the premiums paid into the annuity.","explanationPt":"A base de custo do titular para uma anuidade diferida é tipicamente o mesmo valor dos prêmios pagos na anuidade.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q274","sourceNumber":274,"duplicateIndex":1,"question":"Which of these is NOT a common life insurance nonforfeiture option?","options":[{"label":"A","text":"Reduced paid-up insurance"},{"label":"B","text":"Extended term option"},{"label":"C","text":"Cash surrender option"},{"label":"D","text":"Life income annuity"}],"correctAnswer":"D","explanation":"All of these are common life insurance nonforfeiture options EXCEPT a life income annuity.","explanationPt":"Todas estas são opções comuns de não confisco em seguro de vida, EXCETO uma anuidade de renda vitalícia (life income annuity).","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q275","sourceNumber":275,"duplicateIndex":1,"question":"What type of life insurance policy covers two or more persons and pays the face amount upon the death of the first insured?","options":[{"label":"A","text":"Joint and survivorship"},{"label":"B","text":"Survivorship life"},{"label":"C","text":"Universal life"},{"label":"D","text":"Joint life"}],"correctAnswer":"D","explanation":"A joint life insurance policy covers two or more individuals with the face amount payable upon the death of the first insured.","explanationPt":"Uma apólice de seguro de vida conjunta cobre dois ou mais indivíduos, com o valor de face pagável na morte do primeiro segurado.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q276","sourceNumber":276,"duplicateIndex":1,"question":"A terminally ill policyowner sells his life insurance policy at a discount to help pay for medical expenses. This arrangement is referred to as a(n)","options":[{"label":"A","text":"accelerated benefit"},{"label":"B","text":"life settlement"},{"label":"C","text":"living benefit"},{"label":"D","text":"discounted settlement"}],"correctAnswer":"B","explanation":"Life settlements allow policy holders to sell their policies for a percentage of the face amount for a cash payment.","explanationPt":"Os \"life settlements\" permitem que titulares de apólices vendam suas apólices por um percentual do valor de face em troca de um pagamento em dinheiro.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q277","sourceNumber":277,"duplicateIndex":1,"question":"Which statement regarding a single premium life insurance policy is NOT correct?","options":[{"label":"A","text":"No further premiums are necessary"},{"label":"B","text":"Policy loans are permitted"},{"label":"C","text":"Cash value is immediately created"},{"label":"D","text":"Additional premiums may be required under certain conditions"}],"correctAnswer":"D","explanation":"Only one premium payment is required with a single premium life insurance policy.","explanationPt":"Apenas um pagamento de prêmio é exigido em uma apólice de seguro de vida com prêmio único.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q278","sourceNumber":278,"duplicateIndex":1,"question":"A prospective client was intimidated by a producer to purchase an insurance contract. The producer could be found guilty of","options":[{"label":"A","text":"coercion"},{"label":"B","text":"rebating"},{"label":"C","text":"defamation"},{"label":"D","text":"sliding"}],"correctAnswer":"A","explanation":"A producer who intimidates a prospective insured could be found guilty of coercion.","explanationPt":"Um produtor que intimida um proposto segurado pode ser considerado culpado de coação (coercion).","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q279","sourceNumber":279,"duplicateIndex":1,"question":"An employee requested that the balance of her 401(k) account be sent directly to her in one lump sum. Upon receipt of the distribution, she immediately had the funds rolled over into an IRA. What is the tax consequence of the distribution sent to this employee?","options":[{"label":"A","text":"Distribution is subject to capital gains tax"},{"label":"B","text":"Distribution is subject to ordinary income tax"},{"label":"C","text":"Distribution is subject to a tax penalty"},{"label":"D","text":"Distribution is subject to federal income tax withholding"}],"correctAnswer":"D","explanation":"A participant must complete a rollover to another qualified plan within 60 days or the distribution is considered a nonqualified distribution and is subject to taxes and penalties. A plan sponsor must withhold 20% of the distribution for federal taxes on a rollover. Once the rollover takes place to the new custodian, the remainder of the distribution is released.","explanationPt":"Um participante deve concluir um rollover para outro plano qualificado dentro de 60 dias, ou a distribuição será considerada uma distribuição não qualificada e estará sujeita a impostos e penalidades. O patrocinador do plano deve reter 20% da distribuição para impostos federais em um rollover. Uma vez que o rollover é realizado para o novo custodiante, o restante da distribuição é liberado.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q280","sourceNumber":280,"duplicateIndex":1,"question":"Which of these factors does NOT influence an individual's need for life insurance?","options":[{"label":"A","text":"Lifestyle of the applicant"},{"label":"B","text":"Number of dependents"},{"label":"C","text":"Future educational costs of the dependents"},{"label":"D","text":"Self-maintenance expenses"}],"correctAnswer":"D","explanation":"An individual's need for a death benefit for survivors is influenced by all of the following factors EXCEPT self-maintenance costs.","explanationPt":"A necessidade de um indivíduo por um benefício por morte para os sobreviventes é influenciada por todos estes fatores, EXCETO custos de autossustento.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q281","sourceNumber":281,"duplicateIndex":1,"question":"Dividends from a mutual insurance company are paid to whom?","options":[{"label":"A","text":"Policyholders"},{"label":"B","text":"Beneficiaries"},{"label":"C","text":"Preferred stockholders"},{"label":"D","text":"Stockholders"}],"correctAnswer":"A","explanation":"Mutual insurance companies are owned by policyowners, to whom dividends are paid.","explanationPt":"As seguradoras mútuas são de propriedade dos titulares de apólices, aos quais são pagos dividendos.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q282","sourceNumber":282,"duplicateIndex":1,"question":"Which of the following would prevent a person from obtaining a Massachusetts resident producer license?","options":[{"label":"A","text":"Not graduating from high school"},{"label":"B","text":"Residing in a state outside of Massachusetts"},{"label":"C","text":"Residing in Massachusetts less than five years"},{"label":"D","text":"Being under the age of 25"}],"correctAnswer":"B","explanation":"must be a resident of Massachusetts in order to obtain a residential producer license","explanationPt":"É preciso ser residente de Massachusetts para obter uma licença de produtor residente.","theme":"Producers and Licensing","jurisdiction":"MA","review":false,"reviewFlags":[]},{"id":"Q283","sourceNumber":283,"duplicateIndex":1,"question":"All of these statements concerning group credit life insurance are false EXCEPT","options":[{"label":"A","text":"Cash value loans are allowable"},{"label":"B","text":"Dividends can reduce the premium payments"},{"label":"C","text":"The face amount and premiums are flexible"},{"label":"D","text":"The face amount is based on the outstanding loan balance"}],"correctAnswer":"D","explanation":"The amount of credit life insurance applied for is based on the outstanding loan balance amount.","explanationPt":"O valor de seguro de vida de crédito solicitado é baseado no saldo devedor do empréstimo.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q284","sourceNumber":284,"duplicateIndex":1,"question":"What are premiums for group credit life insurance based on?","options":[{"label":"A","text":"The age of the borrower at the time debt is incurred"},{"label":"B","text":"The age of the borrower when debt is paid off"},{"label":"C","text":"The average age of the borrower over the life of the debt"},{"label":"D","text":"Flat rate unrelated to the borrower's age"}],"correctAnswer":"D","explanation":"Premiums for group credit life insurance are based on claims experience and expense factors, not necessarily the borrower's age.","explanationPt":"Os prêmios do seguro de vida de crédito em grupo são baseados na experiência de sinistros e em fatores de despesa, não necessariamente na idade do mutuário.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q285","sourceNumber":285,"duplicateIndex":1,"question":"In order for a prohibited person to sell insurance in Massachusetts, he or she must have a(n)","options":[{"label":"A","text":"letter signed by the Superintendent"},{"label":"B","text":"waiver from the NAIC"},{"label":"C","text":"authorization from the Attorney General"},{"label":"D","text":"pardon from the Governor"}],"correctAnswer":"A","explanation":"In order for a prohibited person to sell insurance in Massachusetts, he or she must have a letter signed by the Superintende!","explanationPt":"Para que uma pessoa proibida (prohibited person) venda seguros em Massachusetts, ela deve ter uma carta assinada pelo Superintendente.","theme":"State Law","jurisdiction":"MA","review":false,"reviewFlags":[]},{"id":"Q286","sourceNumber":286,"duplicateIndex":1,"question":"The surrender charge on many deferred annuity contracts are waived when the","options":[{"label":"A","text":"annuitant becomes unemployed"},{"label":"B","text":"annuitant dies or becomes disabled"},{"label":"C","text":"contract's interest rate falls below a stated percentage"},{"label":"D","text":"contract is canceled within the first year"}],"correctAnswer":"B","explanation":"Many deferred annuity contracts waive the surrender charge when the annuitant dies or becomes disabled.","explanationPt":"Muitos contratos de anuidade diferida dispensam a taxa de resgate quando o anuitante morre ou fica incapacitado.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q287","sourceNumber":287,"duplicateIndex":1,"question":"An insured may be required to sign which document at policy delivery to ensure there has not been any adverse medical conditions since the time of the application?","options":[{"label":"A","text":"Binding receipt"},{"label":"B","text":"Good health statement"},{"label":"C","text":"Agent's report"},{"label":"D","text":"MIB disclosure"}],"correctAnswer":"B","explanation":"At policy delivery, a good health statement may need to be signed by the insured to ensure there has NOT been any adverse medical conditions since the time of application.","explanationPt":"Na entrega da apólice, pode ser necessário que o segurado assine uma declaração de boa saúde para garantir que NÃO houve condições médicas adversas desde o momento da proposta.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q288","sourceNumber":288,"duplicateIndex":1,"question":"Which of these is NOT considered to be an example of misrepresentation?","options":[{"label":"A","text":"A producer comparing the benefits of competing insurance policies"},{"label":"B","text":"A producer guaranteeing a policy's dividends"},{"label":"C","text":"A producer comparing an insurance policy to a share of stock"},{"label":"D","text":"An individual providing incorrect, misleading, incomplete, or materially untrue information on a producer license application"}],"correctAnswer":"A","explanation":"All of these are considered examples of misrepresentation EXCEPT for \"A producer comparing the benefits of competing surance policies\".","explanationPt":"Todos estes são considerados exemplos de declaração falsa (misrepresentation), EXCETO \"um produtor comparando os benefícios de apólices de seguro concorrentes\".","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q289","sourceNumber":289,"duplicateIndex":1,"question":"Greg applies for insurance and makes a false statement on the application that will influence whether or not the insurer will accept the risk. Greg's false statement is called a(n)","options":[{"label":"A","text":"substandard representation"},{"label":"B","text":"unacceptable risk"},{"label":"C","text":"material misrepresentation"},{"label":"D","text":"adverse selection"}],"correctAnswer":"C","explanation":"A false statement made by an applicant that would influence an insurer in determining whether or not to accept the risk is considered a material misrepresentation.","explanationPt":"Uma declaração falsa feita por um proponente que influenciaria a seguradora na decisão de aceitar ou não o risco é considerada uma declaração falsa material (material misrepresentation).","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q290","sourceNumber":290,"duplicateIndex":1,"question":"Which of the following is an example of defamation?","options":[{"label":"A","text":"An insurer using intimidation in order to restrain or monopolize the business of insurance."},{"label":"B","text":"A producer who publicly and erroneously announces that an insurance company is insolvent"},{"label":"C","text":"A producer who shares commissions with a client"},{"label":"D","text":"An insurer reducing the premiums across the board for a specific risk class"}],"correctAnswer":"B","explanation":"A producer who publicly and erroneously announces that an insurance company is insolvent may be found guilty of defamation.","explanationPt":"Um produtor que anuncia pública e erroneamente que uma seguradora está insolvente pode ser considerado culpado de difamação.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q291","sourceNumber":291,"duplicateIndex":1,"question":"Which of the following is NOT a condition that must be met for an accidental death benefit to be paid?","options":[{"label":"A","text":"Injury must have been suffered prior to a stated age"},{"label":"B","text":"Accidental bodily injury must have been the cause of death"},{"label":"C","text":"Cause of death must be from a job-related injury"},{"label":"D","text":"Death must occur within a stated number of days after the accident"}],"correctAnswer":"C","explanation":"Death from a job-related injury is not a require for a life insurance accidental death benefit to be paid.","explanationPt":"A morte por lesão relacionada ao trabalho não é um requisito para que um benefício por morte acidental de seguro de vida seja pago.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q292","sourceNumber":292,"duplicateIndex":1,"question":"How may an insurance company classify an accidental death benefit on a life policy?","options":[{"label":"A","text":"As an optional policy rider"},{"label":"B","text":"As a provision of the policy"},{"label":"C","text":"As a nonforfeiture option"},{"label":"D","text":"As a mandatory policy rider"}],"correctAnswer":"A","explanation":"The accidental death benefit provided by a life insurance policy may be classified as an optional policy rider.","explanationPt":"O benefício por morte acidental oferecido por uma apólice de seguro de vida pode ser classificado como uma cláusula adicional opcional (optional rider).","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q293","sourceNumber":293,"duplicateIndex":1,"question":"Which of the following is considered an activity of daily living when determining an accelerated life insurance benefit?","options":[{"label":"A","text":"Driving"},{"label":"B","text":"Running"},{"label":"C","text":"Typing"},{"label":"D","text":"Eating"}],"correctAnswer":"D","explanation":"To qualify for an accelerated life insurance benefit, an individual must be unable to perform at least two activities of daily living, including eating, toileting, transferring, bathing, dressing, and continence without substantial assistance for at least 90 days.","explanationPt":"Para se qualificar para um benefício de vida acelerado (accelerated benefit), um indivíduo deve ser incapaz de realizar pelo menos duas atividades da vida diária, incluindo alimentar-se, usar o banheiro, transferir-se, tomar banho, vestir-se e manter continência, sem assistência substancial, por pelo menos 90 dias.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q294","sourceNumber":294,"duplicateIndex":1,"question":"The time limit an individual has to \"rollover\" funds from an IRA or qualified plan is","options":[{"label":"A","text":"60 days"},{"label":"B","text":"90 days"},{"label":"C","text":"120 days"},{"label":"D","text":"No Limit"}],"correctAnswer":"A","explanation":"IRAs and qualified plans, the time limit for rollover funds is 60 days, or the funds could be subjected to income taxes and a penalty tax.","explanationPt":"Para IRAs e planos qualificados, o prazo limite para fundos de rollover é de 60 dias, ou os fundos poderão ficar sujeitos a impostos de renda e a uma multa fiscal.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q295","sourceNumber":295,"duplicateIndex":1,"question":"When testing for the Human Immunodeficiency Virus (HIV), Massachusetts law requires a consent form","options":[{"label":"A","text":"to be signed by the Commissioner"},{"label":"B","text":"that is only valid for 10 days"},{"label":"C","text":"that discloses who may receive a copy of the results"},{"label":"D","text":"which is provided at the option of the insurer"}],"correctAnswer":"C","explanation":"Massachusetts law requires the Human Immunodeficiency Virus (HIV) consent form to disclose the types of individuals or organizations that may receive a copy of the test results.","explanationPt":"A lei de Massachusetts exige que o formulário de consentimento para o teste de HIV (Vírus da Imunodeficiência Humana) divulgue os tipos de pessoas ou organizações que podem receber uma cópia dos resultados do teste.","theme":"State Law","jurisdiction":"MA","review":false,"reviewFlags":[]},{"id":"Q296","sourceNumber":296,"duplicateIndex":1,"question":"A life insurance applicant is tested for the Human Immunodeficiency Virus (HIV). The applicant MUST be informed that the testing","options":[{"label":"A","text":"will not help determine the applicant's insurability"},{"label":"B","text":"violates civil liberties"},{"label":"C","text":"is not 100% accurate"},{"label":"D","text":"helps determine the insurability of the applicant"}],"correctAnswer":"D","explanation":"An applicant for life insurance must be informed that testing for HIV infection is used to help determine the insurability of the proposed insured. The reason for requesting an HIV test cannot be the proposed insured's sexual orientation.","explanationPt":"Um proponente de seguro de vida deve ser informado de que o teste de HIV é usado para ajudar a determinar a segurabilidade do proposto segurado. O motivo para solicitar um teste de HIV não pode ser a orientação sexual do proposto segurado.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q297","sourceNumber":297,"duplicateIndex":1,"question":"Which of the following is NOT the responsibility of an insurer?","options":[{"label":"A","text":"Notifying the Commissioner of the termination of a producer's appointment"},{"label":"B","text":"Providing sales material to its appointed producers"},{"label":"C","text":"Assuming liability for a producer's unauthorized acts"},{"label":"D","text":"Obtaining a Certificate of Authority prior to conducting insurance business in this state"}],"correctAnswer":"C","explanation":"An insurer is responsible for all of these EXCEPT \"Assuming liability for a producer's unauthorized acts”.","explanationPt":"Uma seguradora é responsável por todos estes itens, EXCETO \"assumir responsabilidade por atos não autorizados de um produtor\".","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q298","sourceNumber":298,"duplicateIndex":1,"question":"Any employee insured under a group life insurance plan is normally","options":[{"label":"A","text":"given a master certificate"},{"label":"B","text":"covered on a noncontributory basis"},{"label":"C","text":"required to show proof of insurability"},{"label":"D","text":"covered with term life insurance"}],"correctAnswer":"D","explanation":"Employees covered under a group life plan are normally insured with term insurance.","explanationPt":"Os funcionários cobertos por um plano de vida em grupo normalmente são segurados por meio de seguro temporário (term).","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q299","sourceNumber":299,"duplicateIndex":1,"question":"A retired couple would like to maximize the income derived from their combined life savings and have it payable until they both die. Which annuity would be their best choice?","options":[{"label":"A","text":"Fixed annuity"},{"label":"B","text":"Survivorship annuity"},{"label":"C","text":"Joint life annuity"},{"label":"D","text":"Joint and survivor annuity"}],"correctAnswer":"D","explanation":"A joint and survivor annuity covers two or more lives and continues in force so long as any one of them survives.","explanationPt":"Uma anuidade conjunta e de sobrevivência (joint and survivor) cobre duas ou mais vidas e permanece em vigor enquanto qualquer uma delas sobreviver.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q300","sourceNumber":300,"duplicateIndex":1,"question":"A producer has indicated to a potential client that the proposed life insurance policy is covered by the Massachusetts Life and Health Insurance Guaranty Association. This action taken by the producer is","options":[{"label":"A","text":"permitted and encouraged"},{"label":"B","text":"prohibited by law"},{"label":"C","text":"legal in every state"},{"label":"D","text":"permitted only with the Superintendent's authorization"}],"correctAnswer":"B","explanation":"Pointing out to a prospective client that the life insurance policy you are presenting is covered by the Massachusetts Life and Health Guaranty Association is prohibited by law.","explanationPt":"Apontar a um potencial cliente que a apólice de seguro de vida apresentada é coberta pela Massachusetts Life and Health Guaranty Association é proibido por lei.","theme":"Producers and Licensing","jurisdiction":"MA","review":false,"reviewFlags":[]},{"id":"Q301","sourceNumber":301,"duplicateIndex":1,"question":"Life insurance replacement can be best defined as","options":[{"label":"A","text":"converting existing term coverage to a permanent policy"},{"label":"B","text":"a transaction in which a new life insurance policy is purchased and an existing life insurance policy is surrendered"},{"label":"C","text":"accepting a reduced paid-up policy"},{"label":"D","text":"reducing the face value of an existing policy"}],"correctAnswer":"B","explanation":"A transaction in which a new life insurance policy is purchased and an existing life insurance policy is surrendered is called a replacement.","explanationPt":"Uma transação em que uma nova apólice de seguro de vida é comprada e uma apólice existente é resgatada é chamada de substituição (replacement).","theme":"Ethics and Compliance","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q302","sourceNumber":302,"duplicateIndex":1,"question":"Which of these is NOT a punishment for committing an unfair and deceptive insurance practice?","options":[{"label":"A","text":"Suspension of license"},{"label":"B","text":"Cease and desist order"},{"label":"C","text":"Fine"},{"label":"D","text":"Community service"}],"correctAnswer":"D","explanation":"All of these are considered possible punishment for committing unfair and deceptive insurance practices EXCEPT community service.","explanationPt":"Todas estas são possíveis punições por cometer práticas de seguro desleais e enganosas, EXCETO prestação de serviços comunitários.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q303","sourceNumber":303,"duplicateIndex":1,"question":"Which of the following is considered to be an unfair claims settlement practice?","options":[{"label":"A","text":"Using intimidation in order to restrain or monopolize the business of insurance"},{"label":"B","text":"Misrepresenting pertinent policy provisions relating to coverage after a loss"},{"label":"C","text":"Aproducer who shares commissions with a client"},{"label":"D","text":"Redauiring a time limit for submitting a claim"}],"correctAnswer":"B","explanation":"Misrepresenting pertinent policy provisions relating to coverage after a loss is an unfair claims settlement practice.","explanationPt":"Fazer declaração falsa sobre cláusulas relevantes da apólice relacionadas à cobertura após um sinistro é uma prática desleal de liquidação de sinistros.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q304","sourceNumber":304,"duplicateIndex":1,"question":"What determines how much an annuitant is paid for a variable annuity?","options":[{"label":"A","text":"Varies according to how many outstanding annuity units"},{"label":"B","text":"Payments fluctuate as annuitant gets older"},{"label":"C","text":"The market value variations of the securities backing it"},{"label":"D","text":"Varies according to the insurer's investments in its general account"}],"correctAnswer":"C","explanation":"The amount of each variable annuity benefit paid to an annuitant varies according to the market value of the securities backing it.","explanationPt":"O valor de cada benefício de anuidade variável pago a um anuitante varia de acordo com o valor de mercado dos títulos que a lastreiam.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q305","sourceNumber":305,"duplicateIndex":1,"question":"What effect does interest income have upon insurance premiums?","options":[{"label":"A","text":"Increases premium"},{"label":"B","text":"Decreases premium"},{"label":"C","text":"Levels the premium"},{"label":"D","text":"Adjusts premium on a quarterly basis"}],"correctAnswer":"B","explanation":"The actuarial formula for a bundled insurance premium is as follows: mortality costs (based upon age and gender) less assumed interest = Net premium. Please note that assumed interest always lowers the mortality costs and thus, lowers the total premium.","explanationPt":"A fórmula atuarial para um prêmio de seguro agrupado (bundled) é a seguinte: custo de mortalidade (com base na idade e no sexo) menos os juros presumidos = Prêmio Líquido. Note que os juros presumidos sempre reduzem o custo de mortalidade e, portanto, reduzem o prêmio total.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q306","sourceNumber":306,"duplicateIndex":1,"question":"The contractual rights which allow the owner of a deferred annuity to surrender the cash value several years before the annuity date are called","options":[{"label":"A","text":"nonforfeiture options"},{"label":"B","text":"settlement options"},{"label":"C","text":"conversion options"},{"label":"D","text":"surrender options"}],"correctAnswer":"A","explanation":"If the owner of a deferred annuity surrenders the contract several years before the annuity date in exchange for the cash value, the owner is said to be exercising contractual rights called \"nonforfeiture options\".","explanationPt":"Se o titular de uma anuidade diferida resgatar o contrato vários anos antes da data da anuidade em troca do valor em dinheiro, diz-se que o titular está exercendo direitos contratuais chamados \"opções de não confisco\" (nonforfeiture options).","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q307","sourceNumber":307,"duplicateIndex":1,"question":"When a policy loan is requested by a policyowner and it requires the consent of the beneficiary, what kind of beneficiary designation is this?","options":[{"label":"A","text":"Collateral beneficiary"},{"label":"B","text":"Revocable beneficiary"},{"label":"C","text":"Irrevocable beneficiary"},{"label":"D","text":"Per stirpes beneficiary"}],"correctAnswer":"C","explanation":"The policyowner must obtain the consent of the named beneficiary before taking out a policy loan if the named beneficiary is an irrevocable beneficiary.","explanationPt":"O titular deve obter o consentimento do beneficiário nomeado antes de tomar um empréstimo sobre a apólice, se o beneficiário nomeado for um beneficiário irrevogável.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q308","sourceNumber":308,"duplicateIndex":1,"question":"Which situation would not require the insured's consent when a life insurance policy is issued?","options":[{"label":"A","text":"A policy is purchased by a husband for his wife"},{"label":"B","text":"A policy is purchased by a parent for a minor child"},{"label":"C","text":"A policy is purchased by a business partner for another partner"},{"label":"D","text":"A policy is purchased by an employer for an employee"}],"correctAnswer":"B","explanation":"Consent is not needed when a parent purchases a life insurance policy on a minor.","explanationPt":"Não é necessário consentimento quando um dos pais contrata uma apólice de seguro de vida sobre um menor.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q309","sourceNumber":309,"duplicateIndex":1,"question":"If the Superintendent has reason to believe a producer has violated Massachusetts insurance law, the Superintendent may issue a(n)","options":[{"label":"A","text":"reduction in commission"},{"label":"B","text":"arrest warrant"},{"label":"C","text":"certificate of authority"},{"label":"D","text":"cease and desist order"}],"correctAnswer":"D","explanation":"When the Superintendent believes a producer has violated the law, the Superintendent has the authority to issue a cease and desist order against the producer.","explanationPt":"Quando o Superintendente acredita que um produtor violou a lei, ele tem autoridade para emitir uma ordem de cessar e desistir (cease and desist) contra o produtor.","theme":"Producers and Licensing","jurisdiction":"MA","review":false,"reviewFlags":[]},{"id":"Q310","sourceNumber":310,"duplicateIndex":1,"question":"The Superintendent has reason to believe a producer is in violation of Massachusetts insurance law. Which of the following may be issued against the producer?","options":[{"label":"A","text":"Termination notice"},{"label":"B","text":"Certificate of authority"},{"label":"C","text":"Appointment"},{"label":"D","text":"Cease and desist order"}],"correctAnswer":"D","explanation":"The Superintendent has the authority to issue a cease and desist order against a producer at a hearing if it is believed the producer has broken an insurance law.","explanationPt":"O Superintendente tem autoridade para emitir uma ordem de cessar e desistir contra um produtor em uma audiência, caso se acredite que o produtor tenha infringido uma lei de seguros.","theme":"Producers and Licensing","jurisdiction":"MA","review":false,"reviewFlags":[]},{"id":"Q311","sourceNumber":311,"duplicateIndex":1,"question":"Switching Life insurance policies without tax consequence is permitted under","options":[{"label":"A","text":"MEC tules"},{"label":"B","text":"Section 1035 rules"},{"label":"C","text":"the Exclusion Ratio"},{"label":"D","text":"Replacement rules"}],"correctAnswer":"B","explanation":"Switching Life insurance policies without tax consequence is permitted under Section 1035 rules.","explanationPt":"A troca de apólices de seguro de vida sem consequências fiscais é permitida pelas regras da Seção 1035.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q312","sourceNumber":312,"duplicateIndex":1,"question":"Which of the following can be used to avoid the mandatory withholding tax on qualified plan distributions?","options":[{"label":"A","text":"Qualified plan waiver"},{"label":"B","text":"Trustee-to-trustee transfer"},{"label":"C","text":"Conduit IRA"},{"label":"D","text":"1035 exchange"}],"correctAnswer":"C","explanation":"A conduit IRA is a holding tank for funds that originally came from a qualified plan and are on their way to another qualified plan. No withholding tax is necessary unless any of the funds are distributed directly to the person.","explanationPt":"Um IRA condutor (conduit IRA) é um recipiente temporário para fundos que originalmente vieram de um plano qualificado e estão a caminho de outro plano qualificado. Não é necessária retenção de imposto, a menos que algum dos fundos seja distribuído diretamente à pessoa.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q313","sourceNumber":313,"duplicateIndex":1,"question":"When a lapsed policy's premium has been paid current, it has the potential of being","options":[{"label":"A","text":"restored"},{"label":"B","text":"renewed"},{"label":"C","text":"reinstated"},{"label":"D","text":"reinstituted"}],"correctAnswer":"C","explanation":"A policy that has lapsed may be reinstated by paying the back premiums, interest, and any outstanding loans. Evidence of insurability must also be provided.","explanationPt":"Uma apólice caducada pode ser reinstalada mediante o pagamento dos prêmios atrasados, juros e quaisquer empréstimos pendentes. Também é necessário apresentar prova de segurabilidade.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q314","sourceNumber":314,"duplicateIndex":1,"question":"An employer has a group life coverage for his employees. How would an employee in poor health be treated in this situation?","options":[{"label":"A","text":"Approved on a graded basis"},{"label":"B","text":"Not eligible for insurance on this plan"},{"label":"C","text":"Eligible for the same type of coverage as the other employees"},{"label":"D","text":"Must pay a rating based on risk"}],"correctAnswer":"C","explanation":"Group insurance policies are not written on an individual basis so an employee in poor health is eligible for the same coverage as the other employees in the group.","explanationPt":"As apólices de seguro em grupo não são emitidas de forma individual; portanto, um funcionário com saúde debilitada tem direito à mesma cobertura que os demais funcionários do grupo.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q315","sourceNumber":315,"duplicateIndex":1,"question":"Tori has an annuity that pays her a $500 per month income benefit for life or for ten years, whichever is longer. What kind of annuity is this?","options":[{"label":"A","text":"Fixed life annuity with period certain"},{"label":"B","text":"Variable life annuity with installment refund"},{"label":"C","text":"Fixed life annuity with cash refund"},{"label":"D","text":"Variable life annuity with period certain"}],"correctAnswer":"A","explanation":"A fixed life annuity with period certain is designed to pay the annuitant a fixed income for life, but guarantees a definite minimum period of payments.","explanationPt":"Uma anuidade vitalícia fixa com período certo (period certain) foi criada para pagar ao anuitante uma renda fixa por toda a vida, mas garante um período mínimo definido de pagamentos.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q316","sourceNumber":316,"duplicateIndex":1,"question":"A producer's insurance records must be provided to the Superintendent","options":[{"label":"A","text":"within 30 days of the request"},{"label":"B","text":"under no circumstances"},{"label":"C","text":"upon request by the Superintendent"},{"label":"D","text":"upon approval of the Governor"}],"correctAnswer":"C","explanation":"A producer’s insurance records be provided upon request of the Massachusetts Superintendent of Insurance.","explanationPt":"Os registros de seguro de um produtor devem ser fornecidos mediante solicitação do Superintendente de Seguros de Massachusetts.","theme":"Producers and Licensing","jurisdiction":"MA","review":false,"reviewFlags":[]},{"id":"Q317","sourceNumber":317,"duplicateIndex":1,"question":"A producer who is in violation of a deceptive act or practice may be fined up to","options":[{"label":"A","text":"$1,000"},{"label":"B","text":"$2,000"},{"label":"C","text":"$3,000"},{"label":"D","text":"$4,000"}],"correctAnswer":"A","explanation":"A producer who commits a deceptive act or practice may be fined no more than $1,000.","explanationPt":"Um produtor que cometer um ato ou prática enganosa pode ser multado em no máximo $1.000.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q318","sourceNumber":318,"duplicateIndex":1,"question":"How is a collateral assignment used in a life insurance contract?","options":[{"label":"A","text":"Transfers permanent ownership rights to a creditor"},{"label":"B","text":"Assigns complete ownership rights to a creditor"},{"label":"C","text":"Transfers specific ownership rights to a creditor"},{"label":"D","text":"Assigns ownership rights to the primary beneficiary"}],"correctAnswer":"C","explanation":"A collateral assignment entitles a creditor to be reimbursed out of policy proceeds for the amount owed.","explanationPt":"Uma cessão em garantia (collateral assignment) dá ao credor o direito de ser reembolsado a partir dos valores da apólice pelo montante devido.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q319","sourceNumber":319,"duplicateIndex":1,"question":"What is considered the collateral on a life insurance policy loan?","options":[{"label":"A","text":"No collateral is needed"},{"label":"B","text":"The policy's cash value"},{"label":"C","text":"The policy's face value"},{"label":"D","text":"The equity in a policyowner's home"}],"correctAnswer":"B","explanation":"When a life insurance policyowner obtains a policy loan, the collateral for the loan is the cash value of the policy.","explanationPt":"A resposta correta é B: o valor em dinheiro da apólice. Isso está correto porque, quando o titular de uma apólice de seguro de vida obtém um empréstimo sobre a apólice, a garantia (colateral) desse empréstimo é o valor em dinheiro da apólice.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX003","sourceNumber":null,"duplicateIndex":1,"question":"A signed good health statement may be requested by a life producer at the time of","options":[{"label":"A","text":"policy issue"},{"label":"B","text":"application"},{"label":"C","text":"policy delivery"},{"label":"D","text":"physical examination"}],"correctAnswer":"C","explanation":"A life insurance producer may be required to obtain a signature on a statement of good health at the time of policy delivery.","explanationPt":"A resposta correta é não identificada: alternativa marcada no material. Isso está correto porque um produtor de seguro de vida pode ser obrigado a obter a assinatura em uma declaração de boa saúde no momento da entrega da apólice.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q320","sourceNumber":320,"duplicateIndex":1,"question":"Which of the following relationships demonstrates insurable interest in the absence of economic interest?","options":[{"label":"A","text":"Lifelong friends"},{"label":"B","text":"Employees"},{"label":"C","text":"Marriage partners"},{"label":"D","text":"Business associates"}],"correctAnswer":"C","explanation":"Insurable interest may exist in marriage partners while absent of an economic interest.","explanationPt":"Pode existir interesse segurável entre cônjuges mesmo na ausência de um interesse econômico.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q321","sourceNumber":321,"duplicateIndex":1,"question":"Which of these may NOT be deducted from premium payments or the cash value of a variable life insurance policy?","options":[{"label":"A","text":"Mortality costs"},{"label":"B","text":"Administrative charges"},{"label":"C","text":"Investment management fees"},{"label":"D","text":"Federal premium taxes"}],"correctAnswer":"D","explanation":"All of these are allowable deductions to be made from premium payments or the cash value of a variable life insurance policy EXCEPT Federal premium taxes.","explanationPt":"Todas estas são deduções permitidas dos pagamentos de prêmio ou do valor em dinheiro de uma apólice de vida variável, EXCETO os impostos federais sobre prêmios.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q322","sourceNumber":322,"duplicateIndex":1,"question":"An appointed producer's implied authority is derived from","options":[{"label":"A","text":"the NAIC"},{"label":"B","text":"express authority"},{"label":"C","text":"the insurer's Certificate of Authority"},{"label":"D","text":"evident authority"}],"correctAnswer":"B","explanation":"By the very nature of what producer's are authorized to do (express authority), producers have the implied authority to act on behalf of the principal (insurer).","explanationPt":"Pela própria natureza do que os produtores estão autorizados a fazer (autoridade expressa), os produtores possuem autoridade implícita para agir em nome do principal (a seguradora).","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q323","sourceNumber":323,"duplicateIndex":1,"question":"How are qualified Roth IRA distributions normally treated for tax purposes?","options":[{"label":"A","text":"10% penalty tax is applied"},{"label":"B","text":"Taxed as ordinary income"},{"label":"C","text":"Capital gains tax is applied"},{"label":"D","text":"Received income tax-free"}],"correctAnswer":"D","explanation":"Qualified distributions are received income tax-free in a Roth IRA.","explanationPt":"As distribuições qualificadas de um Roth IRA são recebidas isentas de imposto de renda.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q324","sourceNumber":324,"duplicateIndex":1,"question":"Which tax would an IRA participant be subjected to on distributions received prior to age 59 1/2?","options":[{"label":"A","text":"10% tax penalty for early withdrawal"},{"label":"B","text":"Capital gains tax"},{"label":"C","text":"Income tax and penalty tax"},{"label":"D","text":"Ordinary income tax"}],"correctAnswer":"C","explanation":"Income tax and a penalty tax are generally assessed when a participant receives retirement savings from an IRA before reaching age 59 1/2.","explanationPt":"Geralmente são cobrados imposto de renda e uma multa fiscal quando um participante recebe recursos de aposentadoria de um IRA antes de completar 59 anos e meio.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q325","sourceNumber":325,"duplicateIndex":1,"question":"First-time homebuyers are able to withdraw up to how much from their qualified IRAs without incurring the 10% early withdrawal penalty?","options":[{"label":"A","text":"$2,500"},{"label":"B","text":"$5,000"},{"label":"C","text":"$7,500"},{"label":"D","text":"$10,000"}],"correctAnswer":"D","explanation":"First-time homebuyers are able to withdraw up to $10,000 from their qualified IRAs without incurring the 10% early withdrawal penalty.","explanationPt":"Compradores de primeira casa podem sacar até $10.000 de seus IRAs qualificados sem incorrer na multa de 10% por saque antecipado.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q326","sourceNumber":326,"duplicateIndex":1,"question":"Joe is a life insurance policyowner who has failed to pay interest on his policy loan. What will result from this nonpayment?","options":[{"label":"A","text":"The insurer can charge a higher rate of interest"},{"label":"B","text":"Loan amount is increased to reflect the amount of interest due"},{"label":"C","text":"Future loan privileges will be suspended"},{"label":"D","text":"The loan balance becomes due immediately"}],"correctAnswer":"B","explanation":"When an interest payment is not made, the policy loan amount is increased to reflect the amount of interest due.","explanationPt":"Quando um pagamento de juros não é feito, o valor do empréstimo sobre a apólice é aumentado para refletir o valor dos juros devidos.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q327","sourceNumber":327,"duplicateIndex":1,"question":"Which benefit can be found in an equity indexed annuity, but not in a fixed annuity?","options":[{"label":"A","text":"Protection against living too long"},{"label":"B","text":"Equity loans"},{"label":"C","text":"A fixed rate of return"},{"label":"D","text":"Protection against long-term inflation"}],"correctAnswer":"B","explanation":"An equity indexed annuity is tied to an equity index such as the S&P 500 but also provides a guaranteed minimum interest rate. It gives the annuitant the opportunity to beat the rate of inflation.","explanationPt":"Uma anuidade indexada a ações (equity indexed annuity) está vinculada a um índice de ações, como o S&P 500, mas também oferece uma taxa de juros mínima garantida. Isso dá ao anuitante a oportunidade de superar a taxa de inflação.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q328","sourceNumber":328,"duplicateIndex":1,"question":"The initial premium for a life insurance policy is typically paid in what way?","options":[{"label":"A","text":"The applicant mails it to the insurer after the policy has been approved"},{"label":"B","text":"It is typically obtained by the producer and forwarded to the insurer"},{"label":"C","text":"It is typically forwarded to the insurer by the applicant"},{"label":"D","text":"The producer pays it from any commissions received"}],"correctAnswer":"B","explanation":"The initial premium is usually collected by the producer and sent to the insurer.","explanationPt":"O prêmio inicial geralmente é recebido pelo produtor e enviado à seguradora.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q329","sourceNumber":329,"duplicateIndex":1,"question":"Death proceeds from a life insurance policy are typically included in a deceased insured's gross estate","options":[{"label":"A","text":"for federal income tax reasons"},{"label":"B","text":"for federal and state income tax purposes"},{"label":"C","text":"only if the insured's estate is listed as beneficiary"},{"label":"D","text":"only if the policy is owned by the beneficiary"}],"correctAnswer":"A","explanation":"Life insurance death proceeds are normally included in a deceased insured's gross estate for federal income tax purposes only.","explanationPt":"Os valores por morte de seguro de vida normalmente são incluídos no patrimônio bruto do segurado falecido apenas para fins de imposto de renda federal.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q330","sourceNumber":330,"duplicateIndex":1,"question":"A life insurance policy can be contested by the insurer only during the first___ years of the contract.","options":[{"label":"A","text":"two"},{"label":"B","text":"three"},{"label":"C","text":"four"},{"label":"D","text":"five"}],"correctAnswer":"A","explanation":"The incontestable clause in a life insurance policy stipulates that after a stated amount of time (typically 2 years) the legitimacy of the policy cannot be contested by the policyholder, unless fraud was involved.","explanationPt":"A cláusula de incontestabilidade em uma apólice de seguro de vida estipula que, após um período determinado (normalmente 2 anos), a legitimidade da apólice não pode ser contestada pela seguradora, a menos que tenha havido fraude.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q331","sourceNumber":331,"duplicateIndex":1,"question":"If an insured dies during the grace period without having paid the premium, how much will the insurer pay?","options":[{"label":"A","text":"Policy's face amount"},{"label":"B","text":"Total premiums paid will be returned"},{"label":"C","text":"Policy's face amount minus any premiums due"},{"label":"D","text":"Nothing"}],"correctAnswer":"C","explanation":"If an insured dies during the grace period and the premium has not been paid, the policy benefit is payable. However, the premium amount due is deducted from the death benefits paid to the beneficiary.","explanationPt":"Se um segurado morrer durante o período de carência e o prêmio não tiver sido pago, o benefício da apólice é pagável. No entanto, o valor do prêmio devido é deduzido do benefício por morte pago ao beneficiário.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q332","sourceNumber":332,"duplicateIndex":1,"question":"Why do insurers require a minimum number of employees participate in a group insurance plan?","options":[{"label":"A","text":"Efficiency is maximized"},{"label":"B","text":"Minimize adverse selection"},{"label":"C","text":"Profits are maximized"},{"label":"D","text":"Claims are minimized"}],"correctAnswer":"B","explanation":"The larger the group to be insured, the more predictable will be the expected losses from the group.","explanationPt":"Quanto maior o grupo a ser segurado, mais previsíveis serão as perdas esperadas desse grupo.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q333","sourceNumber":333,"duplicateIndex":1,"question":"At what point are death proceeds paid in a joint life insurance policy?","options":[{"label":"A","text":"When the first insured dies"},{"label":"B","text":"When the second insured dies"},{"label":"C","text":"Only after insurable interest has been confirmed to still exist"},{"label":"D","text":"If both insureds die from the same accident"}],"correctAnswer":"A","explanation":"A joint life policy covers two or more lives and provides for the payment of the proceeds at the death of the first among those insured, at which time the policy terminates.","explanationPt":"Uma apólice de vida conjunta cobre duas ou mais vidas e prevê o pagamento dos valores na morte do primeiro dos segurados, momento em que a apólice se encerra.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q334","sourceNumber":334,"duplicateIndex":1,"question":"Which statement regarding the joint and survivor life insurance settlement option is NOT true?","options":[{"label":"A","text":"Age of the beneficiaries plays a factor when determining the payment amounts"},{"label":"B","text":"Income continues until the last beneficiary dies"},{"label":"C","text":"Two or more beneficiaries can be paid"},{"label":"D","text":"The amount of each installment is larger than the single life income option"}],"correctAnswer":"D","explanation":"The amount of each installment would actually be larger with a single life income option as opposed to a joint and survivor option.","explanationPt":"O valor de cada parcela seria, na verdade, maior com uma opção de renda vitalícia individual do que com uma opção conjunta e de sobrevivência.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q335","sourceNumber":335,"duplicateIndex":1,"question":"What is another term used for a \"pure\" life annuity?","options":[{"label":"A","text":"Annuity certain"},{"label":"B","text":"Immediate annuity"},{"label":"C","text":"Life income"},{"label":"D","text":"Joint annuity"}],"correctAnswer":"C","explanation":"A \"pure\" life annuity (also known as \"life income\") provides the highest monthly income benefit. Upon the death of the annuitant, however, all remaining funds are lost to the insurer.","explanationPt":"Uma anuidade vitalícia \"pura\" (também conhecida como \"life income\") oferece o maior benefício de renda mensal. No entanto, com a morte do anuitante, todos os fundos remanescentes são perdidos para a seguradora.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q336","sourceNumber":336,"duplicateIndex":1,"question":"Security laws passed by Congress are enforced by which Federal agency?","options":[{"label":"A","text":"Securities Enforcement Agency (SEA)"},{"label":"B","text":"Department of Homeland Security"},{"label":"C","text":"Security and Exchange Commission"},{"label":"D","text":"National Association of Insurance Commissioners (NAIC)"}],"correctAnswer":"C","explanation":"The Security and Exchange Commission enforces the security laws enacted by Congress.","explanationPt":"A Securities and Exchange Commission (SEC) fiscaliza o cumprimento das leis de valores mobiliários promulgadas pelo Congresso.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q337","sourceNumber":337,"duplicateIndex":1,"question":"Which of these situations would NOT potentially involve a prison sentence under Federal law?","options":[{"label":"A","text":"Selling insurance with a nonresident license"},{"label":"B","text":"Misappropriating insurance premiums"},{"label":"C","text":"Embezzlement of an insurer's funds"},{"label":"D","text":"Sending threatening letters to an insurer"}],"correctAnswer":"A","explanation":"Selling insurance with a nonresident license is not a Federal violation.","explanationPt":"Vender seguros com uma licença de não residente não é uma violação federal.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q338","sourceNumber":338,"duplicateIndex":1,"question":"If the Commissioner requests access to a producer's business records, the producer","options":[{"label":"A","text":"has the right to refuse the request"},{"label":"B","text":"has 30 days to provide access to the records"},{"label":"C","text":"must provide access to the records upon request"},{"label":"D","text":"may demand a court order for the Commissioner's request"}],"correctAnswer":"C","explanation":"The Commissioner has the power to access producer business records upon request","explanationPt":"O Comissário tem o poder de acessar os registros comerciais de um produtor mediante solicitação.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q339","sourceNumber":339,"duplicateIndex":1,"question":"A qualified profit-sharing plan is designed to","options":[{"label":"A","text":"allow key employees to participate in the profits of the company"},{"label":"B","text":"distribute a portion of company earnings to its employees"},{"label":"C","text":"keep key employees from leaving the company"},{"label":"D","text":"allow employees to elect company officers"}],"correctAnswer":"B","explanation":"One of the purposes of a qualified profit-sharing plan is to distribute a portion of company earnings to employees.","explanationPt":"Um dos objetivos de um plano de participação nos lucros qualificado é distribuir parte dos lucros da empresa aos funcionários.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q340","sourceNumber":340,"duplicateIndex":1,"question":"After an insurance application has been originated, the producer normally","options":[{"label":"A","text":"can change the policy provisions"},{"label":"B","text":"determines whether a claim will be paid"},{"label":"C","text":"is the major personal contact to the insured"},{"label":"D","text":"conducts a physical examination"}],"correctAnswer":"C","explanation":"The producer originating an insurance application usually is the major personal contact with the insured.","explanationPt":"O produtor que dá origem a uma proposta de seguro geralmente é o principal contato pessoal com o segurado.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q341","sourceNumber":341,"duplicateIndex":1,"question":"Which of the following is NOT an intended use of an annuity?","options":[{"label":"A","text":"Obtain income benefits for a stated period of time for more than one person"},{"label":"B","text":"Accumulate assets on a tax-deferred basis"},{"label":"C","text":"Create immediate lifetime income benefits"},{"label":"D","text":"Create new funds upon the death of a wage-earner"}],"correctAnswer":"D","explanation":"All of these are uses of annuities EXCEPT create new funds upon the death of a wag-earner.","explanationPt":"Todos estes são usos de anuidades, EXCETO criar novos fundos após a morte de um assalariado.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q342","sourceNumber":342,"duplicateIndex":1,"question":"An annuity contract may be returned for a full refund during the","options":[{"label":"A","text":"inconestible period"},{"label":"B","text":"grace period"},{"label":"C","text":"free look period"},{"label":"D","text":"refund period"}],"correctAnswer":"C","explanation":"The period during which a buyer may return an annuity contract for a full refund is called the \"free look period\".","explanationPt":"O período durante o qual um comprador pode devolver um contrato de anuidade para reembolso total é chamado de \"período de reflexão\" (free look period).","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q343","sourceNumber":343,"duplicateIndex":1,"question":"A policyowner has a life insurance policy where she had listed her age on the application as 5 years younger than her actual age. If she dies and the insurer discovers the misstatement of age, how much will the insurance company pay?","options":[{"label":"A","text":"Nothing"},{"label":"B","text":"More than the face amount"},{"label":"C","text":"Less than the face amount"},{"label":"D","text":"Full face amount"}],"correctAnswer":"C","explanation":"In this situation, the insurance company will pay less than the face amount.","explanationPt":"Nesta situação, a seguradora pagará menos do que o valor de face.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q344","sourceNumber":344,"duplicateIndex":1,"question":"Which statement regarding the certificate of insurance is accurate?","options":[{"label":"A","text":"It is an insurance contract between the employer and insurer"},{"label":"B","text":"It indicates evidence of an employee's insurance coverage"},{"label":"C","text":"Each certificate of insurance is underwritten on an individual basis"},{"label":"D","text":"Itis issued by the employer to the employee"}],"correctAnswer":"B","explanation":"The certificate of insurance serves as evidence of an employee's coverage in a group life plan.","explanationPt":"O certificado de seguro serve como prova da cobertura de um funcionário em um plano de vida em grupo.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q345","sourceNumber":345,"duplicateIndex":1,"question":"The premiums paid by an employer for his employee's group life insurance are usually considered to be","options":[{"label":"A","text":"tax-deductible to the employer"},{"label":"B","text":"partially deductible to the employee"},{"label":"C","text":"tax-deductible to the employee"},{"label":"D","text":"taxable income to the employee"}],"correctAnswer":"A","explanation":"The amount an employer pays for his employee's life insurance is typically deductible to the business.","explanationPt":"O valor que um empregador paga pelo seguro de vida de seu funcionário geralmente é dedutível para a empresa.","theme":"Health Insurance","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q346","sourceNumber":346,"duplicateIndex":1,"question":"Which of the following does NOT involve a life settlement transaction?","options":[{"label":"A","text":"Converting term life coverage to whole life insurance"},{"label":"B","text":"Inducing life settlement contracts"},{"label":"C","text":"Monitoring life settlement contracts"},{"label":"D","text":"Securing life settlement contracts"}],"correctAnswer":"A","explanation":"The business of life settlements includes all of these except \"Converting term life coverage to whole life insurance\".","explanationPt":"O negócio de \"life settlements\" inclui todos estes itens, EXCETO \"converter cobertura de vida temporária (term) em seguro de vida inteira\".","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q347","sourceNumber":347,"duplicateIndex":1,"question":"Which of the following is NOT considered to be an expense for surviving family members of a deceased wage earner?","options":[{"label":"A","text":"Estate taxes"},{"label":"B","text":"Unemployment tax expenses"},{"label":"C","text":"Funeral expense"},{"label":"D","text":"Living expenses"}],"correctAnswer":"B","explanation":"Unemployment tax liabilities are not expenses a surviving family will normally have.","explanationPt":"Passivos de imposto sobre o desemprego geralmente não são despesas que uma família sobrevivente terá.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q348","sourceNumber":348,"duplicateIndex":1,"question":"A condition that increases the possibility of financial loss is called a(n)","options":[{"label":"A","text":"Risk"},{"label":"B","text":"Peril"},{"label":"C","text":"Hazard"},{"label":"D","text":"Exposure"}],"correctAnswer":"C","explanation":"A hazard is a condition that increases the possibility of loss.","explanationPt":"Um perigo (hazard) é uma condição que aumenta a possibilidade de uma perda.","theme":"General Insurance Concepts","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q349","sourceNumber":349,"duplicateIndex":1,"question":"Which of the following can be defined as a cause of a loss?","options":[{"label":"A","text":"Adversity"},{"label":"B","text":"Risk"},{"label":"C","text":"Hazard"},{"label":"D","text":"Peril"}],"correctAnswer":"D","explanation":"A peril may be defined as the cause of a loss.","explanationPt":"Um risco (peril) pode ser definido como a causa de uma perda.","theme":"General Insurance Concepts","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q350","sourceNumber":350,"duplicateIndex":1,"question":"Which of the following describes the act of insuring a risk against possible loss?","options":[{"label":"A","text":"Risk avoidance"},{"label":"B","text":"Risk transfer"},{"label":"C","text":"Hazard reduction"},{"label":"D","text":"Loss management"}],"correctAnswer":"B","explanation":"Insuring a risk against possible loss is an example of risk transfer","explanationPt":"Segurar um risco contra uma possível perda é um exemplo de transferência de risco.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q351","sourceNumber":351,"duplicateIndex":1,"question":"Which of the following can be defined as \"the potential for loss\"?","options":[{"label":"A","text":"Hazard"},{"label":"B","text":"Risk"},{"label":"C","text":"Transference"},{"label":"D","text":"Peril"}],"correctAnswer":"B","explanation":"fd Correct. A risk can be described as \"the potential for loss\"","explanationPt":"Correto. Um risco pode ser descrito como \"o potencial de perda\".","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q352","sourceNumber":352,"duplicateIndex":1,"question":"Life settlement brokers are NOT allowed to","options":[{"label":"A","text":"advertise their services"},{"label":"B","text":"implement fees"},{"label":"C","text":"introduce policyowners to settlement providers"},{"label":"D","text":"complete transactions prior to being approved for a license"}],"correctAnswer":"D","explanation":"Life settlement brokers need to be licensed before conducting any life settlement transactions. The exception to this would be certain eligible financial professionals.","explanationPt":"Corretores de life settlements precisam ser licenciados antes de realizar qualquer transação de life settlement. A exceção seria certos profissionais financeiros elegíveis.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q353","sourceNumber":353,"duplicateIndex":1,"question":"An insurer has a contractual agreement which transfers a portion of its risk exposure to another insurer. What type of contractual arrangement is this?","options":[{"label":"A","text":"Coinsurance contract"},{"label":"B","text":"Mutuality agreement"},{"label":"C","text":"Reinsurance contract"},{"label":"D","text":"Reciprocity arrangement"}],"correctAnswer":"C","explanation":"Reinsurance contracts accept a portion of the risk underwritten by another insurer who has contracted for the entire coverage amount.","explanationPt":"Os contratos de resseguro aceitam parte do risco subscrito por outra seguradora que contratou a cobertura total.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q354","sourceNumber":354,"duplicateIndex":1,"question":"How does the cost for a survivorship life policy compare to the cost of combining two separate individual life insurance policies?","options":[{"label":"A","text":"Survivorship life policy is lower"},{"label":"B","text":"Survivorship life policy is higher"},{"label":"C","text":"Depends on the investment performance of the underlying accounts"},{"label":"D","text":"Both have the same actuarial costs"}],"correctAnswer":"A","explanation":"Compared to the combined premium for separate life insurance policies on two individuals, the premium for a survivorship life policy is lower.","explanationPt":"A resposta correta é A: o prêmio da apólice de vida de sobrevivência é mais baixo. Isso está correto porque, em comparação com o prêmio combinado de apólices de seguro de vida separadas para dois indivíduos, o prêmio de uma apólice de vida de sobrevivência (survivorship life) é mais baixo.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX004","sourceNumber":null,"duplicateIndex":1,"question":"A survivorship life insurance policy usually covers how many lives?","options":[{"label":"A","text":"1"},{"label":"B","text":"2"},{"label":"C","text":"3"},{"label":"D","text":"4"}],"correctAnswer":"B","explanation":"Survivorship life insurance policies insure the lives of two people. It is a variation of a joint life policy that also insures the lives of two people.","explanationPt":"A resposta correta é B: 2. Isso está correto porque as apólices de seguro de vida de sobrevivência (survivorship life) seguram a vida de duas pessoas. É uma variação de uma apólice de vida conjunta que também segura a vida de duas pessoas.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q355","sourceNumber":355,"duplicateIndex":1,"question":"Which benefit is normally payable to a life insurance policyowner when the insured's life expectancy has been severely limited?","options":[{"label":"A","text":"Reduced paid-up option"},{"label":"B","text":"Accelerated (living) benefit"},{"label":"C","text":"Return of Premium benefit"},{"label":"D","text":"Extended term option"}],"correctAnswer":"B","explanation":"An accelerated (living) benefit is often payable to a policyowner who is terminally","explanationPt":"Um benefício acelerado (living benefit) costuma ser pagável a um titular de apólice que esteja em fase terminal.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q356","sourceNumber":356,"duplicateIndex":1,"question":"How much is normally paid to a policyowner in a life (viatical) settlement?","options":[{"label":"A","text":"Total premiums paid plus interest"},{"label":"B","text":"Full face amount"},{"label":"C","text":"More than the face amount"},{"label":"D","text":"Less than the death benefit"}],"correctAnswer":"D","explanation":"The amount received for a life insurance policy in a life (viatical) settlement is less than the death benefit.","explanationPt":"O valor recebido por uma apólice de seguro de vida em um acordo viático (viatical settlement) é menor do que o benefício por morte.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q357","sourceNumber":357,"duplicateIndex":1,"question":"Which of the following statements about the installments for a fixed period settlement option in life insurance policies is NOT true?","options":[{"label":"A","text":"The periodic payment amount is determined by the beneficiary's age"},{"label":"B","text":"The shorter the period of time, the larger each installment"},{"label":"C","text":"The longer the period of time, the smaller each installment"},{"label":"D","text":"The installment payments are composed of both principal and interest"}],"correctAnswer":"A","explanation":"The amount of the periodic payment in a fixed period settlement option is based on the length of the benefit period, not the beneficiary's age.","explanationPt":"O valor do pagamento periódico em uma opção de liquidação por período fixo (fixed period) é baseado na duração do período de benefício, não na idade do beneficiário.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q358","sourceNumber":358,"duplicateIndex":1,"question":"What is the best definition of a producer?","options":[{"label":"A","text":"An individual who provides insurance advice for compensation"},{"label":"B","text":"An individual appointed by an insurance company that represents the company and presents policies on its behalf"},{"label":"C","text":"An individual who places insurance business with insurers that are not authorized to transact business in this state"},{"label":"D","text":"An individual that evaluates and assumes another party's risk for a fee"}],"correctAnswer":"B","explanation":"A producer is an individual appointed by an insurance company that represents the company and presents policies on its behalf.","explanationPt":"Um produtor é um indivíduo credenciado por uma seguradora que representa a empresa e apresenta apólices em seu nome.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q359","sourceNumber":359,"duplicateIndex":1,"question":"Scott has a life insurance policy in which the dividends are left with the insurance company. This particular policy may be paid up when the cash value plus accumulated dividends","options":[{"label":"A","text":"equal the net single premium for the same face amount at the insured's attained age"},{"label":"B","text":"can purchase extended term coverage for a period of two years or more"},{"label":"C","text":"equal the nonforfeiture value of the policy"},{"label":"D","text":"can purchase a paid-addition"}],"correctAnswer":"A","explanation":"If life insurance policy dividends are left with the insurance company, the policy may be paid up when the cash value plus accumulated dividends equal the net single premium for the same face amount at the insured's attained age.","explanationPt":"Se os dividendos da apólice de seguro de vida forem deixados com a seguradora, a apólice pode ser quitada (paid up) quando o valor em dinheiro somado aos dividendos acumulados igualar o prêmio único líquido para o mesmo valor de face na idade atingida do segurado.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q360","sourceNumber":360,"duplicateIndex":1,"question":"Who is required to notify the Superintendent of a licensee's change of address?","options":[{"label":"A","text":"Licensee"},{"label":"B","text":"Beneficiary"},{"label":"C","text":"Agency"},{"label":"D","text":"Insurer"}],"correctAnswer":"A","explanation":"The licensee is responsible for reporting a change of name or address to the Superintendent of the Bureau of Insurance.","explanationPt":"O licenciado é responsável por informar ao Superintendente do Bureau de Seguros qualquer mudança de nome ou endereço.","theme":"Producers and Licensing","jurisdiction":"MA","review":false,"reviewFlags":[]},{"id":"Q361","sourceNumber":361,"duplicateIndex":1,"question":"A licensee whose name or address changes must notify the Superintendent within __ days.","options":[{"label":"A","text":"10"},{"label":"B","text":"15"},{"label":"C","text":"30"},{"label":"D","text":"45"}],"correctAnswer":"C","explanation":"A producer must notify the Superintendent of a change of address within 30 days.","explanationPt":"Um produtor deve notificar o Superintendente sobre uma mudança de endereço no prazo de 30 dias.","theme":"Producers and Licensing","jurisdiction":"MA","review":false,"reviewFlags":[]},{"id":"Q362","sourceNumber":362,"duplicateIndex":1,"question":"Which report contains information regarding an individual's general reputation and credit standing?","options":[{"label":"A","text":"Credit report"},{"label":"B","text":"Consumer report"},{"label":"C","text":"MIB report"},{"label":"D","text":"Agent's report"}],"correctAnswer":"B","explanation":"A consumer report contains information regarding a consumer's credit, reputation, or habits.","explanationPt":"Um relatório de consumidor contém informações sobre o crédito, a reputação ou os hábitos de um consumidor.","theme":"General Insurance Concepts","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q363","sourceNumber":363,"duplicateIndex":1,"question":"A life insurance policy that contains an accelerated (living) benefit rider will provide funds if the","options":[{"label":"A","text":"insured is expected to be confined to a nursing home for life"},{"label":"B","text":"insured recently had a minor heart attack"},{"label":"C","text":"insured has lost use of one arm"},{"label":"D","text":"insured is having dire financial problems"}],"correctAnswer":"A","explanation":"An insured may qualify for accelerated benefits if he/she has an illness or physical condition that can reasonably be expected to result in death within 24 months.","explanationPt":"Um segurado pode se qualificar para benefícios acelerados se tiver uma doença ou condição física que razoavelmente se espera resultar em morte dentro de 24 meses.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q364","sourceNumber":364,"duplicateIndex":1,"question":"Which would be described as a beneficiary designation by class?","options":[{"label":"A","text":"Children of the insured"},{"label":"B","text":"Estate of the insured"},{"label":"C","text":"Tertiary beneficiary"},{"label":"D","text":"A specific named beneficiary"}],"correctAnswer":"A","explanation":"With a beneficiary designation by class, the policyowner designates a class or group of beneficiaries instead of specifying one or more beneficiaries by name.","explanationPt":"Com uma designação de beneficiário por classe, o titular designa uma classe ou grupo de beneficiários em vez de especificar um ou mais beneficiários pelo nome.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q365","sourceNumber":365,"duplicateIndex":1,"question":"A producer's license may only be suspended or revoked if the producer","options":[{"label":"A","text":"has been afforded a right to a hearing"},{"label":"B","text":"has engaged in replacement of an existing policy"},{"label":"C","text":"filed for bankruptcy"},{"label":"D","text":"did not meet a sales quota"}],"correctAnswer":"A","explanation":"No existing insurance license will be revoked until the licensee has been afforded a right to a hearing on the charges.","explanationPt":"Nenhuma licença de seguro existente será revogada até que o licenciado tenha tido o direito a uma audiência sobre as acusações.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q366","sourceNumber":366,"duplicateIndex":1,"question":"A life insurance policyowner has been diagnosed with a terminal illness. Which of the following is often payable to a policyowner whose life expectancy is substantially reduced due to illness?","options":[{"label":"A","text":"Premium credits"},{"label":"B","text":"Accelerated (living) benefit"},{"label":"C","text":"Reduced paid-up insurance"},{"label":"D","text":"Full face amount"}],"correctAnswer":"B","explanation":"An accelerated (living) benefit is often payable to a life insurance policyowner when a medical condition drastically limits the insured's life expectancy.","explanationPt":"Um benefício acelerado (living benefit) costuma ser pagável ao titular de uma apólice de seguro de vida quando uma condição médica limita drasticamente a expectativa de vida do segurado.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q367","sourceNumber":367,"duplicateIndex":1,"question":"A terminally ill policyowner sells his life insurance policy at a discount to help pay for medical expenses. This arrangement is referred to as a(n)","options":[{"label":"A","text":"accelerated benefit"},{"label":"B","text":"life settlement"},{"label":"C","text":"living benefit"},{"label":"D","text":"discounted settlement"}],"correctAnswer":"B","explanation":"answer is \"li Life settlements allow policy holders to sell their policies for a percentage of the face amount for a cash payment.","explanationPt":"A resposta é que os \"life settlements\" permitem que titulares de apólices vendam suas apólices por um percentual do valor de face, em troca de um pagamento em dinheiro.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q368","sourceNumber":368,"duplicateIndex":1,"question":"In what way is a life insurance policy affected by an accelerated benefit payment?","options":[{"label":"A","text":"Decreases the premiums"},{"label":"B","text":"Extends the grace period"},{"label":"C","text":"Increases the policy loan balance"},{"label":"D","text":"Decreases the death benefit"}],"correctAnswer":"D","explanation":"An accelerated death benefit decreases the death benefit.","explanationPt":"Um benefício por morte acelerado reduz o benefício por morte.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q369","sourceNumber":369,"duplicateIndex":1,"question":"How many days notice must a producer be given prior to a scheduled hearing?","options":[{"label":"A","text":"10 days"},{"label":"B","text":"14 days"},{"label":"C","text":"21 days"},{"label":"D","text":"30 days"}],"correctAnswer":"C","explanation":"A producer must be given 21 days notice for a scheduled hearing.","explanationPt":"Um produtor deve receber um aviso de 21 dias para uma audiência agendada.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q370","sourceNumber":370,"duplicateIndex":1,"question":"A source of supplemental income for a life insurance policyowner can be derived from the","options":[{"label":"A","text":"cash value"},{"label":"B","text":"payor benefit"},{"label":"C","text":"consideration"},{"label":"D","text":"face amount"}],"correctAnswer":"A","explanation":"Cash value may be used as a source to supplement a policyowner's income.","explanationPt":"O valor em dinheiro pode ser usado como fonte para complementar a renda do titular da apólice.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q371","sourceNumber":371,"duplicateIndex":1,"question":"Which of the following involves sharing an uncertain risk with another similar group?","options":[{"label":"A","text":"Transfer"},{"label":"B","text":"Speculative"},{"label":"C","text":"Operational"},{"label":"D","text":"Physical"}],"correctAnswer":"A","explanation":"Risk transfer involves sharing an uncertain risk with another similar group.","explanationPt":"A transferência de risco envolve compartilhar um risco incerto com outro grupo semelhante.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q372","sourceNumber":372,"duplicateIndex":1,"question":"What happens to a life insurance policy when the policy loan balance exceeds the cash value?","options":[{"label":"A","text":"Nonforfeiture options are offered"},{"label":"B","text":"Policy becomes paid-up"},{"label":"C","text":"Automatic premium loan provision is utilized"},{"label":"D","text":"Policy will no longer be in force"}],"correctAnswer":"D","explanation":"In the event a policy loan balance exceeds a life insurance policy's cash value, the policy is no longer in force.","explanationPt":"Caso o saldo de um empréstimo sobre a apólice exceda o valor em dinheiro de uma apólice de seguro de vida, a apólice deixa de estar em vigor.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q373","sourceNumber":373,"duplicateIndex":1,"question":"John bought a deferred annuity on Mary. John amends the contract years later to name Tom as the recipient of the proceeds if Mary dies. Who is the annuitant for this contract?","options":[{"label":"A","text":"John"},{"label":"B","text":"Mary"},{"label":"C","text":"Tom"},{"label":"D","text":"Mary's estate"}],"correctAnswer":"B","explanation":"In this situation, Mary is the annuitant because that is where the proceeds of the annuity will be initially directed.","explanationPt":"Nesta situação, Mary é a anuitante, pois é para ela que os valores da anuidade serão inicialmente direcionados.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q374","sourceNumber":374,"duplicateIndex":1,"question":"How long does one premium payment cover in a single premium whole life policy?","options":[{"label":"A","text":"Until the policy's first renewal date"},{"label":"B","text":"One month"},{"label":"C","text":"One year"},{"label":"D","text":"Full life of the policy"}],"correctAnswer":"D","explanation":"One premium pa' covers the full life of the policy in a single premium whole life policy.","explanationPt":"Um único pagamento de prêmio cobre toda a vigência da apólice em uma apólice de vida inteira com prêmio único.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q375","sourceNumber":375,"duplicateIndex":1,"question":"The payment of the first premium, the promise to pay a covered loss, and the agreement to abide by policy conditions are all examples of","options":[{"label":"A","text":"consideration"},{"label":"B","text":"legal purpose"},{"label":"C","text":"representation"},{"label":"D","text":"acceptance"}],"correctAnswer":"A","explanation":"Consideration can be defined as the value given in exchange for the promises sought.","explanationPt":"A contraprestação (consideration) pode ser definida como o valor dado em troca das promessas buscadas.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q376","sourceNumber":376,"duplicateIndex":1,"question":"An insurance policy that can also be classified as a securities product is called","options":[{"label":"A","text":"variable life"},{"label":"B","text":"modified life"},{"label":"C","text":"universal life"},{"label":"D","text":"a Modified Endowment Contract"}],"correctAnswer":"A","explanation":"Because of the transfer of investment risk from the insurer to the policyowner, variable insurance products are considered securities contracts as well as insurance contracts.","explanationPt":"Devido à transferência do risco de investimento da seguradora para o titular, os produtos de seguro variáveis são considerados tanto contratos de valores mobiliários quanto contratos de seguro.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q377","sourceNumber":377,"duplicateIndex":1,"question":"How are level term policies able to provide level premiums?","options":[{"label":"A","text":"Policy dividends"},{"label":"B","text":"Yearly policy fees"},{"label":"C","text":"Yearly reductions in face amount"},{"label":"D","text":"Premiums are averaged over the term of the policy"}],"correctAnswer":"D","explanation":"vel term policies are able to offer level premiums because the premiums are averaged over the term of the policy.","explanationPt":"As apólices de termo nivelado (level term) conseguem oferecer prêmios nivelados porque os prêmios são calculados em média ao longo de todo o prazo da apólice.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q378","sourceNumber":378,"duplicateIndex":1,"question":"Interest is credited to a fixed annuity no lower than the","options":[{"label":"A","text":"variable contract rate"},{"label":"B","text":"contract guaranteed rate"},{"label":"C","text":"current rate of inflation"},{"label":"D","text":"prime rate"}],"correctAnswer":"B","explanation":"The interest rate on a fixed annuity does not fall below the contract guaranteed rate.","explanationPt":"A taxa de juros de uma anuidade fixa não cai abaixo da taxa garantida no contrato.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q379","sourceNumber":379,"duplicateIndex":1,"question":"An annuitant is paid $495 per month until the contract value is exhausted at some undetermined date in the future. Which type of annuity payout option is this?","options":[{"label":"A","text":"Fixed amount"},{"label":"B","text":"Straight life"},{"label":"C","text":"Period certain"},{"label":"D","text":"Installment refund"}],"correctAnswer":"A","explanation":"Under the fixed amount option, the annuitant receives a fixed payment until the contract value is exhausted, regardless of hen that will be. If the annuitant dies before the contract is depleted, the beneficiary receives the remainder.","explanationPt":"Na opção de valor fixo (fixed amount), o anuitante recebe um pagamento fixo até que o valor do contrato se esgote, independentemente de quando isso ocorrer. Se o anuitante morrer antes de o contrato se esgotar, o beneficiário recebe o restante.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q380","sourceNumber":380,"duplicateIndex":1,"question":"Al surrenders his life insurance policy for its cash value. The total of premiums paid into the policy minus total dividends received in cash or used to offset premiums is referred to as the","options":[{"label":"A","text":"premium basis"},{"label":"B","text":"net proceeds"},{"label":"C","text":"cash basis"},{"label":"D","text":"cost basis"}],"correctAnswer":"D","explanation":"The total of the premiums paid into the policy minus total dividends received in cash or used to offset premiums is referred to as the cost basis.","explanationPt":"O total dos prêmios pagos na apólice, menos o total de dividendos recebidos em dinheiro ou usados para compensar prêmios, é chamado de base de custo (cost basis).","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q381","sourceNumber":381,"duplicateIndex":1,"question":"Which of the following could be a future use of the cash value that builds in a recently-purchased whole life insurance policy?","options":[{"label":"A","text":"Convert the cash value to a paid-up term policy"},{"label":"B","text":"Gives policyowner ability to borrow against funds within two years"},{"label":"C","text":"Increases the policy's face amount"},{"label":"D","text":"Provide supplemental income in 35 years"}],"correctAnswer":"D","explanation":"Whole life policies typically begin to accrue cash value during the 3rd year after issue. The cash value that accumulates can be used to supplement income during retirement years.","explanationPt":"As apólices de vida inteira normalmente começam a acumular valor em dinheiro a partir do 3º ano após a emissão. O valor em dinheiro acumulado pode ser usado para complementar a renda durante os anos de aposentadoria.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q382","sourceNumber":382,"duplicateIndex":1,"question":"Which statement regarding universal life insurance is correct?","options":[{"label":"A","text":"Cash value accumulations have a guaranteed minimum interest rate"},{"label":"B","text":"Policyowner can change the face amount but not the premium"},{"label":"C","text":"Policyowner can change the premium but not the face amount"},{"label":"D","text":"Partial withdrawals cannot be made from the policy's cash value"}],"correctAnswer":"A","explanation":"Cash value accumulations are subject to a minimum interest guarantee in universal life insurance.","explanationPt":"No seguro de vida universal, o acúmulo de valor em dinheiro está sujeito a uma taxa de juros mínima garantida.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q383","sourceNumber":383,"duplicateIndex":1,"question":"Risk ____ is the process of analyzing exposures that create risk and designing programs to handle them.","options":[{"label":"A","text":"acceptance"},{"label":"B","text":"management"},{"label":"C","text":"administration"},{"label":"D","text":"transfer"}],"correctAnswer":"B","explanation":"The process of analyzing exposures that create risk and designing programs to handle them is called risk management.","explanationPt":"O processo de analisar as exposições que criam risco e de projetar programas para lidar com elas é chamado de gerenciamento de risco (risk management).","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q384","sourceNumber":384,"duplicateIndex":1,"question":"An agreement is reached when an insurance contract is formed. Which of the following is NOT considered to be an element of an agreement?","options":[{"label":"A","text":"Meeting of the minds"},{"label":"B","text":"Offer"},{"label":"C","text":"Acceptance"},{"label":"D","text":"Equity"}],"correctAnswer":"D","explanation":"Agreement in an insurance contract includes all of these EXCEPT \"Equity\".","explanationPt":"A resposta correta é D: Patrimônio (Equity). Isso está correto porque o acordo (agreement) em um contrato de seguro inclui todos estes elementos, EXCETO \"Patrimônio (Equity)\".","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX005","sourceNumber":null,"duplicateIndex":1,"question":"A life insurance guaranteed insurability rider gives the insured the right, without proving insurability, to","options":[{"label":"A","text":"O purchase life insurance policies on his children as they are born"},{"label":"B","text":"O purchase life insurance on a spouse after becoming married"},{"label":"C","text":"purchase additional life insurance at anytime"},{"label":"D","text":"periodically purchase additional insurance"}],"correctAnswer":"D","explanation":"Under a typical life insurance guaranteed insurability rider, an insured has the ability to purchase additional insurance at stated intervals without providing evidence of insurability.","explanationPt":"A resposta correta é D: comprar seguro adicional periodicamente. Isso está correto porque, em uma cláusula adicional típica de segurabilidade garantida (guaranteed insurability rider), o segurado tem a capacidade de comprar seguro adicional em intervalos determinados, sem apresentar prova de segurabilidade.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q385","sourceNumber":385,"duplicateIndex":1,"question":"Which of these is NOT considered a type of limited payment whole life insurance?","options":[{"label":"A","text":"Life paid-up at 65"},{"label":"B","text":"20 payment life"},{"label":"C","text":"15 payment life"},{"label":"D","text":"Endowment at age 70"}],"correctAnswer":"D","explanation":"All of these are forms of limited payment whole life insurance policies EXCEP Endowment at age 70.","explanationPt":"Todas estas são formas de apólices de vida inteira com pagamento limitado, EXCETO dotal (endowment) aos 70 anos.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q386","sourceNumber":386,"duplicateIndex":1,"question":"Who typically makes the purchase payments in an individual annuity?","options":[{"label":"A","text":"Owner"},{"label":"B","text":"Trustee"},{"label":"C","text":"Insurer"},{"label":"D","text":"Beneficiary"}],"correctAnswer":"A","explanation":"The purchase payments for an individual annuity are normally made by the owner.","explanationPt":"Os pagamentos de compra de uma anuidade individual normalmente são feitos pelo titular.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q387","sourceNumber":387,"duplicateIndex":1,"question":"A Massachusetts residential producer has been convicted of a felony. Under which circumstance may this producer resume engaging in insurance transactions?","options":[{"label":"A","text":"Upon completion of community service"},{"label":"B","text":"After paying a fine"},{"label":"C","text":"After the Commissioner gives written consent"},{"label":"D","text":"Upon completion of an extended continuing education program"}],"correctAnswer":"C","explanation":"A Massachusetts producer convicted of a felony may only engage in insurance transactions after being given written consent by the Commissioner.","explanationPt":"Um produtor de Massachusetts condenado por um crime grave (felony) só pode realizar transações de seguro após receber consentimento por escrito do Comissário.","theme":"Producers and Licensing","jurisdiction":"MA","review":false,"reviewFlags":[]},{"id":"Q388","sourceNumber":388,"duplicateIndex":1,"question":"Which statement regarding the life insurance premium for a children's rider is true?","options":[{"label":"A","text":"Decreasing premium as each child becomes an adult"},{"label":"B","text":"Premium remains the same no matter how many children"},{"label":"C","text":"Increasing premium as additional children are born"},{"label":"D","text":"No premium is normally charged for a children's rider"}],"correctAnswer":"B","explanation":"The life premium for a child rider remains the same regardless of the number of children.","explanationPt":"O prêmio de vida para uma cláusula adicional infantil (child rider) permanece o mesmo, independentemente do número de filhos.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q389","sourceNumber":389,"duplicateIndex":1,"question":"These are all accurate statements regarding universal life insurance EXCEPT","options":[{"label":"A","text":"Mortality charge is deducted from the policy's cash value each month"},{"label":"B","text":"Policy loans are not permitted"},{"label":"C","text":"Flexible premiums as long as the cost of insurance protection is covered"},{"label":"D","text":"Policy states what percentage of the premium is contributed to the cash value and which pays for the cost of insurance"}],"correctAnswer":"B","explanation":"Policy loans are allowed in universal life insurance policies.","explanationPt":"A resposta correta é B: os empréstimos sobre a apólice não são permitidos. Isso está correto porque, na verdade, os empréstimos sobre a apólice SÃO permitidos em apólices de seguro de vida universal — por isso essa afirmação é a incorreta.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX006","sourceNumber":null,"duplicateIndex":1,"question":"When would evidence of insurability be required for a person already covered with a variable universal life policy?","options":[{"label":"A","text":"When the premium is increased"},{"label":"B","text":"When the policy has renewed"},{"label":"C","text":"When the death benefit is increased"},{"label":"D","text":"When policy is being converted to permanent coverage"}],"correctAnswer":"C","explanation":"Evidence of insurability is normally required when the death benefit is increased in a variable universal life policy.","explanationPt":"A resposta correta é C: quando o benefício por morte é aumentado. Isso está correto porque normalmente é exigida prova de segurabilidade quando o benefício por morte é aumentado em uma apólice de vida universal variável.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q390","sourceNumber":390,"duplicateIndex":1,"question":"Which of these is NOT relevant when determining the amount of personal life insurance needed?","options":[{"label":"A","text":"Existing life insurance coverage"},{"label":"B","text":"Local unemployment rates"},{"label":"C","text":"Household income"},{"label":"D","text":"Household debt"}],"correctAnswer":"B","explanation":"In calculating the amount of personal life insurance needed, all of this information would be relevant except for local unemployment rates.","explanationPt":"Ao calcular o valor de seguro de vida pessoal necessário, todas estas informações seriam relevantes, exceto as taxas locais de desemprego.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q391","sourceNumber":391,"duplicateIndex":1,"question":"T is covered by an Accidental Death and Dismemberment (AD&D) policy that contains an irrevocable beneficiary. What action will the insurance company take if T requests a change of beneficiary?","options":[{"label":"A","text":"Request will be accepted only if in writing by the insured"},{"label":"B","text":"Change will be made only if premiums are paid current"},{"label":"C","text":"Change will be made immediately"},{"label":"D","text":"Request of the change will be refused"}],"correctAnswer":"D","explanation":"An irrevocable desi ion may not be changed without the written consent of the beneficiary.","explanationPt":"Uma designação irrevogável não pode ser alterada sem o consentimento por escrito do beneficiário.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q392","sourceNumber":392,"duplicateIndex":1,"question":"Which of the following disability buy-sell agreements is best suited for businesses with a limited number of partners?","options":[{"label":"A","text":"Split dollar plan"},{"label":"B","text":"Entity agreement"},{"label":"C","text":"Cross-purchase agreement"},{"label":"D","text":"Key person plan"}],"correctAnswer":"C","explanation":"A cross-purchase agreement is a document that allows a company's partners or other shareholders to purchase the interest or shares of a partner who dies, becomes incapacitated, or retires. A cross- purchase agreement is used in business continuation planning. A cross-purchase agreement is best suited for businesses with a limited number of partners.","explanationPt":"Um acordo de compra cruzada (cross-purchase agreement) é um documento que permite que os sócios ou outros acionistas de uma empresa comprem a participação ou as ações de um sócio que falece, fica incapacitado ou se aposenta. Esse acordo é usado no planejamento de continuidade empresarial e é mais adequado para empresas com um número limitado de sócios.","theme":"Health Insurance","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q393","sourceNumber":393,"duplicateIndex":1,"question":"What is the tax treatment of benefit payments for a non-qualified annuity?","options":[{"label":"A","text":"Benefit payments are always taxable"},{"label":"B","text":"Benefit payments are subject to taxes only prior to age 70 1/2"},{"label":"C","text":"Benefit payments must begin at age 59 1/2 to avoid a penalty"},{"label":"D","text":"Benefit payments received after 70 1/2 are always tax-exempt"}],"correctAnswer":"A","explanation":"Under a non-qualified annuity, benefits are taxable at all times. Furthermore, only the earnings (gains) are taxed as income; the principal is not.","explanationPt":"Em uma anuidade não qualificada, os benefícios são tributáveis o tempo todo. Além disso, apenas os rendimentos (ganhos) são tributados como renda; o principal não é.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q394","sourceNumber":394,"duplicateIndex":1,"question":"Field underwriting by a producer","options":[{"label":"A","text":"is used to reduce costs to the insurer"},{"label":"B","text":"involves conducting a physical examination of the applicant"},{"label":"C","text":"may result in the disclosure of hazardous activities of the applicant"},{"label":"D","text":"is illegal in most states"}],"correctAnswer":"C","explanation":"Field underwriting by a producer may result in the disclosure of hazardous activities of the applicant.","explanationPt":"A subscrição de campo (field underwriting) realizada por um produtor pode resultar na divulgação de atividades perigosas do proponente.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q395","sourceNumber":395,"duplicateIndex":1,"question":"Tori has an annuity that pays her a $500 per month income benefit for life or for ten years, whichever is longer. What kind of annuity is this?","options":[{"label":"A","text":"Fixed life annuity with period certain"},{"label":"B","text":"Variable life annuity with installment refund"},{"label":"C","text":"Fixed life annuity with cash refund"},{"label":"D","text":"Variable life annuity with period certain"}],"correctAnswer":"A","explanation":"A fixed life annuity with period certain is designed to pay the annuitant a fixed income for life, but guarantees a definite minimum period of payments.","explanationPt":"Uma anuidade vitalícia fixa com período certo (period certain) foi criada para pagar ao anuitante uma renda fixa por toda a vida, mas garante um período mínimo definido de pagamentos.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q396","sourceNumber":396,"duplicateIndex":1,"question":"The owner of a single premium deferred annuity is entitled to do all of these EXCEPT","options":[{"label":"A","text":"make additional payments into the annuity"},{"label":"B","text":"choose the length of the payout period"},{"label":"C","text":"choose who will be the recipient of the annuity payments"},{"label":"D","text":"cash surrender the contract"}],"correctAnswer":"A","explanation":"Single premium deferred annuities involve a single, lump-sum deposit.","explanationPt":"As anuidades diferidas de prêmio único envolvem um único depósito em quantia total.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q397","sourceNumber":397,"duplicateIndex":1,"question":"With life insurance, the needs approach is used primarily in determining","options":[{"label":"A","text":"which insurance company to purchase the coverage from"},{"label":"B","text":"how much life insurance a client should apply for"},{"label":"C","text":"the type of life insurance that should be purchased"},{"label":"D","text":"a budget for the surviving dependents to follow in the event of the client's death"}],"correctAnswer":"D","explanation":"The \"needs approach\" in life insurance is most useful in determining the amount of life insurance to be recommended to a client.","explanationPt":"A \"abordagem por necessidades\" (needs approach) no seguro de vida é a mais útil para determinar o valor de seguro de vida a ser recomendado a um cliente.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q398","sourceNumber":398,"duplicateIndex":1,"question":"A life insurance policyowner sells her policy to a third party in a life settlement. Under this transaction, the policyowner","options":[{"label":"A","text":"must pay income taxes on the full amount received"},{"label":"B","text":"receives an amount more than the policy's death benefit"},{"label":"C","text":"receives the policy's full death benefit"},{"label":"D","text":"receives an amount less than the policy's death benefit"}],"correctAnswer":"D","explanation":"The amount received for a life insurance policy in a life settlement is less than the death benefit.","explanationPt":"O valor recebido por uma apólice de seguro de vida em um life settlement é menor do que o benefício por morte.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q399","sourceNumber":399,"duplicateIndex":1,"question":"A policyowner with a terminal illness who sells his life insurance policy to a third party is called a","options":[{"label":"A","text":"viable"},{"label":"B","text":"viatical"},{"label":"C","text":"viator"},{"label":"D","text":"viatee"}],"correctAnswer":"C","explanation":"The original policyowner who sells his life policy to a third party for a reduced face amount is known as the \"viator\" in a viatical settlement.","explanationPt":"O titular original que vende sua apólice de vida a um terceiro por um valor de face reduzido é conhecido como o \"viator\" em um acordo viático (viatical settlement).","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q400","sourceNumber":400,"duplicateIndex":1,"question":"Which of the following is associated with an immediate annuity?","options":[{"label":"A","text":"Tax-free benefit payments"},{"label":"B","text":"Installment premium payments"},{"label":"C","text":"Lack of an accumulation period"},{"label":"D","text":"Lump-sum benefit"}],"correctAnswer":"C","explanation":"An immediate annuity lacks an accumulation period.","explanationPt":"Uma anuidade imediata não possui período de acumulação.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q401","sourceNumber":401,"duplicateIndex":1,"question":"Which of the following would NOT be appropriate for an immediate annuity?","options":[{"label":"A","text":"A lottery winner who opted for a lump-sum payment"},{"label":"B","text":"A parent saving for a child's college"},{"label":"C","text":"A beneficiary collecting the face amount of a life insurance policy"},{"label":"D","text":"Someone who just won a large settlement"}],"correctAnswer":"B","explanation":"Setting up a college savings account for a young child would not be a suitable situation for an immediate annuity.","explanationPt":"Criar uma conta de poupança para faculdade para uma criança pequena não seria uma situação adequada para uma anuidade imediata.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q402","sourceNumber":402,"duplicateIndex":1,"question":"An insurer will typically assess a back-end load on a deferred annuity that is cancelled during the early contract years. What is this back-end load referred to as?","options":[{"label":"A","text":"Back-end assessment"},{"label":"B","text":"Cancellation fee"},{"label":"C","text":"Surrender charge"},{"label":"D","text":"Tax penalty"}],"correctAnswer":"C","explanation":"When a deferred annuity is cancelled during the early years of the contract, the insurer will assess a back-end load known as a surrender charge.","explanationPt":"Quando uma anuidade diferida é cancelada nos primeiros anos do contrato, a seguradora cobrará uma taxa de saída conhecida como taxa de resgate (surrender charge).","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q403","sourceNumber":403,"duplicateIndex":1,"question":"Sarah, age 88, is a life annuitant who has lived beyond her life expectancy. The funds for additional benefit payments will be derived primarily from funds that were","options":[{"label":"A","text":"obtained from the state's Guaranty Association"},{"label":"B","text":"accumulated from the invested principal"},{"label":"C","text":"given up by the annuitant's refund beneficiary"},{"label":"B","text":"not distributed to life annuitants who died before life expectancy"}],"correctAnswer":"B","explanation":"When a life annuitant outlives life expectancy, the funds for additional benefit payments will be derived primarily from funds that were not distributed to life annuitants who died before life expectancy.","explanationPt":"Quando um anuitante vive além da expectativa de vida, os fundos para pagamentos adicionais de benefícios virão principalmente de fundos que não foram distribuídos a anuitantes que morreram antes da expectativa de vida.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q404","sourceNumber":404,"duplicateIndex":1,"question":"The absolute assignment of a life insurance policy results in","options":[{"label":"A","text":"all incidents of ownership transferred to the assignee"},{"label":"B","text":"the assignee receives partial incidents of ownership"},{"label":"C","text":"the transfer of ownership is revocable at the discretion of the original policyowner"},{"label":"D","text":"evidence of insurability must be proven before ownership is transferred"}],"correctAnswer":"A","explanation":"Under the absolute assignment of a life insurance policy, all incidents of ownership are transferred to the assignee.","explanationPt":"Sob uma cessão absoluta (absolute assignment) de uma apólice de seguro de vida, todos os direitos de propriedade são transferidos ao cessionário.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q405","sourceNumber":405,"duplicateIndex":1,"question":"Whose interests are being protected with the existence of replacement rules?","options":[{"label":"A","text":"Producer"},{"label":"B","text":"Beneficiary"},{"label":"C","text":"Policyowner"},{"label":"D","text":"Insurer"}],"correctAnswer":"C","explanation":"Replacement rules are designed primarily to protect the interest of the policyowner.","explanationPt":"As regras de substituição (replacement rules) são projetadas principalmente para proteger o interesse do titular da apólice.","theme":"Ethics and Compliance","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q406","sourceNumber":406,"duplicateIndex":1,"question":"Which benefit supplement added to a life insurance policy insures an entire family?","options":[{"label":"A","text":"Kin term rider"},{"label":"B","text":"Household term rider"},{"label":"C","text":"Family term rider"},{"label":"D","text":"Group term rider"}],"correctAnswer":"C","explanation":"The family term rider is attached to a life policy to insure all members of a family.","explanationPt":"A cláusula adicional de termo familiar (family term rider) é anexada a uma apólice de vida para segurar todos os membros de uma família.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q407","sourceNumber":407,"duplicateIndex":1,"question":"A policyowner is permitted to take out a policy loan on a whole life policy at what point?","options":[{"label":"A","text":"When the policy has a cash value"},{"label":"B","text":"When the policy has been in force 2 years"},{"label":"C","text":"When the cash value equals the face amount"},{"label":"D","text":"When the policyowner has demonstrated financial need"}],"correctAnswer":"A","explanation":"A policy loan can be obtained from a whole life insurance policy once it has accrued cash value.","explanationPt":"Um empréstimo sobre a apólice pode ser obtido de uma apólice de seguro de vida inteira assim que ela tiver acumulado valor em dinheiro.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q408","sourceNumber":408,"duplicateIndex":1,"question":"Which of these factors does NOT affect life insurance premium rates?","options":[{"label":"A","text":"Expense factor"},{"label":"B","text":"Interest factor"},{"label":"C","text":"Mortality factor"},{"label":"D","text":"Producer Certification"}],"correctAnswer":"D","explanation":"Mortality, expenses, and interest are the only factors that determine premium rates.","explanationPt":"Mortalidade, despesas e juros são os únicos fatores que determinam as taxas de prêmio.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q409","sourceNumber":409,"duplicateIndex":1,"question":"When compared to a fixed annuity, a variable annuity has what distinguishing feature?","options":[{"label":"A","text":"Flexible premiums according to a stock index"},{"label":"B","text":"Investment risk is assumed by the purchaser"},{"label":"C","text":"Investment risk is assumed by the insurer"},{"label":"D","text":"Payout option can be changed after the accumulation phase"}],"correctAnswer":"B","explanation":"The purchaser assumes the investment risk with a variable annuity.","explanationPt":"O comprador assume o risco de investimento em uma anuidade variável.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q410","sourceNumber":410,"duplicateIndex":1,"question":"Rick recently died and left behind an individual IRA account in his name. His widow was forwarded the balance of the IRA. The transfer of Rick's IRA account balance to his surviving spouse qualifies for","options":[{"label":"A","text":"the marital deduction"},{"label":"B","text":"death benefits"},{"label":"C","text":"Section 1035 exchange"},{"label":"D","text":"capital gains taxation"}],"correctAnswer":"A","explanation":"The transfer of a decedent's IRA account balance to a surviving spouse qualifies for the Unlimited Marital Deduction, which generally exempts the transfer from estate taxes.","explanationPt":"A transferência do saldo da conta IRA de um falecido para o cônjuge sobrevivente se qualifica para a Dedução Marital Ilimitada, que geralmente isenta a transferência de impostos sobre heranças.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q411","sourceNumber":411,"duplicateIndex":1,"question":"Life insurance premiums are computed on what three factors?","options":[{"label":"A","text":"Mortality, interest, dividends"},{"label":"B","text":"Morbidity, interest, expenses"},{"label":"C","text":"Mortality, interest, expenses"},{"label":"D","text":"Morbidity, interest, dividends"}],"correctAnswer":"C","explanation":"Mortality, interest, and expenses are the three factors used in computing life insurance gross premium.","explanationPt":"Mortalidade, juros e despesas são os três fatores usados no cálculo do prêmio bruto do seguro de vida.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q412","sourceNumber":412,"duplicateIndex":1,"question":"The annuitant in a single premium deferred annuity (SPDA)","options":[{"label":"A","text":"receives immediate benefit payments"},{"label":"B","text":"makes only one premium payment"},{"label":"C","text":"can make tax-free withdrawals until the principal is recovered"},{"label":"D","text":"is also the beneficiary"}],"correctAnswer":"B","explanation":"The contract owner in a single premium deferred annuity (SPDA) makes only one lump-sum payment.","explanationPt":"O titular do contrato em uma anuidade diferida de prêmio único (SPDA) faz apenas um único pagamento total.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q413","sourceNumber":413,"duplicateIndex":1,"question":"What must be given to a life insurance applicant when the agent receives an application and the initial premium?","options":[{"label":"A","text":"Agent's report"},{"label":"B","text":"Conditional receipt"},{"label":"C","text":"Commission disclosure"},{"label":"D","text":"Good health statement"}],"correctAnswer":"B","explanation":"A conditional receipt is given to an applicant upon receipt of the initial premium.","explanationPt":"Um recibo condicional é entregue ao proponente no momento do recebimento do prêmio inicial.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q414","sourceNumber":414,"duplicateIndex":1,"question":"A retirement plan that sets aside part of the company's net income for distributions to qualified employees is called a","options":[{"label":"A","text":"rollover plan"},{"label":"B","text":"403(b) plan"},{"label":"C","text":"profit-sharing plan"},{"label":"D","text":"salary reduction plan"}],"correctAnswer":"C","explanation":"Profit-sharing plans set aside a portion of a company's net income for distributions to qualified employees.","explanationPt":"Os planos de participação nos lucros reservam uma parte do lucro líquido de uma empresa para distribuição aos funcionários qualificados.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q415","sourceNumber":415,"duplicateIndex":1,"question":"What is an insurance contract that identifies individuals by relationship to a specific organization?","options":[{"label":"A","text":"Employer insurance"},{"label":"B","text":"Group insurance"},{"label":"C","text":"COBRA plan"},{"label":"D","text":"Industrial insurance"}],"correctAnswer":"B","explanation":"An insurance policy that covers individuals of a particular organization is called group insurance.","explanationPt":"Uma apólice de seguro que cobre indivíduos de uma determinada organização é chamada de seguro em grupo.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q416","sourceNumber":416,"duplicateIndex":1,"question":"Which of these statements is NOT true regarding a cash value loan against a life insurance policy?","options":[{"label":"A","text":"Interest normally accrues on unpaid balances"},{"label":"B","text":"Loan cannot exceed the policy's cash value"},{"label":"C","text":"Policy contract terms dictate the interest rate"},{"label":"D","text":"Interest payments made by policyowner are deductible"}],"correctAnswer":"D","explanation":"The policyowner's interest payments are NOT tax deductible.","explanationPt":"Os pagamentos de juros do titular da apólice NÃO são dedutíveis do imposto de renda.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q417","sourceNumber":417,"duplicateIndex":1,"question":"Which of the following is NOT a reason for a business to buy key person life insurance?","options":[{"label":"A","text":"The reduction in sales as a direct result from death of the key employee"},{"label":"B","text":"Avoid in leadership if the key person were to die"},{"label":"C","text":"The loss of company revenues while a replacement is being sought"},{"label":"D","text":"An increased pension liability if the key employee dies"}],"correctAnswer":"D","explanation":"All of these are reasons for a business organization to purchase key person life insurance EXCEPT \"An increased pension liability if the key employee dies\".","explanationPt":"A resposta correta é D: um aumento na responsabilidade previdenciária caso o funcionário-chave morra. Isso está correto porque todas as demais opções são razões válidas para uma empresa comprar seguro de vida de pessoa-chave, EXCETO essa.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX007","sourceNumber":null,"duplicateIndex":1,"question":"Employers often purchase life insurance on a key employee in order to","options":[{"label":"A","text":"provide an income to the deceased key employee's family"},{"label":"B","text":"pay for funeral costs"},{"label":"C","text":"provide the employer with a tax credit"},{"label":"D","text":"pay for finding and training a replacement if the employee dies prematurely"}],"correctAnswer":"D","explanation":"Employers will frequently purchase life insurance on a key employee to help offset the cost of finding and training a replacement in the event of the key employee's premature death.","explanationPt":"A resposta correta é D: cobrir os custos de encontrar e treinar um substituto caso o funcionário morra prematuramente. Isso está correto porque os empregadores frequentemente compram seguro de vida sobre um funcionário-chave para ajudar a compensar o custo de encontrar e treinar um substituto em caso de morte prematura desse funcionário.","theme":"Ethics and Compliance","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX008","sourceNumber":null,"duplicateIndex":1,"question":"The interest paid during an annuity's payout period is considered","options":[{"label":"A","text":"nontaxable"},{"label":"B","text":"taxable as ordinary income"},{"label":"C","text":"taxable as capital gains"},{"label":"D","text":"tax-deductible"}],"correctAnswer":"B","explanation":"The interest paid during an annuity's payout period is considered taxable as ordinary income.","explanationPt":"A resposta correta é B: tributável como renda ordinária. Isso está correto porque os juros pagos durante o período de pagamento de uma anuidade são considerados tributáveis como renda ordinária.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q418","sourceNumber":418,"duplicateIndex":1,"question":"After the first 3 years of licensure, a producer must complete ___ credit hours of continuing education for each licensing period.","options":[{"label":"A","text":"30"},{"label":"B","text":"45"},{"label":"C","text":"60"},{"label":"D","text":"75"}],"correctAnswer":"B","explanation":"After the first triennium (3 years), 45 credit hours of continuing education is required by a licensed producer for each licensing period.","explanationPt":"Após o primeiro triênio (3 anos), são exigidas 45 horas de educação continuada por um produtor licenciado a cada período de licenciamento.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q419","sourceNumber":419,"duplicateIndex":1,"question":"When using the needs approach for life insurance planning, a lump sum may be created to provide for all of the following EXCEPT","options":[{"label":"A","text":"Final expenses"},{"label":"B","text":"Charitable donation"},{"label":"C","text":"Education"},{"label":"D","text":"Employee benefits"}],"correctAnswer":"D","explanation":"The needs approach to personal life insurance planning may involve creating a lump sum to provide for all of these EXCEPT employee benefits.","explanationPt":"A abordagem por necessidades no planejamento pessoal de seguro de vida pode envolver a criação de uma quantia total para cobrir todos estes itens, EXCETO benefícios trabalhistas.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q420","sourceNumber":420,"duplicateIndex":1,"question":"Under an adjustable life insurance policy, which of the following may NOT be changed without further underwriting?","options":[{"label":"A","text":"The person insured"},{"label":"B","text":"The period of coverage"},{"label":"C","text":"The payment period"},{"label":"D","text":"The plan of coverage"}],"correctAnswer":"A","explanation":"All of these may normally be changed without further underwriting in an adjustable life insurance policy EXCEPT for \"The individual who is insured\".","explanationPt":"Todos estes itens normalmente podem ser alterados sem nova subscrição em uma apólice de seguro de vida ajustável, EXCETO \"o indivíduo que é o segurado\".","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q421","sourceNumber":421,"duplicateIndex":1,"question":"A \"premature\" distribution from a modified endowment contract (MEC) incurs a penalty tax of","options":[{"label":"A","text":"5%"},{"label":"B","text":"10%"},{"label":"C","text":"15%"},{"label":"D","text":"20%"}],"correctAnswer":"B","explanation":"Penalty taxes (10%) on premature distributions prior to age 59 1/2 from a modified endowment contract (MEC) normally apply to policy loans.","explanationPt":"As multas fiscais (10%) sobre distribuições antecipadas antes dos 59 anos e meio de um contrato de dotação modificado (MEC) normalmente se aplicam a empréstimos sobre a apólice.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q422","sourceNumber":422,"duplicateIndex":1,"question":"A trustee-to-trustee transfer of rollover funds in a qualified plan allows a participant to avoid","options":[{"label":"A","text":"mandatory income tax withholding on the amount transferred"},{"label":"B","text":"paying transfer fees"},{"label":"C","text":"paying trustee fees"},{"label":"D","text":"ever paying income taxes on the distributions"}],"correctAnswer":"A","explanation":"There is no federal tax withholding involved in a transfer of funds from one qualified plan into another. Rollovers, however, involve a 20% withholding. Once the rollover takes place to the new custodian, the remainder of the distribution is made.","explanationPt":"Não há retenção de imposto federal em uma transferência de fundos de um plano qualificado para outro. Os rollovers, no entanto, envolvem uma retenção de 20%. Assim que o rollover for realizado para o novo custodiante, o restante da distribuição é liberado.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q423","sourceNumber":423,"duplicateIndex":1,"question":"After an applicant reads and signs an insurance application, he/she should be conscious of the fact that","options":[{"label":"A","text":"a false statement could lead to loss of coverage"},{"label":"B","text":"premium refunds are not allowed"},{"label":"C","text":"the policy is guaranteed to be issued"},{"label":"D","text":"the premium quoted by the agent is final"}],"correctAnswer":"A","explanation":"The applicant should realize that any false statements on an insurance application could lead to loss of coverage.","explanationPt":"O proponente deve entender que quaisquer declarações falsas em uma proposta de seguro podem resultar na perda da cobertura.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q424","sourceNumber":424,"duplicateIndex":1,"question":"A policyowner has just borrowed from a life insurance policy's cash value. Which of these statements is true?","options":[{"label":"A","text":"In the event of death, the loan amount is deducted from the policy proceeds"},{"label":"B","text":"The policy lapses if not repaid within 5 years"},{"label":"C","text":"A policyowner must pre-qualify for the loan to determine creditworthiness"},{"label":"D","text":"Interest on the loan amount is prohibited"}],"correctAnswer":"A","explanation":"If a life insurance policyowner borrows the cash value of a policy, the amount of the loan outstanding is deducted from the policy proceeds.","explanationPt":"A resposta correta é A: em caso de morte, o valor do empréstimo é deduzido dos valores da apólice. Isso está correto porque, se o titular de uma apólice de seguro de vida tomar emprestado o valor em dinheiro de uma apólice, o valor do empréstimo pendente é deduzido dos valores da apólice.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX009","sourceNumber":null,"duplicateIndex":1,"question":"A life insurance policy provision that has the ability to reduce the death benefit is called the","options":[{"label":"A","text":"accelerated (living) benefit"},{"label":"B","text":"insuring clause"},{"label":"C","text":"payor benefit"},{"label":"D","text":"spendthrift clause"}],"correctAnswer":"A","explanation":"Whatever amount is withdrawn from an accelerated benefit will be deducted from the face amount when death occurs.","explanationPt":"A resposta correta é A: benefício acelerado (living benefit). Isso está correto porque qualquer valor sacado de um benefício acelerado será deduzido do valor de face quando ocorrer a morte.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q425","sourceNumber":425,"duplicateIndex":1,"question":"Which of the following is true regarding a person receiving a waiver of premium benefit?","options":[{"label":"A","text":"The insured must expect a total recovery within 2 years"},{"label":"B","text":"The insured will not qualify for short-term disability"},{"label":"C","text":"The insured will not qualify for workers compensation"},{"label":"D","text":"The insured must be disabled for a period of time"}],"correctAnswer":"D","explanation":"In order to qualify for the waiver of premium benefit, the insured must be disabled for a period of time.","explanationPt":"Para se qualificar para o benefício de isenção de prêmio, o segurado deve estar incapacitado por um determinado período de tempo.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q426","sourceNumber":426,"duplicateIndex":1,"question":"What happens when an initial offer is answered with a counteroffer?","options":[{"label":"A","text":"An arbitrator decides on a compromise"},{"label":"B","text":"The counteroffer is legally enforceable"},{"label":"C","text":"Initial offer is void"},{"label":"D","text":"Initial offer is automatically accepted"}],"correctAnswer":"C","explanation":"When an offer is answered by a counteroffer, the first offer is void.","explanationPt":"Quando uma oferta é respondida com uma contraproposta, a oferta original é anulada.","theme":"General Insurance Concepts","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q427","sourceNumber":427,"duplicateIndex":1,"question":"A nonparticipating whole life insurance policy was surrendered for its $20,000 cash value. The total premiums paid had totaled $16,000. What were the federal income tax consequences to the policyowner on receipt of the cash value?","options":[{"label":"A","text":"$16,000 was received as ordinary income and $4,000 as tax-free"},{"label":"B","text":"$20,000 was received as a capital gain"},{"label":"C","text":"$20,000 was received as ordinary income"},{"label":"D","text":"$16,000 was received tax-free and $4,000 as ordinary income"}],"correctAnswer":"D","explanation":"In this situatio e policyowner would receive $16,000 tax free and $4,000 as ordinary income.","explanationPt":"A resposta correta é D: $16.000 foram recebidos isentos de imposto e $4.000 como renda ordinária. Isso está correto porque, nesta situação, o titular receberia $16.000 isentos de imposto e $4.000 como renda ordinária.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX010","sourceNumber":null,"duplicateIndex":1,"question":"Life settlement proceeds may be subject to the claims of","options":[{"label":"A","text":"creditors"},{"label":"B","text":"adjusters"},{"label":"C","text":"insurers"},{"label":"D","text":"beneficiaries"}],"correctAnswer":"A","explanation":"Proceeds of a life settlement contract could be subject to the claims of creditors.","explanationPt":"A resposta correta é A: credores. Isso está correto porque os valores de um contrato de life settlement podem estar sujeitos às reivindicações de credores.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q428","sourceNumber":428,"duplicateIndex":1,"question":"How do benefit payments fluctuate over time in a variable life annuity?","options":[{"label":"A","text":"Benefit payments stay fixed"},{"label":"B","text":"Reflects changes in the market value of assets in a separate account"},{"label":"C","text":"Annuitant controls any benefit payment changes"},{"label":"D","text":"Any benefit payment fluctuations have to be approved in writing by the owner"}],"correctAnswer":"B","explanation":"A variable annuity's benefit payment reflects changes in the market value of assets in a separate account.","explanationPt":"O pagamento de benefício de uma anuidade variável reflete as mudanças no valor de mercado dos ativos em uma conta separada.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q429","sourceNumber":429,"duplicateIndex":1,"question":"Which of these is NOT used as selection criteria in the underwriting process of a life insurance application?","options":[{"label":"A","text":"Credit report"},{"label":"B","text":"National origin"},{"label":"C","text":"Age of applicant"},{"label":"D","text":"Sex of applicant"}],"correctAnswer":"B","explanation":"National origin is not used as an underwriting selection criteria for life insurance","explanationPt":"A resposta correta é B: origem nacional. Isso está correto porque a origem nacional não é usada como critério de seleção de subscrição para o seguro de vida.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX011","sourceNumber":null,"duplicateIndex":1,"question":"The authority to change the beneficiary in an individual annuity lies with the","options":[{"label":"A","text":"annuitant"},{"label":"B","text":"owner"},{"label":"C","text":"beneficiary"},{"label":"D","text":"administrator"}],"correctAnswer":"B","explanation":"The power to change the beneficiary in an individual annuity lies with the owner.","explanationPt":"A resposta correta é B: o titular. Isso está correto porque o poder de mudar o beneficiário em uma anuidade individual pertence ao titular.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q430","sourceNumber":430,"duplicateIndex":1,"question":"Which of the following would NOT have a restricted ability to enter into a contract?","options":[{"label":"A","text":"Mentally ill person"},{"label":"B","text":"Minor"},{"label":"C","text":"Person under the influence of alcohol"},{"label":"D","text":"Small employer"}],"correctAnswer":"D","explanation":"Small employers do not have a restricted ability to enter in a contract.","explanationPt":"Pequenos empregadores não têm capacidade restrita para celebrar um contrato.","theme":"General Insurance Concepts","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q431","sourceNumber":431,"duplicateIndex":1,"question":"Who is required to notify the producer in the event of appointment termination?","options":[{"label":"A","text":"Governor"},{"label":"B","text":"Superintendent"},{"label":"C","text":"Attorney General"},{"label":"D","text":"Insurer"}],"correctAnswer":"D","explanation":"A producer's cancellation of appointment must be reported to the Bureau of Insurance by the insurance company.","explanationPt":"O cancelamento do credenciamento de um produtor deve ser reportado ao Bureau de Seguros pela seguradora.","theme":"Producers and Licensing","jurisdiction":"MA","review":false,"reviewFlags":[]},{"id":"Q432","sourceNumber":432,"duplicateIndex":1,"question":"Which of these is true regarding the exchange of consideration among parties involved in an insurance contract?","options":[{"label":"A","text":"Required to be in currency"},{"label":"B","text":"Must be equal"},{"label":"C","text":"Can be unequal"},{"label":"D","text":"Must be certified by the state where transaction takes place"}],"correctAnswer":"C","explanation":"Insurance contracts are aleatory. This means there is an element of chance and potential for unequal exchange of value for both parties.","explanationPt":"A resposta correta é C: pode ser desigual. Isso está correto porque os contratos de seguro são aleatórios (aleatory). Isso significa que há um elemento de sorte e potencial de troca desigual de valor entre as partes.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX012","sourceNumber":null,"duplicateIndex":1,"question":"The main purpose of an annuity is to","options":[{"label":"A","text":"provide a tax shelter"},{"label":"B","text":"create an estate"},{"label":"C","text":"create a stream of income"},{"label":"D","text":"provide a death benefit"}],"correctAnswer":"C","explanation":"An annuity is simply a vehicle for liquidating a sum of money.","explanationPt":"A resposta correta é C: criar um fluxo de renda. Isso está correto porque uma anuidade é simplesmente um veículo para liquidar uma quantia em dinheiro.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q433","sourceNumber":433,"duplicateIndex":1,"question":"How can an insurance company minimize exposure to loss?","options":[{"label":"A","text":"Risk concealing"},{"label":"B","text":"Reinsuring risks"},{"label":"C","text":"Reissuance"},{"label":"D","text":"Risk assumption"}],"correctAnswer":"B","explanation":"Many insurers are able to minimize exposure to loss by reinsuring risk:","explanationPt":"Muitas seguradoras conseguem minimizar sua exposição a perdas ao resseguir o risco.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q434","sourceNumber":434,"duplicateIndex":1,"question":"An insurer has a contractual agreement which transfers a portion of its risk exposure to another insurer. What type of contractual arrangement is this?","options":[{"label":"A","text":"Coinsurance contract"},{"label":"B","text":"Mutuality agreement"},{"label":"C","text":"Reinsurance contract"},{"label":"D","text":"Reciprocity arrangement"}],"correctAnswer":"C","explanation":"Reinsurance contracts accept a portion of the risk underwritten by another insurer who has contracted for the entire coverage amount.","explanationPt":"Os contratos de resseguro aceitam parte do risco subscrito por outra seguradora que contratou a cobertura total.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q435","sourceNumber":435,"duplicateIndex":1,"question":"When must insurable interest exist for a life insurance contract to be valid?","options":[{"label":"A","text":"Inception of the contract"},{"label":"B","text":"Throughout the entire length of the contract"},{"label":"C","text":"When the insured dies"},{"label":"D","text":"During the contestable period"}],"correctAnswer":"A","explanation":"Insurable interest must only exist at the inception of the contract.","explanationPt":"O interesse segurável deve existir apenas no início do contrato.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q435-2","sourceNumber":435,"duplicateIndex":2,"question":"Insurable interest in one's own life is legally considered as","options":[{"label":"A","text":"illegal in most states"},{"label":"B","text":"limited"},{"label":"C","text":"generally unlimited"},{"label":"D","text":"contingent on future earnings"}],"correctAnswer":"C","explanation":"The insurable interest on one's own life is generally regarded as unlimited.","explanationPt":"A resposta correta é C: geralmente ilimitado. Isso está correto porque o interesse segurável sobre a própria vida geralmente é considerado ilimitado.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX013","sourceNumber":null,"duplicateIndex":1,"question":"The exclusion ratio determines","options":[{"label":"A","text":"how long an annuitant receives benefit payments"},{"label":"B","text":"if an annuity is eligible for a 1035 exchange"},{"label":"C","text":"the interest rate for an annuity"},{"label":"D","text":"the amount of an annuity payment subject to income tax"}],"correctAnswer":"D","explanation":"The exclusion ratio determines the amount of an annuity payment subject to income tax.","explanationPt":"A resposta correta é D: o valor de um pagamento de anuidade sujeito a imposto de renda. Isso está correto porque o índice de exclusão (exclusion ratio) determina o valor de um pagamento de anuidade sujeito a imposto de renda.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX014","sourceNumber":null,"duplicateIndex":1,"question":"After the extended term life nonforfeiture option is chosen, the available insurance will be","options":[{"label":"A","text":"increasing term for a stated period of time"},{"label":"B","text":"level term for a stated period of time"},{"label":"C","text":"decreasing term for a stated period of time"},{"label":"D","text":"renewable for a stated period of time"}],"correctAnswer":"B","explanation":"Under the extended term life insurance nonforfeiture option, the available insurance is level term for a stated period of time. The amount of coverage is the same as the original face amount.","explanationPt":"A resposta correta é B: termo nivelado por um período determinado. Isso está correto porque, na opção de não confisco de termo estendido (extended term), o seguro disponível é termo nivelado por um período determinado. O valor da cobertura é igual ao valor de face original.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q436","sourceNumber":436,"duplicateIndex":1,"question":"Which of these is NOT an underwriting responsibility of a life insurance agent?","options":[{"label":"A","text":"Asking relevant questions concerning an applicant's avocations"},{"label":"B","text":"Requesting an attending physician's report (APR)"},{"label":"C","text":"Ordering an inspection report"},{"label":"D","text":"Determining the final rate classification"}],"correctAnswer":"D","explanation":"Determining the final rate classification is not the responsibility of the life insurance agent.","explanationPt":"A resposta correta é D: determinar a classificação final de risco. Isso está correto porque determinar a classificação final de risco não é responsabilidade do agente de seguro de vida.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX015","sourceNumber":null,"duplicateIndex":1,"question":"Taking a sum of money and decreasing it in size is called","options":[{"label":"A","text":"capital gains"},{"label":"B","text":"capital appreciation"},{"label":"C","text":"capital liquidation"},{"label":"D","text":"capital sum"}],"correctAnswer":"C","explanation":"Capital liquidation creates a situation in which a sum of money decreases in size.","explanationPt":"A resposta correta é C: liquidação de capital. Isso está correto porque a liquidação de capital cria uma situação em que uma quantia em dinheiro diminui de tamanho.","theme":"General Insurance Concepts","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX016","sourceNumber":null,"duplicateIndex":1,"question":"A producer who misrepresented pertinent policy provisions related to a claim committed a(n)","options":[{"label":"A","text":"felony"},{"label":"B","text":"unfair claims settlement practice"},{"label":"C","text":"violation of federal law"},{"label":"D","text":"act of defamation"}],"correctAnswer":"B","explanation":"Misrepresenting pertinent policy provisions relating to coverage after a loss is an unfair claims settlement practice.","explanationPt":"A resposta correta é não identificada: alternativa marcada no material. Isso está correto porque fazer declaração falsa sobre cláusulas relevantes da apólice relacionadas à cobertura após um sinistro é uma prática desleal de liquidação de sinistros.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q437","sourceNumber":437,"duplicateIndex":1,"question":"The insurer's obligation to pay a claim depends on whether the insured or beneficiary has complied with all policy conditions. This makes the policy a(n)","options":[{"label":"A","text":"agency agreement"},{"label":"B","text":"aleatory agreement"},{"label":"C","text":"contract of good faith"},{"label":"D","text":"conditional contract"}],"correctAnswer":"D","explanation":"The insurer's obligation to pay a claim depends on whether the insured or beneficiary has complied with all policy conditions, making the policy a conditional contract..","explanationPt":"A obrigação da seguradora de pagar um sinistro depende de o segurado ou beneficiário ter cumprido todas as condições da apólice, o que torna a apólice um contrato condicional.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q438","sourceNumber":438,"duplicateIndex":1,"question":"What typically changes at the re-entry option date found in some term life policies?","options":[{"label":"A","text":"beneficiary"},{"label":"B","text":"amount of coverage"},{"label":"C","text":"premium"},{"label":"D","text":"contestable period"}],"correctAnswer":"C","explanation":"answer is \"pr re-entry option gives the insured the opportunity to provide evidence of insurability at the end of the term to qualify to renew the policy at a lower premium.","explanationPt":"A resposta correta é C: o prêmio. Isso está correto porque a opção de \"re-entry\" (readmissão) dá ao segurado a oportunidade de apresentar prova de segurabilidade ao final do prazo, para se qualificar para renovar a apólice com um prêmio mais baixo.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX017","sourceNumber":null,"duplicateIndex":1,"question":"Under the Law of Agency, the principal is considered to be","options":[{"label":"A","text":"the producer"},{"label":"B","text":"the insurer"},{"label":"C","text":"the plan administrator"},{"label":"D","text":"the insured"}],"correctAnswer":"B","explanation":"According to the Law of Agency, the insurer is considered to be the principal.","explanationPt":"A resposta correta é B: a seguradora. Isso está correto porque, de acordo com a Lei de Agência (Law of Agency), a seguradora é considerada o principal.","theme":"General Insurance Concepts","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX018","sourceNumber":null,"duplicateIndex":1,"question":"The following are all elements of a valid contract EXCEPT","options":[{"label":"A","text":"consideration"},{"label":"B","text":"offer and acceptance"},{"label":"C","text":"competent parties"},{"label":"D","text":"written evidence"}],"correctAnswer":"D","explanation":"A valid contract requires all of these things except written evidence.","explanationPt":"A resposta correta é D: evidência escrita. Isso está correto porque um contrato válido exige todos estes elementos, exceto evidência escrita.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q439","sourceNumber":439,"duplicateIndex":1,"question":"A notice of information practices must be given to a policyholder at LEAST every ____ year(s)","options":[{"label":"A","text":"one"},{"label":"B","text":"Two"},{"label":"C","text":"Three"},{"label":"D","text":"four"}],"correctAnswer":"C","explanation":"A notice of information practices must be given to a policyholder at least every three","explanationPt":"A resposta correta é C: três. Isso está correto porque um aviso de práticas de informação deve ser fornecido a um titular de apólice pelo menos a cada três anos.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX019","sourceNumber":null,"duplicateIndex":1,"question":"Purchasing insurance is an example of risk","options":[{"label":"A","text":"transference"},{"label":"B","text":"avoidance"},{"label":"C","text":"retention"},{"label":"D","text":"sharing"}],"correctAnswer":"A","explanation":"Purchasing insurance is an example of risk transference.","explanationPt":"A resposta correta é A: transferência. Isso está correto porque comprar seguro é um exemplo de transferência de risco.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q440","sourceNumber":440,"duplicateIndex":1,"question":"A single premium deferred annuity sometimes contains a bailout feature. Which statement regarding this feature is correct?","options":[{"label":"A","text":"If the interest rate falls below a specified level, the surrender charge is waived"},{"label":"B","text":"If the interest rate rises above a certain level, the surrender charge is waived"},{"label":"C","text":"It allows the Life and Health Guaranty Association to bailout the insolvent insurer"},{"label":"D","text":"A reinsurer will make the remainder of the annuity payments if the original insurance company becomes insolvent"}],"correctAnswer":"A","explanation":"Some annuity contracts allow the owner to withdraw funds without a withdrawal charge if the interest rate falls below a certain level. This is referred to as a \"bail-out\" option. The amount withdrawn may be subject at least in part to income tax and a 10% IRS penalty.","explanationPt":"Alguns contratos de anuidade permitem que o titular saque fundos sem taxa de saque se a taxa de juros cair abaixo de um determinado nível. Isso é chamado de opção de \"bail-out\". O valor sacado pode estar sujeito, ao menos em parte, a imposto de renda e a uma multa de 10% do IRS.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q441","sourceNumber":441,"duplicateIndex":1,"question":"Which of the following is a syndicate established by a group of insurers to share underwriting duties?","options":[{"label":"A","text":"Reinsurer"},{"label":"B","text":"Lloyd's organization"},{"label":"C","text":"NAIC"},{"label":"D","text":"Multi-line insurers"}],"correctAnswer":"B","explanation":"The Lloyd's organization is a syndicate of individuals and companies that individually underwrite insurance. An insurance company can be liable for a producer's unauthorized acts A. only when a felony is involved B. when the agency contract is unclear concerning the authority given ✓ correta C. at anytime D. only if the agency contract is unilateral An insurance company can be liable for a producer's unauthorized acts when the agency contract is vague concerning the authority granted.","explanationPt":"A organização Lloyd's é um sindicato de indivíduos e empresas que subscrevem seguros individualmente. Uma seguradora pode ser responsabilizada pelos atos não autorizados de um produtor A. somente quando envolver um crime grave B. quando o contrato de agência não for claro quanto à autoridade concedida ✓ correta C. a qualquer momento D. somente se o contrato de agência for unilateral Uma seguradora pode ser responsabilizada pelos atos não autorizados de um produtor quando o contrato de agência for vago quanto à autoridade concedida.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q442","sourceNumber":442,"duplicateIndex":1,"question":"Which of the following contracts offer deferred taxation, flexible payments, a guaranteed interest rate, and death benefits equal to the cash value?","options":[{"label":"A","text":"Variable life policy"},{"label":"B","text":"Modified life policy"},{"label":"C","text":"Flexible premium fixed annuity"},{"label":"D","text":"Immediate fixed annuity"}],"correctAnswer":"C","explanation":"A flexible premium fixed annuity offers flexible deposits, deferred taxation, a guaranteed minimum interest rate, and death proceeds equal to the cash value.","explanationPt":"Uma anuidade fixa de prêmio flexível oferece depósitos flexíveis, tributação diferida, uma taxa de juros mínima garantida e valores por morte iguais ao valor em dinheiro.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q443","sourceNumber":443,"duplicateIndex":1,"question":"Which of the following statements about universal life insurance is NOT true?","options":[{"label":"A","text":"Death benefit can be increased"},{"label":"B","text":"Premiums are flexible"},{"label":"C","text":"Universal life insurance normally has a minimum guaranteed cash value for duration of the policy"},{"label":"D","text":"The cash value interest rate must equal or exceed a guaranteed minimum value"}],"correctAnswer":"C","explanation":"All of these statements about universal life insurance are true EXCEPT \"Universal life insurance normally has a minimum guaranteed cash value for duration of the policy\".","explanationPt":"Todas estas afirmações sobre o seguro de vida universal são verdadeiras, EXCETO \"o seguro de vida universal normalmente possui um valor em dinheiro mínimo garantido durante toda a vigência da apólice\".","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q444","sourceNumber":444,"duplicateIndex":1,"question":"What is the effect of the market value adjustment in a market value adjustment annuity?","options":[{"label":"A","text":"Transfers the tax liability to the owner"},{"label":"B","text":"Allows owner to periodically adjust the investment risk"},{"label":"C","text":"Transfers some of the investment risk to the policyowner"},{"label":"D","text":"No effect"}],"correctAnswer":"C","explanation":"A Market Value Adjustment (MVA) can be attached to a deferred annuity that features fixed interest rate guarantees combined with an interest rate adjustment factor that can cause the actual crediting rates to increase or decrease in response to market. Market value adjustments found in some annuity products are meant to shift some of the investment risk to the policyowner.","explanationPt":"Um Ajuste de Valor de Mercado (MVA) pode ser anexado a uma anuidade diferida que oferece garantias de taxa de juros fixa combinadas com um fator de ajuste de taxa de juros que pode fazer com que as taxas de crédito reais aumentem ou diminuam em resposta ao mercado. Os ajustes de valor de mercado encontrados em alguns produtos de anuidade têm o objetivo de transferir parte do risco de investimento para o titular.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q445","sourceNumber":445,"duplicateIndex":1,"question":"When does interest income for a flexible premium deferred annuity get reported for federal income taxes?","options":[{"label":"A","text":"Never"},{"label":"B","text":"After the principal has been exhausted"},{"label":"C","text":"Upon receiving distributions from the contract"},{"label":"D","text":"During the accumulation phase"}],"correctAnswer":"C","explanation":"The portion of the annuity payment that represents interest-earned is taxable. The portion that represents the return of principal is not taxed.","explanationPt":"A parte do pagamento da anuidade que representa os juros ganhos é tributável. A parte que representa o retorno do principal não é tributada.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q446","sourceNumber":446,"duplicateIndex":1,"question":"The beneficiary of a life insurance policy is normally selected by whom?","options":[{"label":"A","text":"Policyowner"},{"label":"B","text":"Contingent beneficiary"},{"label":"C","text":"Estate"},{"label":"D","text":"Insurance company"}],"correctAnswer":"A","explanation":"The beneficiary of a life insurance policy is normally selected by the policyowner.","explanationPt":"O beneficiário de uma apólice de seguro de vida normalmente é escolhido pelo titular da apólice.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q447","sourceNumber":447,"duplicateIndex":1,"question":"Which of the following is a TRUE statement regarding universal life insurance?","options":[{"label":"A","text":"Death benefits are normally taxable"},{"label":"B","text":"Policy loans are not permitted"},{"label":"C","text":"Premiums or face amount cannot be changed"},{"label":"D","text":"Policy indicates how much of each premium is used toward company expenses"}],"correctAnswer":"D","explanation":"Premium payments are separated and paid toward the insurance protection. The loading cost and the remaining balance is used to build the cash value.","explanationPt":"Os pagamentos de prêmio são separados e destinados à proteção do seguro. O custo de carregamento (loading cost) e o saldo restante são usados para acumular o valor em dinheiro.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q448","sourceNumber":448,"duplicateIndex":1,"question":"An officer for a corporation takes out numerous unsecured loans from the company's qualified retirement plan. Which of these rules is the plan in violation of?","options":[{"label":"A","text":"Key employee rule"},{"label":"B","text":"Top heavy rule"},{"label":"C","text":"Vesting rule"},{"label":"D","text":"Exclusive benefit rule"}],"correctAnswer":"D","explanation":"ds Correct. The assets held in a company's qualified retirement plan must be maintained for the exclusive benefit of the employees and their beneficiaries.","explanationPt":"A resposta correta é D: regra do benefício exclusivo. Isso está correto porque os ativos mantidos no plano de aposentadoria qualificado de uma empresa devem ser mantidos exclusivamente em benefício dos funcionários e de seus beneficiários.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX020","sourceNumber":null,"duplicateIndex":1,"question":"In a qualified retirement plan, the yearly contributions to an employee's account","options":[{"label":"A","text":"are not tax-deductible"},{"label":"B","text":"are restricted to minimum levels set by the IRS"},{"label":"C","text":"are restricted to maximum limits set by the IRS"},{"label":"D","text":"must be matched dollar-for-dollar by the employer"}],"correctAnswer":"C","explanation":"Annual limits to an employee's qualified retirement plan are based on maximum limits set by the IRS.","explanationPt":"A resposta correta é C: são restritas a limites máximos estabelecidos pelo IRS. Isso está correto porque os limites anuais para o plano de aposentadoria qualificado de um funcionário são baseados nos limites máximos estabelecidos pelo IRS.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q450","sourceNumber":450,"duplicateIndex":1,"question":"A(n)___ agent may represent several insurers.","options":[{"label":"A","text":"captive"},{"label":"B","text":"free"},{"label":"C","text":"independent"},{"label":"D","text":"career"}],"correctAnswer":"C","explanation":"An independent agent may represent several insurers.","explanationPt":"Um agente independente pode representar várias seguradoras.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q449","sourceNumber":449,"duplicateIndex":1,"question":"The policy provision that permits an employee to change from group life coverage to an individual life policy is called","options":[{"label":"A","text":"the assignment provision"},{"label":"B","text":"conversion provision"},{"label":"C","text":"certificate provision"},{"label":"D","text":"modification provision"}],"correctAnswer":"B","explanation":"The conversion provision allows an employee to change from group coverage to an individual life insurance policy","explanationPt":"A resposta correta é B: cláusula de conversão. Isso está correto porque a cláusula de conversão permite que um funcionário mude da cobertura em grupo para uma apólice individual de seguro de vida.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX021","sourceNumber":null,"duplicateIndex":1,"question":"Which life insurance policy provision prohibits a beneficiary from \"commuting, encumbering, withdrawing, or assigning\" any portion of the proceeds prior to actual receipt from the company?","options":[{"label":"A","text":"Insuring clause"},{"label":"B","text":"Spendthrift clause"},{"label":"C","text":"Nonforfeiture provision"},{"label":"D","text":"Collateral Provision"}],"correctAnswer":"B","explanation":"A spendthrift clause prevents a beneficiary from recklessly spending benefits by requiring the benefits to be paid in fixed amounts or installments over a certain period of time.","explanationPt":"A resposta correta é B: cláusula de proteção contra dilapidação (spendthrift clause). Isso está correto porque essa cláusula impede que o beneficiário gaste os benefícios de forma imprudente, exigindo que sejam pagos em quantias fixas ou parcelas ao longo de um determinado período.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q450-2","sourceNumber":450,"duplicateIndex":2,"question":"An insurance application requires an applicant to make a full, accurate disclosure of the risk factor involved. Using this criteria, an insurance policy is considered what type of contract?","options":[{"label":"A","text":"Aleatory contract"},{"label":"B","text":"Estoppel contract"},{"label":"C","text":"Contract of utmost good faith"},{"label":"D","text":"Unilateral contract"}],"correctAnswer":"C","explanation":"i Correct. A contract of utmost good faith is a minimum standard that requires both the buyer and seller in a transaction to act honestly toward each other and to not mislead or withhold critical information from one another.","explanationPt":"Correto. Um contrato de máxima boa-fé é um padrão mínimo que exige que tanto o comprador quanto o vendedor em uma transação ajam com honestidade um com o outro e não induzam ao erro nem ocultem informações essenciais entre si.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q451","sourceNumber":451,"duplicateIndex":1,"question":"What is the insurer responsible for when a producer is acting within the scope of authority granted in the agency contract?","options":[{"label":"A","text":"All actions by the producer"},{"label":"B","text":"Not responsible for any acts by the producer"},{"label":"C","text":"Responsible for acts that involve misrepresentation only"},{"label":"D","text":"Responsible for acts by the producer that are authority only"}],"correctAnswer":"D","explanation":"The significance of authority (whether express, implied, or apparent) is that it ties the company to the acts and deeds of its producers. The law will view the producer and the company as one and the same when the producer acts within the scope of his/her authority.","explanationPt":"A resposta correta é D: é responsável apenas pelos atos do produtor que estão dentro da autoridade concedida. Isso está correto porque a importância da autoridade (seja expressa, implícita ou aparente) está em vincular a empresa aos atos e ações de seus produtores. A lei considerará o produtor e a empresa como uma só entidade quando o produtor agir dentro do escopo de sua autoridade.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX022","sourceNumber":null,"duplicateIndex":1,"question":"Voluntarily terminating an insurance policy is also known as","options":[{"label":"A","text":"discontinuation"},{"label":"B","text":"elimination"},{"label":"C","text":"estoppel"},{"label":"D","text":"cancellation"}],"correctAnswer":"D","explanation":"The voluntary act of terminating an insurance contract is called cancellation.","explanationPt":"A resposta correta é D: cancelamento. Isso está correto porque o ato voluntário de encerrar um contrato de seguro é chamado de cancelamento.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q452","sourceNumber":452,"duplicateIndex":1,"question":"Which of these annuity contract features is meant to discourage withdrawals and exchanges?","options":[{"label":"A","text":"Annuitization"},{"label":"B","text":"Annual fees"},{"label":"C","text":"Withdrawal penalty"},{"label":"D","text":"Surrender charges"}],"correctAnswer":"D","explanation":"Surrender charges are intended to discourage withdrawals and exchanges in an annuity.","explanationPt":"As taxas de resgate (surrender charges) têm o objetivo de desestimular saques e trocas em uma anuidade.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q453","sourceNumber":453,"duplicateIndex":1,"question":"An annuitant is paid $495 per month until the contract value is exhausted at some undetermined date in the future. Which type of annuity payout option is this?","options":[{"label":"A","text":"Fixed amount"},{"label":"B","text":"Straight life"},{"label":"C","text":"Period certain"},{"label":"D","text":"Installment refund"}],"correctAnswer":"A","explanation":"Under the fixed amount option, the annuitant receives a fixed payment until the contract value is exhausted, regardless of when that will be. If the annuitant dies before the contract is depleted, the beneficiary receives the remainder.","explanationPt":"A resposta correta é A porque, na opção Fixed amount, o annuitant recebe um pagamento fixo, neste caso $495 por mês, até que o valor do contrato seja esgotado. A data final é indefinida porque depende de quanto tempo o saldo levará para acabar. Se o annuitant morrer antes de o contrato ser totalmente esgotado, o beneficiário recebe o valor restante.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX023","sourceNumber":null,"duplicateIndex":1,"question":"In an individual retirement account (IRA), rollover contributions are","options":[{"label":"A","text":"subject to capital gains tax"},{"label":"B","text":"subject to ordinary income tax"},{"label":"C","text":"partially limited by dollar amount"},{"label":"D","text":"unlimited by dollar amount"}],"correctAnswer":"D","explanation":"Rollover contributions to an individual retirement annuity (IRA) are not limited by dollar amount.","explanationPt":"A resposta correta é D: ilimitadas por valor em dólares. Isso está correto porque as contribuições de rollover para uma anuidade de aposentadoria individual (IRA) não são limitadas por valor em dólares.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX024","sourceNumber":null,"duplicateIndex":1,"question":"According to the needs approach, an emergency reserve fund's primary purpose is to","options":[{"label":"A","text":"pay off debt"},{"label":"B","text":"cover the cost of unexpected expenses"},{"label":"C","text":"pay for the cost of life insurance"},{"label":"D","text":"provide a supplemental income source"}],"correctAnswer":"B","explanation":"An emergency reserve fund is designed primarily to cover the cost of unexpected expenses.","explanationPt":"A resposta correta é B: cobrir o custo de despesas inesperadas. Isso está correto porque um fundo de reserva de emergência é criado principalmente para cobrir o custo de despesas inesperadas.","theme":"General Insurance Concepts","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q454","sourceNumber":454,"duplicateIndex":1,"question":"When funds are transferred directly from one IRA to another IRA, what percentage of the tax is withheld?","options":[{"label":"A","text":"10%"},{"label":"B","text":"20%"},{"label":"C","text":"30%"},{"label":"D","text":"None"}],"correctAnswer":"D","explanation":"There is no tax withheld on an IRA transfer it directly involves two IRAs.","explanationPt":"Não há retenção de imposto em uma transferência de IRA quando ela envolve diretamente dois IRAs.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q455","sourceNumber":455,"duplicateIndex":1,"question":"Which of the following situations would allow funds to be deposited into a rollover IRA?","options":[{"label":"A","text":"An individual receives a $100,000 inheritance"},{"label":"B","text":"A family receives $1,000,000 in a wrongful death lawsuit"},{"label":"C","text":"An employee quits her job and receives $50,000 from her qualified plan"},{"label":"D","text":"A policyowner surrenders his life insurance policy's $25,000 cash value"}],"correctAnswer":"C","explanation":"id Correct. An employee who resigns and receives funds from a qualified plan could deposit the available funds into a rollover individual retirement account (IRA).","explanationPt":"Correto. Um funcionário que se demite e recebe fundos de um plano qualificado pode depositar os fundos disponíveis em um IRA de rollover.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q456","sourceNumber":456,"duplicateIndex":1,"question":"What kind of life policy typically offers mortgage protection?","options":[{"label":"A","text":"Whole life"},{"label":"B","text":"Decreasing term"},{"label":"C","text":"Increasing term"},{"label":"D","text":"Level term"}],"correctAnswer":"B","explanation":"A mortgage protection life insurance policy uses a decreasing term policy. As the outstanding loan decreases, so does the amount of term coverage.","explanationPt":"Uma apólice de seguro de vida de proteção de hipoteca (mortgage protection) usa uma apólice de termo decrescente. À medida que o saldo devedor do empréstimo diminui, também diminui o valor da cobertura de termo.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q457","sourceNumber":457,"duplicateIndex":1,"question":"What happens to the purchasing power of benefit payments from a fixed life annuity when the cost of living goes up?","options":[{"label":"A","text":"Increases"},{"label":"B","text":"Decreases"},{"label":"C","text":"Not affected by inflation"},{"label":"D","text":"Tied to stock index"}],"correctAnswer":"B","explanation":"Under a fixed life annuity, the purchasing power decreases when the cost of living goes up because the amount of benefit payments remains fixed. On the flip side, the purchasing power increases when the cost of living goes down.","explanationPt":"A resposta correta é B: diminui. Isso está correto porque, em uma anuidade vitalícia fixa, o poder de compra diminui quando o custo de vida aumenta, já que o valor dos pagamentos de benefício permanece fixo. Por outro lado, o poder de compra aumenta quando o custo de vida diminui.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX025","sourceNumber":null,"duplicateIndex":1,"question":"The law of large numbers enables an insurer to","options":[{"label":"A","text":"predict losses"},{"label":"B","text":"avoid adverse selection"},{"label":"C","text":"classify rates"},{"label":"D","text":"assure company profits"}],"correctAnswer":"A","explanation":"The Law of Large numbers enables an insurer to predict losses.","explanationPt":"A resposta correta é A: prever perdas. Isso está correto porque a lei dos grandes números permite que uma seguradora preveja perdas.","theme":"General Insurance Concepts","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q458","sourceNumber":458,"duplicateIndex":1,"question":"When a large sum of money is used to structure monthly payments, which product is typically used?","options":[{"label":"A","text":"A 401(k) plan"},{"label":"B","text":"A 403(b) plan"},{"label":"C","text":"A deferred annuity"},{"label":"D","text":"An immediate annuity"}],"correctAnswer":"D","explanation":"An immediate annuity is commonly used to structure payments coming from an initial large sum.","explanationPt":"Uma anuidade imediata é comumente usada para estruturar pagamentos a partir de uma grande quantia inicial.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q459","sourceNumber":459,"duplicateIndex":1,"question":"Straight whole life insurance can be accurately described in all of these statements EXCEPT","options":[{"label":"A","text":"Policy protection normally expires at age 65"},{"label":"B","text":"Nonforfeiture values are available to the policyowner"},{"label":"C","text":"Provides level protection with level premiums"},{"label":"D","text":"Cash value loans are permitted"}],"correctAnswer":"A","explanation":"All of the following statements about straight whole life insurance policies are true EXCEPT \"Policy protection normally expires at age 65\".","explanationPt":"Todas estas afirmações sobre apólices de vida inteira comum (straight whole life) são verdadeiras, EXCETO \"a proteção da apólice normalmente expira aos 65 anos\".","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q460","sourceNumber":460,"duplicateIndex":1,"question":"Wyatt is shopping for life insurance and is mainly concerned with the policy's death benefit. Which index should he be looking at when making comparisons?","options":[{"label":"A","text":"Net gain index"},{"label":"B","text":"Net payment cost index"},{"label":"C","text":"Cost surrender index"},{"label":"D","text":"Guaranteed renewable index"}],"correctAnswer":"B","explanation":"The net payment cost index is useful if one's primary concern is the amount of death benefits provided in the policy. It is helpful in comparing future costs, such as in 10 to 20 years, if one will continue to pay premiums and does not take the policy's cash value.","explanationPt":"O índice de custo líquido de pagamento (net payment cost index) é útil se a principal preocupação for o valor dos benefícios por morte oferecidos pela apólice. Ele ajuda a comparar custos futuros, como em 10 a 20 anos, caso a pessoa continue pagando os prêmios e não utilize o valor em dinheiro da apólice.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q461","sourceNumber":461,"duplicateIndex":1,"question":"When does the insured stop making payments under a thirty-payment whole life policy?","options":[{"label":"A","text":"At the time of death or 30 years after the policy's inception, whichever comes first"},{"label":"B","text":"It depends on the performance of the underlying investment account"},{"label":"C","text":"When the cash value surpasses the face amount"},{"label":"D","text":"At age 100"}],"correctAnswer":"A","explanation":"Under a thirty-payment whole life insurance policy, the insured stops paying premiums at the earlier of date of death or 30 years after the policy's inception.","explanationPt":"Em uma apólice de vida inteira com trinta pagamentos (thirty-payment whole life), o segurado para de pagar os prêmios o que ocorrer primeiro: a data da morte ou 30 anos após o início da apólice.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q462","sourceNumber":462,"duplicateIndex":1,"question":"Which of the following is TRUE about a qualified retirement plan that is \"top heavy\"?","options":[{"label":"A","text":"More than 30% of plan assets are in key employee accounts"},{"label":"B","text":"More than 40% of annual additions are for key employee accounts"},{"label":"C","text":"More than 50% of plan assets are in key employee accounts"},{"label":"D","text":"More than 60% of plan assets are in key employee accounts"}],"correctAnswer":"D","explanation":"A plan is considered to be top heavy if more than 60% of plan assets are attributable to \"key employees' as of the last day of the prior plan year.","explanationPt":"Um plano é considerado \"top heavy\" (concentrado no topo) se mais de 60% dos ativos do plano forem atribuíveis a \"funcionários-chave\" no último dia do ano anterior do plano.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q463","sourceNumber":463,"duplicateIndex":1,"question":"During the application process, a statement made by an applicant that becomes part of the contract is considered to be a(n)","options":[{"label":"A","text":"warranty"},{"label":"B","text":"representation"},{"label":"C","text":"waiver"},{"label":"D","text":"exclusion"}],"correctAnswer":"A","explanation":"A warranty is a statement made by the applicant that is guaranteed to be true in every respect and becomes part of the contract.","explanationPt":"Uma garantia (warranty) é uma declaração feita pelo proponente que é garantida como verdadeira em todos os aspectos e passa a fazer parte do contrato.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q464","sourceNumber":464,"duplicateIndex":1,"question":"An arrangement where an individual is authorized to act on behalf of another person or company is established through","options":[{"label":"A","text":"estoppel"},{"label":"B","text":"the law of agency"},{"label":"C","text":"the law of adhesion"},{"label":"D","text":"an aleatory contract"}],"correctAnswer":"B","explanation":"An agency is a situation where an agent has the power to represent and act for another person or company.","explanationPt":"Uma agência é uma situação em que um agente tem o poder de representar e agir em nome de outra pessoa ou empresa.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q465","sourceNumber":465,"duplicateIndex":1,"question":"A life insurance policy that includes a return of premium rider will pay the beneficiary how much upon the insured's death?","options":[{"label":"A","text":"Total premiums paid plus the policy face amount"},{"label":"B","text":"Face amount plus interest accrued"},{"label":"C","text":"Interest accrued plus total premiums paid"},{"label":"D","text":"Face amount minus any outstanding loan balances"}],"correctAnswer":"A","explanation":"A life insurance policy that includes a return of premium rider will pay the face amount plus total premiums paid upon the insured's death.","explanationPt":"Uma apólice de seguro de vida que inclui uma cláusula adicional de devolução de prêmio (return of premium rider) pagará o valor de face mais o total de prêmios pagos na morte do segurado.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q466","sourceNumber":466,"duplicateIndex":1,"question":"Death benefits from a life insurance policy are normally considered to be","options":[{"label":"A","text":"exempt from federal income tax"},{"label":"B","text":"subject to the cost recovery rule"},{"label":"C","text":"subject to attachments from the insured's creditors"},{"label":"D","text":"subject to the value-added tax"}],"correctAnswer":"A","explanation":"Life insurance death proceeds that are paid to a named beneficiary are generally exempt from federal income tax.","explanationPt":"Os valores por morte de seguro de vida pagos a um beneficiário nomeado geralmente são isentos de imposto de renda federal.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q466-2","sourceNumber":466,"duplicateIndex":2,"question":"The highest mortality rate belongs to which group?","options":[{"label":"A","text":"Age 60 females"},{"label":"B","text":"Age 70 males"},{"label":"C","text":"Age 60 males"},{"label":"D","text":"Age 70 females"}],"correctAnswer":"B","explanation":"The group on this list that has the highest mortality rate is age 70 males.","explanationPt":"Nesta lista, o grupo com a maior taxa de mortalidade é o de homens de 70 anos.","theme":"General Insurance Concepts","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q467","sourceNumber":467,"duplicateIndex":1,"question":"During the early years of a whole life insurance policy, the cash value will normally be","options":[{"label":"A","text":"equal to the total premiums paid"},{"label":"B","text":"more than the total premiums paid"},{"label":"C","text":"less than the total premiums paid"},{"label":"D","text":"unavailable as a policy loan"}],"correctAnswer":"C","explanation":"During the early years of a whole life insurance policy, the cash value will normally be less than the total premiums paid.","explanationPt":"A resposta correta é C: menor do que o total dos prêmios pagos. Isso está correto porque, nos primeiros anos de uma apólice de seguro de vida inteira, o valor em dinheiro normalmente será menor do que o total dos prêmios pagos.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX026","sourceNumber":null,"duplicateIndex":1,"question":"A producer working for an insurance company may be personally liable for","options":[{"label":"A","text":"acts performed which are expressed in the agency contract"},{"label":"B","text":"acts performed which are prohibited in the agency contract"},{"label":"C","text":"all actions taken on behalf of the insurer"},{"label":"D","text":"nothing"}],"correctAnswer":"B","explanation":"A producer of an insurer would be personally liable when the producer performs an act which is prohibited in the agency contract.","explanationPt":"A resposta correta é B: atos praticados que são proibidos no contrato de agência. Isso está correto porque um produtor de uma seguradora seria pessoalmente responsável quando pratica um ato proibido pelo contrato de agência.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX027","sourceNumber":null,"duplicateIndex":1,"question":"A life insurance policy's contingent beneficiary is the","options":[{"label":"A","text":"primary person who receives the death benefits if the insured dies"},{"label":"B","text":"person who receives the death benefits if the primary beneficiary dies before the insured"},{"label":"C","text":"person who receives the death benefits if there is no named beneficiary"},{"label":"D","text":"person whose approval is needed before a beneficiary designation is changed"}],"correctAnswer":"B","explanation":"The contingent beneficiary is the person who receives the policy proceeds if the primary beneficiary dies before the insured.","explanationPt":"A resposta correta é B: a pessoa que recebe o benefício por morte caso o beneficiário principal morra antes do segurado. Isso está correto porque o beneficiário contingente é a pessoa que recebe os valores da apólice caso o beneficiário principal morra antes do segurado.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX028","sourceNumber":null,"duplicateIndex":1,"question":"A foreign insurer wishing to conduct business in Massachusetts MUST obtain a","options":[{"label":"A","text":"certificate of authority"},{"label":"B","text":"certificate of compliance"},{"label":"C","text":"certificate of reciprocity"},{"label":"D","text":"certificate of completion"}],"correctAnswer":"A","explanation":"A foreign insurer wishing to conduct business in Massachusetts must obtain a certificate of authority from the Superintendent of Insurance.","explanationPt":"A resposta correta é A: um certificado de autoridade. Isso está correto porque uma seguradora estrangeira que deseja operar em Massachusetts deve obter um certificado de autoridade do Superintendente de Seguros.","theme":"State Law","jurisdiction":"MA","review":false,"reviewFlags":[]},{"id":"Q468","sourceNumber":468,"duplicateIndex":1,"question":"Which type of life insurance policy is best suited for paying off the outstanding balance of a 30-year mortgage in the event of the insured's death?","options":[{"label":"A","text":"30-year endowment"},{"label":"B","text":"30-year increasing term"},{"label":"C","text":"30-year decreasing term"},{"label":"D","text":"30-year whole life"}],"correctAnswer":"C","explanation":"Decreasing term life insurance provides a death benefit that gradually decreases over the span of the policy. Decreasing term life insurance is commonly used for paying off an outstanding mortgage balance in the event of an insured's death (mortgage insurance).","explanationPt":"A resposta correta é C: termo decrescente de 30 anos. Isso está correto porque o seguro de vida temporário decrescente (decreasing term) oferece um benefício por morte que diminui gradualmente ao longo da vigência da apólice. É comumente usado para quitar o saldo devedor de uma hipoteca em caso de morte do segurado (seguro de hipoteca).","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX029","sourceNumber":null,"duplicateIndex":1,"question":"A single-life annuity only has ONE","options":[{"label":"A","text":"annuitant"},{"label":"B","text":"benefit payment"},{"label":"C","text":"premium payment"},{"label":"D","text":"beneficiary"}],"correctAnswer":"A","explanation":"Single-life annuities are characterized by having only one annuitant.","explanationPt":"A resposta correta é A: anuitante. Isso está correto porque as anuidades de vida única (single-life annuity) são caracterizadas por terem apenas um anuitante.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q469","sourceNumber":469,"duplicateIndex":1,"question":"What would be considered an advantage of purchasing term life insurance?","options":[{"label":"A","text":"Cash value can be borrowed against"},{"label":"B","text":"The coverage is permanent"},{"label":"C","text":"Nonforfeiture values are available"},{"label":"D","text":"The initial premium is lower compared to an equivalent amount of whole life coverage"}],"correctAnswer":"D","explanation":"The initial premium is typically lower on a term policy than for same amount of whole life insurance.","explanationPt":"O prêmio inicial normalmente é mais baixo em uma apólice temporária (term) do que no mesmo valor de seguro de vida inteira.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q470","sourceNumber":470,"duplicateIndex":1,"question":"What does a 401(k) plan generally provide its participants?","options":[{"label":"A","text":"Tax-free distributions"},{"label":"B","text":"Salary-deferral distributions"},{"label":"C","text":"Salary-deferral option"},{"label":"D","text":"Adefined retirement benefit"}],"correctAnswer":"C","explanation":"The correct answer A401(k) plan normally provides pai salary-deferral option for contributions to the plan.","explanationPt":"A resposta correta é que um plano 401(k) normalmente oferece uma opção de diferimento salarial (salary-deferral) para as contribuições ao plano.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q471","sourceNumber":471,"duplicateIndex":1,"question":"Which of the following is NOT an example of risk retention?","options":[{"label":"A","text":"Becoming aware of a risk and taking no action"},{"label":"B","text":"Self-insuring a given risk"},{"label":"C","text":"Deciding a business deal is risky but going through with it anyways"},{"label":"D","text":"Not doing a business deal after deciding it would be too risky"}],"correctAnswer":"D","explanation":"Not doing a business deal after deciding it would be too risky is an example of risk avoidance, not retention.","explanationPt":"Não fechar um negócio depois de decidir que seria arriscado demais é um exemplo de evitação de risco (risk avoidance), não de retenção.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q472","sourceNumber":472,"duplicateIndex":1,"question":"Which of these is NOT an advantage of term life insurance?","options":[{"label":"A","text":"The greatest amount of coverage can be provided for the initial premium paid"},{"label":"B","text":"It can be provided as a rider to another policy"},{"label":"C","text":"A cash benefit will be provided if the insured is alive at the end of the policy period"},{"label":"D","text":"Temporary insurance needs can be met"}],"correctAnswer":"C","explanation":"Term life insurance does NOT provide a cash benefit at the end of the policy period.","explanationPt":"O seguro de vida temporário (term life) NÃO oferece um benefício em dinheiro ao final do período da apólice.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q473","sourceNumber":473,"duplicateIndex":1,"question":"Which of the following is an unincorporated association whose members provide coverage for one another?","options":[{"label":"A","text":"Self-insurer"},{"label":"B","text":"Lloyds"},{"label":"C","text":"Reciprocal"},{"label":"D","text":"Surplus lines"}],"correctAnswer":"C","explanation":"A reciprocal association is an unincorporated association whose members provide coverage for one another.","explanationPt":"Uma associação recíproca (reciprocal association) é uma associação não constituída em sociedade cujos membros oferecem cobertura uns aos outros.","theme":"General Insurance Concepts","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q474","sourceNumber":474,"duplicateIndex":1,"question":"According to the IRS, a company may NOT do which of the following in regards to funds in a qualified retirement plan?","options":[{"label":"A","text":"Transfer the funds to a new custodian"},{"label":"B","text":"Invest the funds in mutual funds"},{"label":"C","text":"Transfer vested funds to terminated employees"},{"label":"D","text":"Repossess the funds for business purposes"}],"correctAnswer":"D","explanation":"Under IRS rules, a company may do all of these except \" Repossess the funds for business purposes'","explanationPt":"A resposta correta é D: reaver os fundos para fins comerciais. Isso está correto porque, de acordo com as regras do IRS, uma empresa pode fazer todos estes itens, exceto reaver os fundos do plano para fins comerciais.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX030","sourceNumber":null,"duplicateIndex":1,"question":"A business becoming incorporated is an example of risk ____","options":[{"label":"A","text":"reduction"},{"label":"B","text":"severance"},{"label":"C","text":"retention"},{"label":"D","text":"transfer"}],"correctAnswer":"D","explanation":"Incorporation of a business is an example of risk transfer.","explanationPt":"A resposta correta é D: transferência. Isso está correto porque a incorporação de uma empresa é um exemplo de transferência de risco.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q475","sourceNumber":475,"duplicateIndex":1,"question":"Which life insurance settlement option pays a stated monthly benefit until both principal and interest are exhausted?","options":[{"label":"A","text":"Fixed amount installment option"},{"label":"B","text":"Fixed period installment option"},{"label":"C","text":"Life income option"},{"label":"D","text":"Interest only option"}],"correctAnswer":"A","explanation":"The fixed amount installment option pays a predetermined amount of income at specific intervals until the proceeds and any interest earned are exhausted.","explanationPt":"A resposta correta é A: opção de parcelas de valor fixo (fixed amount installment). Isso está correto porque essa opção paga um valor predeterminado de renda em intervalos específicos até que os valores e quaisquer juros ganhos se esgotem.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX031","sourceNumber":null,"duplicateIndex":1,"question":"An agent whose actions exceed the authority granted by contract is","options":[{"label":"A","text":"acting under apparent authority"},{"label":"B","text":"acting under Implied authority"},{"label":"C","text":"not backed by the insurer"},{"label":"D","text":"backed by the insurer"}],"correctAnswer":"C","explanation":"An agent whose actions exceed the authority granted by contract is not backed by the insurer.","explanationPt":"A resposta correta é C: sem o respaldo da seguradora. Isso está correto porque um agente cujas ações excedem a autoridade concedida pelo contrato não tem o respaldo da seguradora.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q476","sourceNumber":476,"duplicateIndex":1,"question":"Which of the following combinations best describe a universal life insurance policy?","options":[{"label":"A","text":"A mutual fund and an endowment policy"},{"label":"B","text":"A term insurance policy and a whole life policy"},{"label":"C","text":"A modified endowment policy and an annual term insurance policy"},{"label":"D","text":"A flexible premium deposit fund and a monthly renewable term insurance policy"}],"correctAnswer":"D","explanation":"A universal life insurance policy can be described most accurately as a combination of a flexible premium deposit fund and a monthly renewable term insurance policy.","explanationPt":"Uma apólice de seguro de vida universal pode ser descrita, de forma mais precisa, como uma combinação de um fundo de depósito de prêmio flexível e uma apólice de seguro temporário renovável mensalmente.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q477","sourceNumber":477,"duplicateIndex":1,"question":"A teacher recently retired at age 63 and has a tax sheltered annuity (TSA). Periodic deposits total $120,000 and the value of the contract is now worth $200,000. How much is taxed if the current value is surrendered today?","options":[{"label":"A","text":"$200,000"},{"label":"B","text":"$80,000"},{"label":"C","text":"$120,000"},{"label":"D","text":"$0"}],"correctAnswer":"A","explanation":"In this situation, $200,000 will be taxed upon surrender. A tax-sheltered annuity is funded with pre-tax dollars so the entire current value is taxed when surrender. No additional tax penalties are imposed if the owner surrenders the annuity at age 59 1/2 or older.","explanationPt":"A resposta correta é A: $200.000. Isso está correto porque, nesta situação, os $200.000 serão tributados no resgate. Uma anuidade com benefício fiscal (TSA) é financiada com dólares antes de impostos, então todo o valor atual é tributado no resgate. Nenhuma penalidade fiscal adicional é imposta se o titular resgatar a anuidade aos 59 anos e meio ou mais.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX032","sourceNumber":null,"duplicateIndex":1,"question":"The reason for backdating a policy is","options":[{"label":"A","text":"to avoid being considered a substandard risk due to a recent cancer diagnosis"},{"label":"B","text":"to obtain a premium rate based on an earlier age"},{"label":"C","text":"to decrease the face amount"},{"label":"D","text":"to decrease the Contestable period"}],"correctAnswer":"B","explanation":"The purpose of backdating a life insurance policy is to use premiums based on an earlier age.","explanationPt":"A resposta correta é B: obter uma taxa de prêmio baseada em uma idade mais jovem. Isso está correto porque o objetivo de retroagir a data (backdating) de uma apólice de seguro de vida é usar prêmios baseados em uma idade mais jovem.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q478","sourceNumber":478,"duplicateIndex":1,"question":"Which of these is an accurate statement regarding the fixed period settlement option on a life insurance policy?","options":[{"label":"A","text":"A portion of the payments paid to the beneficiary comes from interest calculated on the proceeds of the policy"},{"label":"B","text":"Payment can be adjusted monthly by the beneficiary"},{"label":"C","text":"A portion of the payments paid to the beneficiary comes from interest generated from policy loans"},{"label":"D","text":"Payments are normally guaranteed for 10 years or more"}],"correctAnswer":"A","explanation":"A portion of the payments paid to the beneficiary stems from interest generated from proceeds.","explanationPt":"A resposta correta é A: parte dos pagamentos feitos ao beneficiário provém dos juros calculados sobre os valores da apólice. Isso está correto porque parte dos pagamentos feitos ao beneficiário provém de juros gerados pelos valores.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX033","sourceNumber":null,"duplicateIndex":1,"question":"A life annuity with period certain is characterized as","options":[{"label":"A","text":"guaranteeing benefit payments for a stated period of time after reaching age 65"},{"label":"B","text":"guaranteeing a minimum interest rate"},{"label":"C","text":"guaranteeing lifetime benefit payments for two or more people"},{"label":"D","text":"guaranteeing benefit payments for a stated minimum number of years"}],"correctAnswer":"D","explanation":"The benefits under a life annuity with period certain are guaranteed for a stated minimum number of years.","explanationPt":"A resposta correta é D: garantir pagamentos de benefício por um número mínimo determinado de anos. Isso está correto porque os benefícios de uma anuidade vitalícia com período certo (period certain) são garantidos por um número mínimo determinado de anos.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q479","sourceNumber":479,"duplicateIndex":1,"question":"An employer that offers a qualified retirement plan (as opposed to a non-qualified plan) to its employees is eligible to","options":[{"label":"A","text":"avoid ERISA regulations"},{"label":"B","text":"make tax-deductible contributions to the plan"},{"label":"C","text":"make tax deductible contributions to key employees only"},{"label":"D","text":"make partial tax-deductible contributions to the plan"}],"correctAnswer":"B","explanation":"The advantage gained by providing a qualified retirement plan is the employer's contributions to the plan are tax deductible.","explanationPt":"A vantagem obtida ao oferecer um plano de aposentadoria qualificado é que as contribuições do empregador ao plano são dedutíveis do imposto.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q480","sourceNumber":480,"duplicateIndex":1,"question":"When a producer submits an application that discloses personal information regarding the applicant, who supplies the privacy notice?","options":[{"label":"A","text":"Producer"},{"label":"B","text":"Insurer"},{"label":"C","text":"Underwriter"},{"label":"D","text":"Fiduciary"}],"correctAnswer":"A","explanation":"The producer is responsible for providing the insurance applicant with privacy notices.","explanationPt":"O produtor é responsável por fornecer ao proponente de seguro os avisos de privacidade.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q481","sourceNumber":481,"duplicateIndex":1,"question":"An agent gives a conditional receipt to a client for an insurance policy after collecting the initial premium. When will the policy become effective?","options":[{"label":"A","text":"When the policy is issued"},{"label":"B","text":"The date of policy delivery"},{"label":"C","text":"When the conditions of the receipt are met"},{"label":"D","text":"The date the sales appointment was set"}],"correctAnswer":"C","explanation":"A conditional receipt indicates that certain conditions must be met in order for the insurance coverage to go into effect.","explanationPt":"Um recibo condicional indica que certas condições devem ser cumpridas para que a cobertura do seguro entre em vigor.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q482","sourceNumber":482,"duplicateIndex":1,"question":"Which of the following individuals is eligible to receive a temporary producer license?","options":[{"label":"A","text":"Prospective producer who is waiting to take the state licensing examination"},{"label":"B","text":"An individual who only plans to sell insurance for 6 months to family members and friends"},{"label":"C","text":"The spouse of a retiring producer"},{"label":"D","text":"Adesignated employee who is replacing a deceased producer"}],"correctAnswer":"D","explanation":"In Massachusetts, a designated employee who is replacing a deceased producer would be eligible for a temporary producer's license.","explanationPt":"Em Massachusetts, um funcionário designado que está substituindo um produtor falecido teria direito a uma licença temporária de produtor.","theme":"Producers and Licensing","jurisdiction":"MA","review":false,"reviewFlags":[]},{"id":"Q483","sourceNumber":483,"duplicateIndex":1,"question":"Where will a life insurance policy's proceeds be directed to if all the beneficiaries die before the insured?","options":[{"label":"A","text":"Insured's creditors"},{"label":"B","text":"Beneficiary's estate"},{"label":"C","text":"Insured's estate"},{"label":"D","text":"Court-ordered beneficiary"}],"correctAnswer":"C","explanation":"If all beneficiaries die before the insured dies, the proceeds of a life insurance policy will be paid to the insured's estate.","explanationPt":"Se todos os beneficiários morrerem antes do segurado, os valores de uma apólice de seguro de vida serão pagos ao espólio do segurado.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q484","sourceNumber":484,"duplicateIndex":1,"question":"Which tax is normally associated with an individual's death?","options":[{"label":"A","text":"Excise tax"},{"label":"B","text":"Consumption tax"},{"label":"C","text":"Federal estate tax"},{"label":"D","text":"Ad valorem tax"}],"correctAnswer":"C","explanation":"The Federal estate tax is a tax typically associated with death.","explanationPt":"O imposto federal sobre heranças (estate tax) é um imposto tipicamente associado à morte.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q485","sourceNumber":485,"duplicateIndex":1,"question":"When an annuity contract has been fully surrendered, how will the surrender charges affect the final contract settlement?","options":[{"label":"A","text":"Final contract settlement will be reduced"},{"label":"B","text":"Final contract settlement will be increased"},{"label":"C","text":"Final contract settlement will not be affected"},{"label":"D","text":"Final contract settlement will be held in escrow until surrender charges are paid"}],"correctAnswer":"A","explanation":"If the contract owner fully surrenders an annuity contract, any applicable surrender charges will reduce the final contract settlement.","explanationPt":"Se o titular do contrato resgatar totalmente uma anuidade, quaisquer taxas de resgate aplicáveis reduzirão o valor final da liquidação do contrato.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q486","sourceNumber":486,"duplicateIndex":1,"question":"John received a one-time distribution of $50,000 from his modified endowment contract (MEC). Prior to that, the contract's cash value was $150,000, the contract investment amount was $100,000, and the death benefit was $500,000. What percentage of the $50,000 distribution was taxable as ordinary income?","options":[{"label":"A","text":"0%"},{"label":"B","text":"25%"},{"label":"C","text":"50%"},{"label":"D","text":"100%"}],"correctAnswer":"D","explanation":"Funds withdrawn from an MEC are subject to last-in first-out (LIFO) tax treatment, which assumes that the investment or earnings portion of the contract's values is withdrawn first (making these funds fully taxable as ordinary income).","explanationPt":"A resposta correta é D: 100%. Isso está correto porque os fundos retirados de um MEC estão sujeitos ao tratamento fiscal \"último a entrar, primeiro a sair\" (LIFO), que presume que a parte de investimento ou de rendimentos dos valores do contrato é retirada primeiro, tornando esses fundos totalmente tributáveis como renda ordinária.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX034","sourceNumber":null,"duplicateIndex":1,"question":"A(n) ___ agent is an insurance agent who represents only ONE insurance company.","options":[{"label":"A","text":"exclusive"},{"label":"B","text":"captive"},{"label":"C","text":"domestic"},{"label":"D","text":"inclusive"}],"correctAnswer":"B","explanation":"A captive agent is an insurance agent who only works for one insurance company.","explanationPt":"A resposta correta é B: cativo (captive). Isso está correto porque um agente cativo é um agente de seguros que trabalha apenas para uma seguradora.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX035","sourceNumber":null,"duplicateIndex":1,"question":"Contributions made by an employee to a qualified retirement plan are required to be","options":[{"label":"A","text":"subject to income taxes"},{"label":"B","text":"fully refundable"},{"label":"C","text":"nonforfeitable"},{"label":"D","text":"subject to a vesting schedule"}],"correctAnswer":"D","explanation":"employee's contribution to a qualified retirement plan must be subject to the vesting schedule.","explanationPt":"A resposta correta é D: sujeitas a um cronograma de aquisição de direitos (vesting schedule). Isso está correto porque a contribuição do funcionário a um plano de aposentadoria qualificado deve estar sujeita ao cronograma de aquisição de direitos.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX036","sourceNumber":null,"duplicateIndex":1,"question":"The owner's cost basis for a non-qualified deferred annuity is typically the same as the","options":[{"label":"A","text":"annuity's cash value"},{"label":"B","text":"total premiums paid"},{"label":"C","text":"benefits payable to the annuitant"},{"label":"D","text":"interest earned within the annuity"}],"correctAnswer":"B","explanation":"An owner's cost basis for a deferred annuity is typically the same amount as the premiums paid into the annuity.","explanationPt":"A resposta correta é B: o total de prêmios pagos. Isso está correto porque a base de custo do titular para uma anuidade diferida normalmente é o mesmo valor dos prêmios pagos na anuidade.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q487","sourceNumber":487,"duplicateIndex":1,"question":"How are monthly life annuity benefit payments treated under a tax sheltered annuity (TSA)?","options":[{"label":"A","text":"Taxed as a capital gain during the accumulation period"},{"label":"B","text":"Taxed as ordinary income during the accumulation period"},{"label":"C","text":"Taxed as ordinary income in the year received"},{"label":"D","text":"Received tax-free to all recipients"}],"correctAnswer":"C","explanation":"Monthly life annuity benefit payments received from a tax sheltered annuity (TSA) are taxed as ordinary income in the year received.","explanationPt":"Os pagamentos mensais de benefício de anuidade vitalícia recebidos de uma anuidade com benefício fiscal (TSA) são tributados como renda ordinária no ano em que forem recebidos.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q488","sourceNumber":488,"duplicateIndex":1,"question":"When a ten year renewable term life insurance policy issued at age 45 is renewed, the premium rate will be the current rate for","options":[{"label":"A","text":"Ten year term insurance for a person aged 55"},{"label":"B","text":"Ten year term insurance for a person aged 45"},{"label":"C","text":"Yearly renewable term insurance for a person aged 55."},{"label":"D","text":"Yearly renewable term insurance for a person aged 45"}],"correctAnswer":"A","explanation":"A ten year renewable term policy permits the policyowner to renew the same coverage for another ten years at the end of the first ten-year term. The premiums for the renewal period will be higher than the initial period.","explanationPt":"A resposta correta é A: seguro temporário de dez anos para uma pessoa de 55 anos. Isso está correto porque uma apólice de termo renovável de dez anos permite que o titular renove a mesma cobertura por mais dez anos ao final do primeiro período de dez anos. Os prêmios do período de renovação serão mais altos do que os do período inicial.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX037","sourceNumber":null,"duplicateIndex":1,"question":"An insurable risk requires","options":[{"label":"A","text":"that the chance for both a loss or gain exists"},{"label":"B","text":"the loss must be catastrophic"},{"label":"C","text":"that the chance of loss be calculable"},{"label":"D","text":"that the loss must be incalculable"}],"correctAnswer":"C","explanation":"An insurable risk requires the loss to be calculable or predictable.","explanationPt":"A resposta correta é C: que a chance de perda seja calculável. Isso está correto porque um risco segurável exige que a perda seja calculável ou previsível.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX038","sourceNumber":null,"duplicateIndex":1,"question":"An agent's authority to bind an insurer to an insurance contract may be granted in the","options":[{"label":"A","text":"agent's contract and the insurance company's appointment"},{"label":"B","text":"agent's license and insurance company's certificate of authority"},{"label":"C","text":"buyer's guide and policy summary"},{"label":"D","text":"state guaranty association"}],"correctAnswer":"A","explanation":"The agent's contract and appointment with the insurance company grants the authority to bind an insurer to an insurance contract.","explanationPt":"A resposta correta é A: o contrato do agente e o credenciamento da seguradora. Isso está correto porque o contrato do agente e seu credenciamento com a seguradora concedem a autoridade para vincular a seguradora a um contrato de seguro.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q489","sourceNumber":489,"duplicateIndex":1,"question":"Assets that back the non-guaranteed values of variable life insurance products are held in which account?","options":[{"label":"A","text":"Trust account set up by the insured"},{"label":"B","text":"Separate account set up by the insurer"},{"label":"C","text":"General account of the insurer"},{"label":"D","text":"Money market account"}],"correctAnswer":"B","explanation":"ds Correct. Assets that back the non-guaranteed values of variable life insurance products are held in a separate account set up by the insurer.","explanationPt":"Correto. Os ativos que lastreiam os valores não garantidos dos produtos de seguro de vida variável são mantidos em uma conta separada estabelecida pela seguradora.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q490","sourceNumber":490,"duplicateIndex":1,"question":"Which settlement option makes minimum guaranteed dollar payments over a stated number of years?","options":[{"label":"A","text":"Interest-Only"},{"label":"B","text":"Fixed-Period"},{"label":"C","text":"Fixed-Amount"},{"label":"D","text":"Life Income"}],"correctAnswer":"B","explanation":"The Fixed-Period Proceed Option pays proceeds (including interest and principal) in minimum guaranteed dollar payments over a stated number of years.","explanationPt":"A Opção de Valores por Período Fixo (Fixed-Period Proceed Option) paga os valores (incluindo juros e principal) em pagamentos mínimos garantidos em dólares, ao longo de um número determinado de anos.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q491","sourceNumber":491,"duplicateIndex":1,"question":"Tom has a qualified retirement plan with his employer that is currently considered to be 80% \"vested\". How can this be interpreted?","options":[{"label":"A","text":"20% of the funds are subject to taxes"},{"label":"B","text":"80% of the funds are invested in a separate account"},{"label":"C","text":"If Tom's employment is terminated, 20% of the funds could be forfeited"},{"label":"D","text":"If Tom's employment is terminated, 80% of the funds could be forfeited"}],"correctAnswer":"C","explanation":"answer is \"If Tom's employment is terminated, 20% of the funds could be forfeited' that 20% of the funds could be forfeited if Tom's employment is terminated.","explanationPt":"A resposta é \"Se o emprego de Tom for encerrado, 20% dos fundos poderiam ser perdidos\" — ou seja, 20% dos fundos poderiam ser perdidos caso o emprego de Tom seja encerrado.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q492","sourceNumber":492,"duplicateIndex":1,"question":"Under an adjustable life insurance policy, which of the following may NOT be changed without further underwriting?","options":[{"label":"A","text":"The person insured"},{"label":"B","text":"The period of coverage"},{"label":"C","text":"The payment period"},{"label":"D","text":"The plan of coverage"}],"correctAnswer":"A","explanation":"All of these may normally be changed without further underwriting in an adjustable life insurance policy EXCEPT for \"The individual who is insured\".","explanationPt":"A resposta correta é A: a pessoa segurada. Isso está correto porque todos os demais itens normalmente podem ser alterados sem nova subscrição em uma apólice de seguro de vida ajustável, EXCETO \"o indivíduo que é o segurado\".","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX039","sourceNumber":null,"duplicateIndex":1,"question":"When premiums are determined, one factor would be the expenses of the","options":[{"label":"A","text":"beneficiary"},{"label":"B","text":"insurer"},{"label":"C","text":"policyowner"},{"label":"D","text":"producer"}],"correctAnswer":"B","explanation":"Insurance companies are just like any other business. They have operating expenses which need to be factored into the premiums.","explanationPt":"A resposta correta é B: a seguradora. Isso está correto porque as seguradoras são como qualquer outro negócio: elas têm despesas operacionais que precisam ser consideradas nos prêmios.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q493","sourceNumber":493,"duplicateIndex":1,"question":"Which of the these is NOT a true statement of the war exclusion?","options":[{"label":"A","text":"Civil insurrections apply"},{"label":"B","text":"Prevents an insurer's financial catastrophe"},{"label":"C","text":"Typically applies to declared and undeclared wars"},{"label":"D","text":"War risk is typically uninsurable"}],"correctAnswer":"A","explanation":"Civil insurrections fall under an illegal act or felony, which are typically excluded from coverage as well.","explanationPt":"As insurreições civis se enquadram como um ato ilegal ou crime grave, os quais também são tipicamente excluídos da cobertura.","theme":"State Law","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q494","sourceNumber":494,"duplicateIndex":1,"question":"Which statement is INCORRECT concerning a tax-sheltered annuity (TSA)?","options":[{"label":"A","text":"Participants make payments from salary reductions"},{"label":"B","text":"Normally used by charitable, educational, and religious organizations"},{"label":"C","text":"Also known as 403(b) plans"},{"label":"D","text":"Annual investment gains are included in participant's gross income"}],"correctAnswer":"D","explanation":"The investment gains are actually deferred in a tax-sheltered annuity.","explanationPt":"A resposta correta é D: os ganhos de investimento anuais são incluídos na renda bruta do participante. Isso está correto porque, na verdade, os ganhos de investimento são diferidos em uma anuidade com benefício fiscal (TSA) — por isso essa afirmação é a incorreta.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX040","sourceNumber":null,"duplicateIndex":1,"question":"A life insurance producer's underwriting duties may include","options":[{"label":"A","text":"approving or declining a life insurance application"},{"label":"B","text":"seeking additional information requested by the insurance company"},{"label":"C","text":"ordering an MIB report"},{"label":"D","text":"determining the rate classification of the applicant"}],"correctAnswer":"B","explanation":"Underwriting responsibilities of the life insurance producer include seeking additional information requested by the insurer.","explanationPt":"A resposta correta é B: buscar informações adicionais solicitadas pela seguradora. Isso está correto porque as responsabilidades de subscrição do produtor de seguro de vida incluem buscar informações adicionais solicitadas pela seguradora.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q495","sourceNumber":495,"duplicateIndex":1,"question":"An insurance application requires an applicant to make a full, accurate disclosure of the risk factor involved. Using this criteria, an insurance policy is considered what type of contract?","options":[{"label":"A","text":"Aleatory contract"},{"label":"B","text":"Estoppel contract"},{"label":"C","text":"Contract of utmost good faith"},{"label":"D","text":"Unilateral contract"}],"correctAnswer":"C","explanation":"A contract of utmost good faith is a minimum standard that requires both the buyer and seller in a transaction to act honestly toward each other and to not mislead or withhold critical information from one another.","explanationPt":"Um contrato de máxima boa-fé é um padrão mínimo que exige que tanto o comprador quanto o vendedor em uma transação ajam com honestidade um com o outro e não induzam ao erro nem ocultem informações essenciais entre si.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q496","sourceNumber":496,"duplicateIndex":1,"question":"Christopher is issued an insurance policy that contains an attached agreement which alters the terms of the policy. This attached agreement is called a(n)","options":[{"label":"A","text":"extension"},{"label":"B","text":"endorsement"},{"label":"C","text":"sanction"},{"label":"D","text":"restriction"}],"correctAnswer":"B","explanation":"An endorsement is a written form attached to an insurance policy that alters the policy's coverage, terms, or conditions. Sometimes called a rider.","explanationPt":"A resposta correta é B: endosso (endorsement). Isso está correto porque um endosso é um formulário escrito anexado a uma apólice de seguro que altera a cobertura, os termos ou as condições da apólice. Às vezes também é chamado de rider.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX041","sourceNumber":null,"duplicateIndex":1,"question":"Giving up a known right on a voluntary basis is called a(n)","options":[{"label":"A","text":"disclaimer"},{"label":"B","text":"estoppel"},{"label":"C","text":"waiver"},{"label":"D","text":"surrender"}],"correctAnswer":"C","explanation":"Waiver is defined as the intentional and voluntary giving up of a known right.","explanationPt":"A resposta correta é C: renúncia (waiver). Isso está correto porque a renúncia (waiver) é definida como o ato intencional e voluntário de abrir mão de um direito conhecido.","theme":"General Insurance Concepts","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q497","sourceNumber":497,"duplicateIndex":1,"question":"When a deferred annuity is surrendered, who must sign the authorization to do so?","options":[{"label":"A","text":"Owner"},{"label":"B","text":"Annuitant and beneficiary"},{"label":"C","text":"Annuitant"},{"label":"D","text":"All parties involved"}],"correctAnswer":"A","explanation":"The contract owner exclusively has the power to surrender the cash value of an annuity.","explanationPt":"O titular do contrato tem o poder exclusivo de resgatar o valor em dinheiro de uma anuidade.","theme":"Annuities","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q498","sourceNumber":498,"duplicateIndex":1,"question":"Which statement concerning an adjustable life insurance policy is FALSE?","options":[{"label":"A","text":"Cash surrender is possible"},{"label":"B","text":"Evidence of insurability is required when there is a change in premium"},{"label":"C","text":"Combines term and permanent insurance into a single plan"},{"label":"D","text":"An extra premium paid is allowable"}],"correctAnswer":"B","explanation":"All of these statements about an adjustable life insurance policy are true EXCEPT \"Evidence of insurability is required when there is a change in premium\".","explanationPt":"Todas estas afirmações sobre uma apólice de seguro de vida ajustável são verdadeiras, EXCETO \"é exigida prova de segurabilidade quando há uma mudança no prêmio\".","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q499","sourceNumber":499,"duplicateIndex":1,"question":"A business may purchase an annuity for all of the following reasons EXCEPT","options":[{"label":"A","text":"Structuring a liability settlement payment"},{"label":"B","text":"informally funding a non-qualified deferred compensation plan"},{"label":"C","text":"Accumulating assets on a tax-deferred basis"},{"label":"D","text":"Providing a pension to employees"}],"correctAnswer":"B","explanation":"Business corporations may use annuities for all of these purposes EXCEPT informally funding a non-qualified deferred compensation plan.","explanationPt":"Empresas comerciais podem usar anuidades para todos estes fins, EXCETO financiar informalmente um plano de compensação diferida não qualificado.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q500","sourceNumber":500,"duplicateIndex":1,"question":"The______ has the ability to examine the records of authorized insurers because of the powers granted through state statutes.","options":[{"label":"A","text":"Superintendent"},{"label":"B","text":"Governor"},{"label":"C","text":"Attorney General"},{"label":"D","text":"State Inspector"}],"correctAnswer":"A","explanation":"The Superintendent has the ability to examine the records of authorized insurers because of the powers granted through state statutes.","explanationPt":"O Superintendente tem a capacidade de examinar os registros das seguradoras autorizadas devido aos poderes concedidos pelas leis estaduais.","theme":"State Law","jurisdiction":"MA","review":false,"reviewFlags":[]},{"id":"Q501","sourceNumber":501,"duplicateIndex":1,"question":"Insurance is NOT characterized as which of the following?","options":[{"label":"A","text":"Transference of risk"},{"label":"B","text":"Pooling of premium dollars"},{"label":"C","text":"Method of risk management"},{"label":"D","text":"As the number of insureds increase the number of losses decrease"}],"correctAnswer":"D","explanation":"All of these are characteristics of insurance EXCEPT \"As the number of insureds increase the number of losses decrease\".","explanationPt":"Todas estas são características do seguro, EXCETO \"à medida que o número de segurados aumenta, o número de perdas diminui\".","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q502","sourceNumber":502,"duplicateIndex":1,"question":"An insurance contract may be voided if a misrepresentation found on the application is determined to be","options":[{"label":"A","text":"conditional"},{"label":"B","text":"aleatory"},{"label":"C","text":"material"},{"label":"D","text":"intentional"}],"correctAnswer":"C","explanation":"An insurer can void an insurance policy if a misrepresentation on the application is found to be material.","explanationPt":"Uma seguradora pode anular uma apólice de seguro se uma declaração falsa na proposta for considerada material.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q503","sourceNumber":503,"duplicateIndex":1,"question":"An applicant submits a life insurance application where an investigative consumer report is used in the underwriting process. Which of these statements is true?","options":[{"label":"A","text":"Applicant can determine which items in the report to leave out"},{"label":"B","text":"Insurer can obtain a copy of this report without the applicant's knowledge"},{"label":"C","text":"Fee for the report is typically paid by the applicant"},{"label":"D","text":"Applicant has a right to receive a copy of the report"}],"correctAnswer":"D","explanation":". When an investigative consumer report is used in connection with an insurance application, the applicant has the right to receive a copy of the report.","explanationPt":"Quando um relatório investigativo do consumidor é usado em conexão com uma proposta de seguro, o proponente tem o direito de receber uma cópia do relatório.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q504","sourceNumber":504,"duplicateIndex":1,"question":"What happens when a policyowner borrows against the cash value of his life insurance policy?","options":[{"label":"A","text":"The policy proceeds would be reduced by the outstanding loan balance"},{"label":"B","text":"No additional loans can be taken out in the future"},{"label":"C","text":"The amount borrowed is added to the policyowner's gross income for tax purposes"},{"label":"D","text":"The interest on the loan is tax-deductible"}],"correctAnswer":"A","explanation":"If a life insurance policyowner borrows against the cash value of a policy, the outstanding loan balance is deducted from the policy proceeds.","explanationPt":"A resposta correta é A: os valores da apólice seriam reduzidos pelo saldo do empréstimo pendente. Isso está correto porque, se o titular de uma apólice de seguro de vida tomar emprestado contra o valor em dinheiro de uma apólice, o saldo do empréstimo pendente é deduzido dos valores da apólice.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"QX042","sourceNumber":null,"duplicateIndex":1,"question":"The death proceeds of a credit life insurance policy are typically paid to the","options":[{"label":"A","text":"borrower"},{"label":"B","text":"lender"},{"label":"C","text":"annuitant"},{"label":"D","text":"borrower's dependents"}],"correctAnswer":"B","explanation":"Credit life insurance is designed to cover the life of a debtor. The beneficiary of such a policy is usually the lender.","explanationPt":"A resposta correta é B: o credor. Isso está correto porque o seguro de vida de crédito é projetado para cobrir a vida de um devedor. O beneficiário de tal apólice geralmente é o credor.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q505","sourceNumber":505,"duplicateIndex":1,"question":"Which term describes the elimination of a hazard?","options":[{"label":"A","text":"Risk avoidance"},{"label":"B","text":"Risk retention"},{"label":"C","text":"Risk transference"},{"label":"D","text":"Risk pooling"}],"correctAnswer":"A","explanation":"Eliminating a hazard is an example of risk avoidance.","explanationPt":"Eliminar um perigo (hazard) é um exemplo de evitação de risco (risk avoidance).","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q506","sourceNumber":506,"duplicateIndex":1,"question":"When an individual is planning to protect his family with life insurance, one method of doing so is called needs analysis. What exactly does needs analysis involve?","options":[{"label":"A","text":"Identifies the needs of an individual and the individual's dependents"},{"label":"B","text":"Takes into account the present value of future income earned by the breadwinner"},{"label":"C","text":"Places a dollar value on the life of the individual"},{"label":"D","text":"Establishes the investment risk level acceptable to the individual"}],"correctAnswer":"A","explanation":"Needs analysis is a method of life insurance planning which identifies the needs of an individual and the individual's dependent.","explanationPt":"A análise de necessidades (needs analysis) é um método de planejamento de seguro de vida que identifica as necessidades de um indivíduo e de seus dependentes.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q507","sourceNumber":507,"duplicateIndex":1,"question":"Which statement concerning a decreasing term life policy is accurate?","options":[{"label":"A","text":"Cash value decreases over the policy period"},{"label":"B","text":"Premium decreases over the policy period"},{"label":"C","text":"Face amount decreases over the policy period"},{"label":"D","text":"Face amount stays the same over the policy period"}],"correctAnswer":"C","explanation":"With a decreasing term policy, the face amount of the policy decreases throughout the policy period. Mortgage insurance is the most common use of decreasing term insurance.","explanationPt":"Em uma apólice de termo decrescente, o valor de face da apólice diminui ao longo do período da apólice. O seguro de hipoteca é o uso mais comum do seguro temporário decrescente.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q508","sourceNumber":508,"duplicateIndex":1,"question":"Group life plans sold in Massachusetts typically contain a conversion option. If the insured elects this option, the new policy","options":[{"label":"A","text":"does NOT require evidence of insurability"},{"label":"B","text":"requires evidence of insurability"},{"label":"C","text":"is in force for up to 5 years"},{"label":"D","text":"does NOT require premium payments from the insured"}],"correctAnswer":"A","explanation":"When an insured under a group life insurance plan in Massachusetts elects the conversion option, the new policy is issued without requiring evidence of insurability.","explanationPt":"Quando um segurado sob um plano de seguro de vida em grupo em Massachusetts opta pela opção de conversão, a nova apólice é emitida sem exigir prova de segurabilidade.","theme":"State Law","jurisdiction":"MA","review":false,"reviewFlags":[]},{"id":"Q509","sourceNumber":509,"duplicateIndex":1,"question":"Insurable interest involves what assumption?","options":[{"label":"A","text":"Insurable interest must exist during the entire life of the insured"},{"label":"B","text":"One person gains from the death of another person"},{"label":"C","text":"One person benefits from another person's continued life"},{"label":"D","text":"Insurable interest must only exist at the time of the insured's death"}],"correctAnswer":"C","explanation":"To have insurable interest in the life of another person, an individual must have a reasonable expectation of benefiting from the other person's continued life.","explanationPt":"Para ter interesse segurável na vida de outra pessoa, um indivíduo deve ter uma expectativa razoável de se beneficiar da continuidade da vida dessa pessoa.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q510","sourceNumber":510,"duplicateIndex":1,"question":"What minimum percentage of all eligible employees must participate in a group life insurance plan if the premiums are completely paid for by the employer?","options":[{"label":"A","text":"0%"},{"label":"B","text":"50%"},{"label":"C","text":"75%"},{"label":"D","text":"100%"}],"correctAnswer":"D","explanation":"If group life insurance premiums are completely paid for by the employer, the minimum percent of eligible employees required to be covered is 100%.","explanationPt":"Se os prêmios do seguro de vida em grupo forem totalmente pagos pelo empregador, o percentual mínimo de funcionários elegíveis exigido para serem cobertos é de 100%.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q511","sourceNumber":511,"duplicateIndex":1,"question":"According to the law of large numbers, how would losses be affected if the number of similar insured units increases?","options":[{"label":"A","text":"The higher the exposure, the higher the cost of each loss"},{"label":"B","text":"No effect on predicting losses"},{"label":"C","text":"Predictability of losses will be improved"},{"label":"D","text":"Ability to predict losses decreases"}],"correctAnswer":"C","explanation":"Based on the law of large numbers, as the number of similar insured units increases, predictability of losses improves.","explanationPt":"Com base na lei dos grandes números, à medida que o número de unidades seguradas semelhantes aumenta, a previsibilidade das perdas melhora.","theme":"General Insurance Concepts","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q512","sourceNumber":512,"duplicateIndex":1,"question":"How long can an insurer legally defer paying the cash value of a surrendered life insurance policy?","options":[{"label":"A","text":"2 months"},{"label":"B","text":"4 months"},{"label":"C","text":"6 months"},{"label":"D","text":"12 months"}],"correctAnswer":"C","explanation":"The maximum length of time a life insurance company may legally defer paying the cash value of a surrendered policy is normally six months.","explanationPt":"O período máximo de tempo em que uma seguradora pode legalmente adiar o pagamento do valor em dinheiro de uma apólice resgatada normalmente é de seis meses.","theme":"Policy Provisions","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q513","sourceNumber":513,"duplicateIndex":1,"question":"Which of the following is NOT an objective of the National Association of Insurance Commissioners?","options":[{"label":"A","text":"Encourage uniformity in state insurance laws"},{"label":"B","text":"Protect the interest of policyowners and consumers"},{"label":"C","text":"Regulate state insurance commissioners"},{"label":"D","text":"Promote efficiency in the administration of state insurance laws"}],"correctAnswer":"C","explanation":"All of these are roles provided by the National Association of Insurance Commissioners EXCEPT \"Regulate state insurance commissioners\".","explanationPt":"Todos estes são papéis desempenhados pela National Association of Insurance Commissioners, EXCETO \"regular os comissários estaduais de seguros\".","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q514","sourceNumber":514,"duplicateIndex":1,"question":"The maximum prison sentence given under federal law for unfair and deceptive insurance practices is","options":[{"label":"A","text":"15 years"},{"label":"B","text":"10 years"},{"label":"C","text":"5 years"},{"label":"D","text":"1 year"}],"correctAnswer":"A","explanation":"15 years is the maximum penalty period for conviction of unfair and deceptive insurance practices.","explanationPt":"15 anos é o período máximo de penalidade para condenação por práticas de seguro desleais e enganosas.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q515","sourceNumber":515,"duplicateIndex":1,"question":"Who normally pays the premiums for group credit life insurance?","options":[{"label":"A","text":"Creditor and borrower share the cost equally"},{"label":"B","text":"Borrower"},{"label":"C","text":"Creditor"},{"label":"D","text":"Beneficiary"}],"correctAnswer":"B","explanation":"The borrower typically pays the premiums on any credit life insurance policy.","explanationPt":"O mutuário normalmente paga os prêmios de qualquer apólice de seguro de vida de crédito.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q516","sourceNumber":516,"duplicateIndex":1,"question":"Use of XYZ Insurance Company brochures, business cards, and rating guides is an example of","options":[{"label":"A","text":"Expresses authority"},{"label":"B","text":"Implied authority"},{"label":"C","text":"Apparent authority"},{"label":"D","text":"Fiduciary duty"}],"correctAnswer":"C","explanation":"Apparent authority is what a third party (such as a member of the public) assumes an agent has, based on the actions or words of the principal. By supplying the agent with business cards, brochures, and rating guides, the insurance ompany has given the impression that it supports the words and actions of its agent.","explanationPt":"A autoridade aparente é o que um terceiro (como um membro do público) presume que um agente possui, com base nas ações ou palavras do principal. Ao fornecer ao agente cartões de visita, folhetos e guias de classificação, a seguradora deu a impressão de que apoia as palavras e ações de seu agente.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q517","sourceNumber":517,"duplicateIndex":1,"question":"Which of the following is NOT subject to the promise to pay in an insuring clause?","options":[{"label":"A","text":"How the premium is calculated"},{"label":"B","text":"Policy provisions"},{"label":"C","text":"Policy conditions"},{"label":"D","text":"Policy exclusions"}],"correctAnswer":"A","explanation":"An insuring clause might state that the promise to pay is subject to any of these EXCEPT how the premium is determined.","explanationPt":"Uma cláusula de seguro (insuring clause) pode estabelecer que a promessa de pagamento está sujeita a qualquer um destes itens, EXCETO a forma como o prêmio é determinado.","theme":"Underwriting and Applications","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q518","sourceNumber":518,"duplicateIndex":1,"question":"A contract is considered void in all of the following situations EXCEPT","options":[{"label":"A","text":"When one party is a minor"},{"label":"B","text":"When consideration is unequal"},{"label":"C","text":"When consideration is incomplete"},{"label":"D","text":"When agreement cannot be reached between parties"}],"correctAnswer":"B","explanation":"An aleatory contract involves the possibility of unequal consideration and does not make it voidable.","explanationPt":"Um contrato aleatório envolve a possibilidade de contraprestação desigual e isso não o torna anulável.","theme":"Producers and Licensing","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q519","sourceNumber":519,"duplicateIndex":1,"question":"What qualifies as acceptance of an insurance contract offer?","options":[{"label":"A","text":"Adeclined policy"},{"label":"B","text":"An issued policy"},{"label":"C","text":"The application and initial premium"},{"label":"D","text":"The initial premium only"}],"correctAnswer":"B","explanation":"An issued policy signifies acceptance of an offer of an insurance contract.","explanationPt":"Uma apólice emitida indica a aceitação de uma oferta de contrato de seguro.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q520","sourceNumber":520,"duplicateIndex":1,"question":"Ambiguities in insurance contracts are typically interpreted in favor of the insured. This rule is referred to as","options":[{"label":"A","text":"Subrogation"},{"label":"B","text":"Reasonable expectations"},{"label":"C","text":"Insurable interest"},{"label":"D","text":"Adhesion"}],"correctAnswer":"B","explanation":"Reasonable expectations\" is a legal principle that reinforces the rule that ambiguities in insurance contracts should be interpreted in favor of the policyholder.","explanationPt":"\"Expectativas razoáveis\" é um princípio jurídico que reforça a regra de que ambiguidades em contratos de seguro devem ser interpretadas em favor do segurado.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q521","sourceNumber":521,"duplicateIndex":1,"question":"Which of these statements is NOT a characteristic of the law of large numbers?","options":[{"label":"A","text":"Individual losses can be predicted based on past experience"},{"label":"B","text":"Group losses can be predicted based on past experience"},{"label":"C","text":"Losses can be predicted in large groups with a higher degree of accuracy"},{"label":"D","text":"Rates can be calculated to compensate for losses"}],"correctAnswer":"D","explanation":"The law of large numbers states that larger groups provide better loss predictions. The higher the exposure, the more likely the event can be predicted.","explanationPt":"A lei dos grandes números afirma que grupos maiores fornecem melhores previsões de perdas. Quanto maior a exposição, mais provável é que o evento possa ser previsto.","theme":"State Law","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q522","sourceNumber":522,"duplicateIndex":1,"question":"Which of these policies is considered a whole life policy?","options":[{"label":"A","text":"Credit life"},{"label":"B","text":"Single premium life"},{"label":"C","text":"Renewable life"},{"label":"D","text":"Convertible life"}],"correctAnswer":"B","explanation":"A single-premium life policy is considered a type of whole life insurance","explanationPt":"Uma apólice de vida com prêmio único é considerada um tipo de seguro de vida inteira.","theme":"Life Insurance Policies","jurisdiction":"GENERAL","review":false,"reviewFlags":[]},{"id":"Q523","sourceNumber":523,"duplicateIndex":1,"question":"What is the maximum number of employees (earning at least $5,000) that an employer can have in order to start a SIMPLE retirement plan?","options":[{"label":"A","text":"25"},{"label":"B","text":"50"},{"label":"C","text":"100"},{"label":"D","text":"250"}],"correctAnswer":"C","explanation":"An employer can have a maximum of 100 employees earning at least $5,000 to be eligible for a SIMPLE retirement plan.","explanationPt":"Um empregador pode ter no máximo 100 funcionários ganhando pelo menos $5.000 para ser elegível para um plano de aposentadoria SIMPLE.","theme":"Retirement and Taxation","jurisdiction":"GENERAL","review":false,"reviewFlags":[]}]};
